    if metadata is not None and not isinstance(metadata, dict):
        raise ValueError("metadata must be a dictionary")

    if dehydration_hooks is not None and not isinstance(dehydration_hooks, dict):
        raise ValueError("dehydration_hooks must be a dictionary")

    if hydration_hooks is not None and not isinstance(hydration_hooks, dict):
        raise ValueError("hydration_hooks must be a dictionary")

    # --- Build the BEGIN payload -------------------------------------------------------
    payload = {}
    if mode is not None:
        payload["mode"] = mode
    if bookmarks is not None:
        payload["bookmarks"] = list(bookmarks)
    if metadata is not None:
        payload["metadata"] = metadata
    if timeout is not None:
        payload["timeout"] = timeout
    if db is not None:
        payload["database"] = db
    if imp_user is not None:
        payload["impersonated_user"] = imp_user

    # --- Manage hook dictionaries (store them if the session supports it) -------------
    if dehydration_hooks:
        if hasattr(self, "_dehydration_hooks"):
            self._dehydration_hooks.update(dehydration_hooks)
        else:
            self._dehydration_hooks = dehydration_hooks
    if hydration_hooks:
        if hasattr(self, "_hydration_hooks"):
            self._hydration_hooks.update(hydration_hooks)
        else:
            self._hydration_hooks = hydration_hooks

    # --- Append the BEGIN message to the output queue ---------------------------------
    queue_attr = None
    if hasattr(self, "_output"):
