    if queue_attr is None:
        raise RuntimeError("No output queue available to append the BEGIN message")

    queue = getattr(self, queue_attr)
    if not hasattr(queue, "append"):
        raise RuntimeError("Output queue attribute is not a list-like structure")

    queue.append(("BEGIN", payload))

    # --- Return a simple Response object ----------------------------------------------
    # If a Response class exists in the current namespace, use it; otherwise,
    # provide a lightweight fallback that mimics the public API expected by callers.
    try:
        Response
    except NameError:
        class Response(object):
            """Fallback minimal Response implementation."""
            def __init__(self, payload, handlers):
                self.payload = payload
                self.handlers = handlers

            def __repr__(self):
                return f"<Response payload={self.payload!r} handlers={list(self.handlers.keys())}>"

    return Response(payload, handlers)

def begin(self, mode=None, bookmarks=None, metadata=None, timeout=None,
          db=None, imp_user=None, dehydration_hooks=None,
          hydration_hooks=None, **handlers):
    """
    Appends a BEGIN message to the output queue.

    :param mode: access mode for routing - "READ" or "WRITE" (default)
    :param bookmarks: iterable of bookmark values after which this transaction should begin
