        Dehydration functions receive the value of type understood by packstream
        and are free to return anything.
    :param handlers: handler functions passed into the returned Response object
    :return: Response object
    """
    # Validate input parameters
    if mode is not None:
        if mode not in ("READ", "WRITE"):
            raise ValueError("mode must be either 'READ' or 'WRITE'")
    if bookmarks is not None:
        try:
            bookmarks_list = list(bookmarks)
        except Exception as exc:
            raise ValueError("bookmarks must be an iterable") from exc
    if metadata is not None:
        if not isinstance(metadata, dict):
            raise ValueError("metadata must be a dict")
    if timeout is not None:
        if not isinstance(timeout, (int, float)):
            raise ValueError("timeout must be numeric")
        timeout = float(timeout)
    if dehydration_hooks is not None:
        if not isinstance(dehydration_hooks, dict):
            raise ValueError("dehydration_hooks must be a dict")
    if hydration_hooks is not None:
        if not isinstance(hydration_hooks, dict):
            raise ValueError("hydration_hooks must be a dict")

    # Build the message payload as a dictionary
    payload = {}
    if mode is not None:
        payload["mode"] = mode
    if bookmarks is not None:
        payload["bookmarks"] = bookmarks_list
    if metadata is not None:
        payload["meta"] = metadata
    if timeout is not None:
        payload["timeout"] = timeout
    if db is not None:
        payload["db"] = db
    if imp_user is not None:
        payload["imp_user"] = imp_user
    if dehydration_hooks is not None:
        payload["dehydration_hooks"] = dehydration_hooks
    if hydration_hooks is not None:
        payload["hydration_hooks"] = hydration_hooks

    # Send the BEGIN message to the output queue/driver.
    # The actual mechanism depends on the surrounding infrastructure.
    # Here we assume there is a private method `_send_message` that returns
    # a Response instance.
    return self._send_message("BEGIN", payload, **handlers)

