def _inline_r_setup(code: str) -> str:
    """Some behaviour of R cannot be configured via env variables, but can
    only be configured via R options once R has started. These are set here.
    """
    if not isinstance(code, str):
        raise ValueError("code must be a string")
    try:
        import rpy2.robjects as ro
    except Exception:
        # rpy2 not available; return code unchanged
        return code
    # Set common R options that cannot be controlled by environment variables
    try:
        ro.r("options(warn = -1, scipen = 999, digits = 15)")
    except Exception:
        # If setting options fails, ignore and continue
        pass
    return code

def _shuffled(seq: Sequence[str]) -> list[str]:
    """Deterministically shuffle"""
    try:
        items = list(seq)
    except Exception as e:
        raise TypeError("Expected a sequence of strings") from e

    for x in items:
        if not isinstance(x, str):
            raise TypeError("All items in sequence must be of type str")

    n = len(items)
    seed = sum(ord(ch) for s in items for ch in s)
    for i in range(n - 1, 0, -1):
        seed = (seed * 9301 + 49297) % 233280
        j = seed % (i + 1)
        items[i], items[j] = items[j], items[i]
    return items

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    import re
    if not s:
        return ()
    # Extract all digit sequences from the string and convert them to integers.
    # This method is intentionally simple and does not support complex
    # semantic versioning nuances such as prerelease or build metadata.
    parts = re.findall(r'\d+', s)
    return tuple(int(part) for part in parts)

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    if not isinstance(s, str):
        raise TypeError("s must be a string")
    import re
    # Split on any non-digit characters and convert the numeric parts to ints
    parts = [int(x) for x in re.split(r'\D+', s) if x]
    if not parts:
        raise ValueError("No numeric components found in the version string")
    return tuple(parts)

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    import re
    if not isinstance(s, str):
        raise TypeError(f"Expected a string, got {type(s).__name__}")
    # Split on any non-digit characters such as dots or hyphens
    parts = re.split(r'[^0-9]+', s)
    nums = []
    for part in parts:
        if part == '':
            continue
        try:
            nums.append(int(part))
        except ValueError:
            # ignore segments that cannot be converted to int
            continue
    return tuple(nums)

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison

    Converts a version string into a tuple of integers for simple comparison.
    Non-numeric parts are ignored.

    Parameters:
        s (str): The version string, e.g. '1.2.3', 'v1.0-rc', '2.0.0-beta1'.

    Returns:
        tuple[int, ...]: A tuple of integer components, e.g. (1, 2, 3).

    Notes:
        - Empty or non-numeric strings return an empty tuple.
        - Leading/trailing whitespace is ignored.
    """
    if not isinstance(s, str):
        raise TypeError("parse_version expects a string input")

    s = s.strip()
    if not s:
        return ()

    parts = []
    buf = ""
    for ch in s:
        if ch.isdigit():
            buf += ch
        else:
            if buf:
                parts.append(int(buf))
                buf = ""
    if buf:  # append the last accumulated number
        parts.append(int(buf))

    return tuple(parts)

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    if not isinstance(s, str):
        raise TypeError("parse_version expects a string, got {}".format(type(s).__name__))
    parts = []
    for part in s.strip().split('.'):
        part = part.strip()
        if not part:
            parts.append(0)
            continue
        num_str = ''.join(ch for ch in part if ch.isdigit())
        if num_str:
            parts.append(int(num_str))
        else:
            parts.append(0)
    return tuple(parts)

def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """
    if not isinstance(cmd, tuple):
        raise TypeError("cmd must be a tuple")
    sys_module = __import__('sys')
    is_windows = sys_module.platform == 'win32'
    if not is_windows:
        return cmd
    new_cmd = list(cmd)
    first = new_cmd[0] if new_cmd else None
    if isinstance(first, str):
        try:
            with open(first, 'rb') as f:
                first_line = f.readline().decode(errors='ignore')
            if first_line.startswith('#!'):
                parts = first_line[2:].strip().split()
                interpreter = parts[0] if parts else ''
                if 'python' in interpreter.lower():
                    interpreter = 'python'
                new_cmd = [interpreter, first] + new_cmd[1:]
        except Exception:
            pass
    result = []
    for a in new_cmd:
        if isinstance(a, str) and (' ' in a or '\t' in a or '"' in a):
            a = a.replace('"', r'\"')
            a = f'"{a}"'
        result.append(a)
    return tuple(result)

def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """
    # Only handle Windows platforms
    import os
    import sys

    if os.name != 'nt':
        return cmd

    if not cmd:
        return cmd

    parts = list(cmd)
    first = parts[0]
    # Resolve absolute path for the first argument if possible
    try:
        first_path = os.path.abspath(first)
    except Exception:
        first_path = first

    # If the first argument points to an existing file,
    # inspect it for a shebang and normalise accordingly
    if os.path.isfile(first_path):
        _, ext = os.path.splitext(first_path)
        ext_lower = ext.lower()
        # Quick‑check for common script extensions
        if ext_lower in ('.py', '.pyw', '.sh', '.bat', '.cmd'):
            # For python scripts, explicitly call the interpreter
            if ext_lower in ('.py', '.pyw'):
                return tuple([sys.executable] + parts)
            # Attempt to interpret shebangs at the top of the file
            try:
                with open(first_path, 'rb') as f:
                    first_line = f.readline().decode('utf-8', errors='ignore')
                if first_line.startswith('#!'):
                    shebang = first_line[2:].strip()
                    # Handle the common '#!env something' pattern
                    if shebang.startswith('env '):
                        # e.g. '#!env python3.10'
                        words = shebang.split()
                        interpreter = words[1] if len(words) > 1 else 'python'
                    else:
                        interpreter = shebang.split()[0]
                    # Resolve the interpreter path if it is not absolute
                    if not os.path.isabs(interpreter):
                        # Search in PATH
                        path_env = os.environ.get('PATH', os.defpath)
                        for pdir in path_env.split(os.pathsep):
                            cand = os.path.join(pdir, interpreter)
                            if os.path.isfile(cand) and os.access(cand, os.X_OK):
                                interpreter = cand
                                break
                    # Build a new command list: interpreter + the rest of the parts
                    new_parts = [interpreter] + parts[1:]
                    return tuple(new_parts)
            except Exception:
                pass

    # If nothing special was detected, return the original command
    return cmd

def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            try:
