                raise ValueError(f"Key function raised an exception: {e}") from e
            if k in cache:
                return cache[k]
            if lock is not None:
                with lock:
                    if k in cache:
                        return cache[k]
                    result = func(*args, **kwargs)
                    cache[k] = result
            else:
                result = func(*args, **kwargs)
                cache[k] = result
            return result
        return wrapper
    return decorator

