@classmethod
def extostr(cls, e, max_level=30, max_path_level=5):
    """Format an exception."""
    import traceback, os
    if not isinstance(e, BaseException):
        raise TypeError("e must be an exception instance")
    parts = []

    def _format(exc):
        tb = traceback.format_exception(type(exc), exc, exc.__traceback__, limit=max_level)
        for line in tb:
            if line.startswith('  File "'):
                try:
                    header, rest = line.split('"', 1)
                    path, rest = rest.split('"', 1)
                    parts_split = path.split(os.sep)
                    if len(parts_split) > max_path_level:
                        path = os.sep.join(['..'] + parts_split[-max_path_level:])
                    parts.append(f'{header}"{path}"{rest}')
                except Exception:
                    parts.append(line)
            else:
                parts.append(line)
        if exc.__cause__:
            parts.append('During handling of the above exception, another exception occurred:\n')
            _format(exc.__cause__)
        elif exc.__context__:
            parts.append('During handling of the above exception, another exception occurred:\n')
            _format(exc.__context__)

    _format(e)
    return ''.join(parts)
