def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if not isinstance(classes, (list, tuple)):
        raise TypeError("Input must be a list or tuple of classes")

    # Validate all items are classes
    for cls in classes:
        if not isinstance(cls, type):
            raise TypeError(f"Expected a class, got {cls!r}")

    minimal = []
    for cls in classes:
        # If any other class in the list is a subclass of this one, skip it
        if any(other != cls and issubclass(other, cls) for other in classes):
            continue
        minimal.append(cls)

    # Remove duplicate entries while preserving order
    seen = set()
    result = []
    for cls in minimal:
        if cls not in seen:
            seen.add(cls)
            result.append(cls)

    return result

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if not classes:
        return []

    unique = []
    seen = set()
    for cls in classes:
        if not isinstance(cls, type):
            raise TypeError(f"Expected a class type, got {cls!r}")
        if cls not in seen:
            seen.add(cls)
            unique.append(cls)

    minimal = []
    for cls in unique:
        # cls is a superclass of another class in the list if any
        # other class is a subclass of it
        is_super = any(issubclass(other, cls) and other is not cls for other in unique)
        if not is_super:
            minimal.append(cls)

    return minimal

