def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""

    # Validate that we have an iterable of classes
    try:
        cls_iter = iter(classes)
    except TypeError:
        raise TypeError("`classes` must be an iterable")

    # Keep elements in original order and drop duplicates
    unique = []
    seen = set()
    for c in cls_iter:
        if not isinstance(c, type):
            raise TypeError(f"Expected a class, got {type(c).__name__}")
        if c not in seen:
            seen.add(c)
            unique.append(c)

    # Determine which classes are superclasses of any other in the list
    to_remove = set()
    n = len(unique)
    for i in range(n):
        c1 = unique[i]
        for j in range(n):
            if i == j:
                continue
            c2 = unique[j]
            # If c2 is a subclass of c1, then c1 is redundant
            if issubclass(c2, c1):
                to_remove.add(c1)
                break

    # Build the minimal base list preserving the original order
    minimal = [c for c in unique if c not in to_remove]
    return minimal

