            # If the attribute exists on the instance's __dict__, it is
            # explicitly set; otherwise, it is probably inherited.
            if attr_name in getattr(self, '__dict__', {}):
                explicit_attrs.append(attr_name)
            else:
                # Fallback: include the attribute if the class defines it
                # as a data descriptor or normal attribute.
                if hasattr(self.__class__, attr_name):
