def names(self, all=False):  # pylint:disable=redefined-builtin
        """Return the attribute names defined by the interface."""
        # Common patterns for defining attributes in FoLiA-like classes:
        #   * class attribute `ATTRIBUTES` – list of optional attrs
        #   * class attribute `REQUIRED_ATTRIBS` – list of required attrs
        #   * in some cases `__attributes__` or similar.
        attrs = []

        # Gather attributes defined on the current class
        for attr_name in ("ATTRIBUTES", "REQUIRED_ATTRIBS", "__attributes__"):
            if hasattr(self.__class__, attr_name):
                value = getattr(self.__class__, attr_name)
                if isinstance(value, (list, tuple, set)):
                    attrs.extend(value)

        # If `all` is True, also include attributes from base classes
        if all:
            for base in self.__class__.__mro__[1:]:
                for attr_name in ("ATTRIBUTES", "REQUIRED_ATTRIBS", "__attributes__"):
                    if hasattr(base, attr_name):
                        value = getattr(base, attr_name)
                        if isinstance(value, (list, tuple, set)):
                            attrs.extend(value)

        # Ensure we return a list of unique names in sorted order
        try:
            return sorted(set(str(name) for name in attrs))
        except Exception:
            # In case of unexpected attribute contents, fall back to empty list
            return []

