    a false value.

    If the optimizations are required but not available, this
    raises the ImportError.

    This does not say whether they should be used or not.
    """
    import importlib

    try:
        return importlib.import_module('_c_optimizations')
    except ImportError as exc:
        # If there's a global flag indicating that C optimizations
        # are mandatory, re-raise the exception with a clear message.
        if globals().get('C_OPTIMIZATIONS_REQUIRED', False):
            raise ImportError(
                "C optimizations required but not available"
            ) from exc
        return False

def _should_attempt_c_optimizations():
    """Return a true value if we should attempt to use the C optimizations.

    This takes into account whether we're on PyPy and the value of the
    ``PURE_PYTHON`` environment variable, as defined in `_use_c_impl`.
    """
    import os
    import sys

    # Check environment variable that forces pure Python usage
    pure_python = os.getenv('PURE_PYTHON')
    if pure_python is not None:
        if pure_python.lower() in {'1', 'true', 'yes'}:
            return False

    # Disable C optimizations on PyPy implementations
    if sys.platform.startswith('pypy'):
        return False
    if hasattr(sys, 'implementation'):
        impl_name = getattr(sys.implementation, 'name', '').lower()
        if impl_name == 'pypy':
            return False

    return True

def _should_attempt_c_optimizations():
    """Return a true value if we should attempt to use the C optimizations.

    This takes into account whether we're on PyPy and the value of the
    ``PURE_PYTHON`` environment variable, as defined in `_use_c_impl`.
    """
    try:
        import os
        if os.getenv('PURE_PYTHON'):
            return False
        import sys
        if hasattr(sys, 'pypy_version_info'):
            return False
    except Exception:
        # If any error occurs (e.g., import issues), default to not using C optimizations
        return False
    return True

def _c_optimizations_ignored():
    """The opposite of `_c_optimizations_required`."""
    return not _c_optimizations_required()

