    """
    # Ensure the required method exists
    if not hasattr(self, "_c_optimizations_required"):
        raise AttributeError("Missing _c_optimizations_required method.")
    # Return the negated value of the required optimization flag
    return not self._c_optimizations_required()

def _c_optimizations_ignored():
    """The opposite of `_c_optimizations_required`."""
    try:
        return not _c_optimizations_required()
    except NameError:
        raise RuntimeError("`_c_optimizations_required` function is not defined")

