def to_csv(self, separator=",", header=None):
    """.. deprecated:: 0.5 in Lena 0.5 to_csv is not used.
          Iterables are converted to tables.

    Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.

    To convert :class:`Graph` to CSV inside a Lena sequence,
    use :class:`lena.output.ToCSV`.
    """
    import warnings
    from collections.abc import Iterable

    warnings.warn("to_csv is deprecated and will be removed in a future version.", DeprecationWarning, stacklevel=2)

    if not isinstance(separator, str):
        raise TypeError("separator must be a string")
    if header is not None and not isinstance(header, str):
        raise TypeError("header must be a string or None")

    rows = []

    if header is not None:
        rows.append(header)

    # Helper to determine if an object is a non-string iterable
    def is_non_string_iter(obj):
        return isinstance(obj, Iterable) and not isinstance(obj, (str, bytes))

    # Construct rows from graph points
    for point in getattr(self, 'points', []):
        try:
            # Try unpacking coordinate and value
            if is_non_string_iter(point) and len(point) == 2:
                coord, value = point
            else:
                # If point is a single value, use it as the coordinate
                coord = point
                value = None
        except Exception:
            raise ValueError(f"Invalid point format: {point!r}")

        # Convert coordinate(s) to string
        if is_non_string_iter(coord):
            coord_str = separator.join(str(v) for v in coord)
        else:
            coord_str = str(coord)

        # Convert value(s) to string
        if value is None:
            value_str = ""
        elif is_non_string_iter(value):
            value_str = separator.join(str(v) for v in value)
        else:
            value_str = str(value)

        # Combine coordinate and value parts
        if value_str:
            row = f"{coord_str}{separator}{value_str}"
        else:
            row = coord_str

        rows.append(row)

    return "\n".join(rows) + ("\n" if rows else "")

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    if not isinstance(coord_name, str):
        raise TypeError("coord_name must be a string")
    try:
        # First look for a dedicated attribute like <coord>_err_indices
        attr_name = f"{coord_name}_err_indices"
        if hasattr(self, attr_name):
            return getattr(self, attr_name)

        # Next look for a generic mapping stored on the instance
        if hasattr(self, "err_indices"):
            err_map = getattr(self, "err_indices")
            if isinstance(err_map, dict):
                return err_map.get(coord_name, [])

        # No standard place found – try to fetch the coordinate list
        # and return an empty list indicating no errors
        if getattr(self, coord_name, None) is not None:
            return []

        # If the coordinate itself does not exist, raise an informative error
        raise AttributeError
    except AttributeError:
        raise ValueError(f"Unable to find error indices for coordinate '{coord_name}'.")
    except Exception as exc:
        # Wrap any other unexpected error
        raise RuntimeError(f"Error retrieving error indices for '{coord_name}': {exc}") from exc

def _update_context(self, context):
        """Update *context* with the properties of this graph.

        *context.error* is appended with indices of errors.
        Example subcontext for a graph with fields "E,t,error_E_low":
        {"error": {"x_low": {"index": 2}}}.
        Note that error names are called "x", "y" and "z"
        (this corresponds to first three coordinates,
        if they are present), which allows to simplify plotting.
        Existing values are not removed
        from *context.value* and its subcontexts.

        Called on "destruction" of the graph (for example,
        in :class:`.ToCSV`). By destruction we mean conversion
        to another structure (like text) in the flow.
        The graph object is not really destroyed in this process.
        """
        # Validate the context container
        if not isinstance(context, dict):
            raise TypeError("context must be a dictionary-like object")

        # Ensure the nested 'error' dictionary exists
        error_ctx = context.setdefault('error', {})
        if not isinstance(error_ctx, dict):
            raise TypeError("context['error'] must be a dictionary")

        # Populate error indices
        # Expected format: a mapping of field names to integer indices,
        # where field names starting with 'error_' denote error components.
        error_mapping = {}
        if hasattr(self, "errors") and isinstance(self.errors, dict):
            error_mapping = self.errors
        elif hasattr(self, "error") and isinstance(self.error, dict):
            error_mapping = self.error
        # Attempt to infer error mapping from attributes if missing
        elif hasattr(self, "__dict__"):
            for key, value in self.__dict__.items():
                if key.startswith("error_") and isinstance(value, int):
                    error_mapping[key] = value

        for full_name, idx in error_mapping.items():
            # Normalize error field name (strip leading 'error_')
            if full_name.startswith("error_"):
                core = full_name[6:].lstrip("_")
            else:
                core = full_name

            # Map first three coordinates to 'x', 'y', 'z' names
            # For fields not matching these, keep the original suffix
            # Determine coordinate index based on ordering (first three fields)
            # Here we simply use the core name as key; customize if needed
            coord_name = core

            # Create nested structure: e.g., {'x_low': {'index': idx}}
            error_ctx.setdefault(coord_name, {})["index"] = idx

        # Merge existing values without removing them
        value_ctx = context.setdefault("value", {})
        if not isinstance(value_ctx, dict):
            raise TypeError("context['value'] must be a dictionary")
        # If the graph has a 'value' attribute that is a dict, merge it
        if hasattr(self, "value") and isinstance(self.value, dict):
            value_ctx.update(self.value)
        # If there is a method to export data (e.g., to_dict), use it
        elif hasattr(self, "to_dict") and callable(self.to_dict):
            try:
                val = self.to_dict()
                if isinstance(val, dict):
                    value_ctx.update(val)
            except Exception:
                pass
        # Otherwise attempt to merge attributes from the instance
        else:
            for k, v in self.__dict__.items():
                if k not in ("errors", "error", "value"):
                    value_ctx.setdefault(k, v)
        # No explicit return; context is modified in-place.

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # Validate input lengths
    if len(edges) != len(bins) + 1:
        raise ValueError("Edges length must be one greater than bins length")

    # Compute bin widths
    try:
        widths = [e2 - e1 for e1, e2 in zip(edges, edges[1:])]
    except Exception as exc:
        raise TypeError("Edges must support numeric subtraction") from exc

    # Compute integral as weighted sum
    try:
        integral_value = sum(b * w for b, w in zip(bins, widths))
    except Exception as exc:
        raise TypeError("Bins must support numeric multiplication") from exc

    return integral_value

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # Basic validation
    try:
        nbins = len(bins)
    except Exception as exc:
        raise TypeError(f"bins must be a sequence of numbers, got {bins!r}") from exc
    try:
        nedges = len(edges)
    except Exception as exc:
        raise TypeError(f"edges must be a sequence of numbers, got {edges!r}") from exc

    if nbins == 0:
        return 0.0

    if nedges != nbins + 1:
        raise ValueError(f"edges length must be len(bins)+1 (got {nedges} edges "
                         f"for {nbins} bins)")

    total = 0.0
    # Compute widths and accumulate the integral
    for bin_val, left_edge, right_edge in zip(bins, edges[:-1], edges[1:]):
        try:
            width = float(right_edge) - float(left_edge)
            total += float(bin_val) * width
        except Exception as exc:
            raise ValueError(f"Non-numeric value encountered: bin={bin_val}, "
                             f"edges=({left_edge}, {right_edge})") from exc

    return total

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # Basic validation of input types
    try:
        bins_list = list(bins)
    except Exception as exc:
        raise TypeError(f"bins must be an iterable, got {type(bins).__name__}") from exc

    try:
        edges_list = list(edges)
    except Exception as exc:
        raise TypeError(f"edges must be an iterable, got {type(edges).__name__}") from exc

    # The number of edges should be one more than the number of bins
    if len(edges_list) != len(bins_list) + 1:
        raise ValueError(
            f"Length mismatch: expected {len(bins_list) + 1} edges "
            f"for {len(bins_list)} bins, got {len(edges_list)}"
        )

    # Compute the integral: sum over bin height * bin width
    total = 0.0
    for height, start, end in zip(bins_list, edges_list[:-1], edges_list[1:]):
        width = end - start
        if width < 0:
            raise ValueError(f"Negative bin width detected: {start} to {end}")
        total += float(height) * width

    return total

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # Validate input types and lengths
    try:
        bins = list(bins)
        edges = list(edges)
    except Exception as exc:
        raise ValueError("bins and edges must be iterable") from exc

    if not isinstance(bins, list) or not isinstance(edges, list):
        raise ValueError("bins and edges must be list-like")

    if len(edges) != len(bins) + 1:
        raise ValueError(
            f"Number of edges ({len(edges)}) must be one more than number of bins ({len(bins)})"
        )

    # Compute bin widths and check for non-negative intervals
    widths = []
    for i in range(len(bins)):
        w = edges[i + 1] - edges[i]
        if w < 0:
            raise ValueError(f"Edge interval negative at position {i}: {edges[i]} -> {edges[i+1]}")
        widths.append(w)

    # Integral is sum of bin values times their widths
    total = 0.0
    for b, w in zip(bins, widths):
        try:
            total += float(b) * float(w)
        except Exception as exc:
            raise ValueError(f"Invalid numeric value in bin or edge: {b} * {w}") from exc

    return total

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # Try converting to NumPy arrays for vectorised operations.
    try:
        import numpy as _np
        bins_arr = _np.asarray(bins, dtype=float)
        edges_arr = _np.asarray(edges, dtype=float)
    except Exception as exc:
        raise TypeError(
            f"bins and edges must be array‑like numeric types; got {type(bins)} and {type(edges)}"
        ) from exc

    # Ensure the inputs are one‑dimensional and lengths are compatible.
    if bins_arr.ndim != 1:
        raise ValueError(f"bins must be a 1‑D array, got shape {bins_arr.shape}")
    if edges_arr.ndim != 1:
        raise ValueError(f"edges must be a 1‑D array, got shape {edges_arr.shape}")
    if len(edges_arr) != len(bins_arr) + 1:
        raise ValueError(
            f"len(edges) must be len(bins)+1; got {len(edges_arr)} and {len(bins_arr)}"
        )

    # If there are no bins, the integral is zero.
    if len(bins_arr) == 0:
        return 0.0

    # Compute bin widths as the difference between successive edges.
    widths = _np.diff(edges_arr)

    # The integral is the sum of bin values multiplied by their widths.
    return float(_np.sum(bins_arr * widths))

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    if seq is None:
        return False
    # If the sequence itself is a single element, check if it is a FillRequest.
    if isinstance(seq, FillRequest):
        return True
    # If it's a Source instance, it's not a FillRequestSeq.
    if isinstance(seq, Source):
        return False
    # Try iterating over the sequence.
    try:
        found = False
        for elem in seq:
            if isinstance(elem, FillRequest):
                found = True
            if isinstance(elem, Source):
                # Presence of a Source object means it's a Source sequence.
                return False
        return found
    except Exception:
        # seq is not iterable or some other issue; treat as not a FillRequestSeq.
        return False

