    if isinstance(seq, AbstractElement):
        # Exclude Source elements
        return isinstance(seq, FillRequest) and not isinstance(seq, Source)

    # Handle common sequence types
    try:
        # Iterate over iterable sequences (lists, tuples, sets, etc.)
        for elem in seq:
            if isinstance(elem, Source):
                # A Source element disqualifies this sequence
                return False
            if isinstance(elem, FillRequest):
