            if isinstance(val1, dict) and isinstance(val2, dict):
                # Decide whether to recurse based on level
                if level == 1:
                    # Only compare top-level; if dicts differ include val1
                    if val1 != val2:
                        result[key] = val1
                elif level == 0:
                    # No recursion: do nothing if dicts are present in both
                    pass
                else:  # level > 1 or level == -1 (infinite)
                    sublevel = level - 1 if level > 0 else -1
                    subdiff = difference(val1, val2, sublevel)
                    if subdiff:
                        result[key] = subdiff
            else:
                if val1 != val2:
