    return result

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise TypeError("Both d1 and d2 must be dictionaries.")

    # Helper to determine if we should recurse
    def should_recurse(lvl):
        return lvl != 0

    # Main recursion
    result = {}
    for key, val in d1.items():
        if key not in d2:
            # Key only in d1: include a copy if it's a dict, otherwise raw value
            result[key] = val.copy() if isinstance(val, dict) else val
        else:
            other = d2[key]
            if val == other:
                continue  # identical, no difference
            # Different values
            if isinstance(val, dict) and isinstance(other, dict) and should_recurse(level):
                # Recurse deeper with decreasing level, unless infinite
                next_level = level if level == -1 else level - 1
                sub = difference(val, other, next_level)
                if sub:
                    result[key] = sub
                else:
                    # No differences deeper, but values differ at this level
                    result[key] = val.copy() if isinstance(val, dict) else val
            else:
                result[key] = val.copy() if isinstance(val, dict) else val
    return result

