        if not isinstance(coord, (list, tuple)):
            raise TypeError(f"coord must be a list or tuple, got {type(coord).__name__}")
        if len(coord) != len(self.edges):
            raise ValueError(f"coord length ({len(coord)}) does not match histogram dimensionality ({len(self.edges)})")
        try:
            w = float(weight)
        except Exception as exc:
            raise TypeError(f"weight must be numeric, got {type(weight).__name__}") from exc

