        indices = []
        for dim, c in enumerate(coord):
            edges = self.edges[dim]
            if c < edges[0] or c >= edges[-1]:
                # Coordinate is outside the valid range; ignore
                return
            bin_index = None
            # Linear search for the bin (edges are sorted)
            for i in range(len(edges) - 1):
                if edges[i] <= c < edges[i + 1]:
                    bin_index = i
                    break
            if bin_index is None:
                # Should not happen, but guard against it
                return
            indices.append(bin_index)

        # Increment the histogram bin
        self.data[tuple(indices)] += w
