                    pass

        # Validate value type
        if isinstance(value, (list, tuple, set)):
            # Containers are not allowed; treat entire container as invalid
            errors.append({str(value): "expected string or bytes-like object"})
        elif not isinstance(value, (str, bytes)):
            errors.append({str(value): "expected string or bytes-like object"})
