def validate_value(value):
    """Validate the given value against the corresponding regular expression.

    Args:
        value: the string to validate

    Raises:
        ValidationError: if the given value is not conform to the regular expression.
    """
    import re
    if not isinstance(value, str):
        raise ValidationError("Value must be a string.")
    # If a special regex pattern attribute is present on the value object, use it;
    # otherwise default to accepting any string.
    pattern = getattr(value, "_validate_pattern", r".*")
    try:
        if not re.fullmatch(pattern, value):
            raise ValidationError(f"Value '{value}' does not match pattern '{pattern}'.")
    except re.error as exc:
        raise ValidationError(f"Invalid regular expression '{pattern}': {exc}") from exc

def validate_key(key):
    """Validate the given key against the corresponding regular expression.

    Args:
        key: the string to validate

    Raises:
        ValidationError: if the given key is not conform to the regular expression.
    """
    import re
    # Ensure key is a string
    if not isinstance(key, str):
        raise ValidationError("Key must be a string")

    # The regular expression against which the key is validated.
    # It should be defined at module level as KEY_REGEX or KEY_PATTERN.
    # If not defined, fall back to a permissive pattern or raise an error.
    pattern = None
    try:
        pattern = KEY_REGEX
    except NameError:
        try:
            pattern = KEY_PATTERN
        except NameError:
            # If no pattern is defined, we cannot perform validation.
            raise ValidationError("No key validation pattern defined")

    # Compile if it's a string pattern
    if isinstance(pattern, str):
        regex = re.compile(pattern)
    elif hasattr(pattern, "match"):
        regex = pattern
    else:
        raise ValidationError("Invalid key validation pattern")

    if not regex.match(key):
        raise ValidationError(f"Key '{key}' does not match the required pattern.")

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """Together with :func:`generate_default_observer_schema_list`, this function is
    called recursively to generate part of a default ``observer_schema`` from part of a
    Kubernetes resource, defined respectively by ``manifest_dict`` or ``manifest_list``.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer_schema

    This function creates a new dictionary from ``manifest_dict`` and replaces all
    non-list and non-dict values by ``None``.

    In case of ``first_level`` dictionary (i.e. complete ``observer_schema`` for a
    resource), the values of the identifying fields are copied from the manifest file.
    """
    if not isinstance(manifest_dict, dict):
        raise TypeError(f"Expected a dict, got {type(manifest_dict).__name__}")

    result = {}

    for key, value in manifest_dict.items():
        # Special handling when this dict represents the whole schema
        if first_level:
            if key in {"kind", "apiVersion"}:
                # Copy identifying string fields verbatim
                result[key] = value
                continue
            if key == "metadata" and isinstance(value, dict):
                # Copy only the name and namespace subfields from metadata
                meta = {}
                for sub in ("name", "namespace"):
                    meta[sub] = value.get(sub)
                result[key] = meta
                continue

        # Normal recursive processing
        if isinstance(value, dict):
            # Recurse into nested dictionaries
            result[key] = generate_default_observer_schema_dict(value, first_level=False)
        elif isinstance(value, list):
            # Lists are preserved, but each element is processed similarly
            new_list = []
            for item in value:
                if isinstance(item, (dict, list)):
                    new_list.append(
                        generate_default_observer_schema_dict(item, first_level=False)
                        if isinstance(item, dict)
                        else new_list.append(item)
                    )
                else:
                    new_list.append(None)
            result[key] = new_list
        else:
            # All other scalar values are replaced with None unless they are copying
            # identifying fields in the first-level case (handled above).
            result[key] = None

    return result

