            # Schema must be a list; nothing to do.
            return

        for field in observer_schema:
            # Skip any fields that are not marked for observation
            if not field.get("observe", True):
                continue

            field_name = field.get("name")
            if not field_name:
                continue

            # If the field is not yet present in the manifest, initialize it
            if field_name not in last_applied_manifest:
                # Prefer the value from the response; fall back to a default if provided
                value = response.get(field_name, field.get("default"))
                last_applied_manifest[field_name] = value

            # Handle nested structures (dicts or lists of dicts)
            child_schema = field.get("children", None)
            if not child_schema:
                continue

            # Current value in the manifest
            child_last = last_applied_manifest.get(field_name)
            # Current value in the response
            child_resp = response.get(field_name)

            # If the child is a dict, recurse directly
            if isinstance(child_schema, list) and isinstance(child_resp, dict):
                if not isinstance(child_last, dict):
                    child_last = {}
                    last_applied_manifest[field_name] = child_last
                update_last_applied_manifest_list_from_resp(child_last, child_schema, child_resp)

            # If the child is a list of dicts, loop over elements
            elif isinstance(child_schema, list) and isinstance(child_resp, list):
                # Ensure the manifest contains a list
                if not isinstance(last_applied_manifest[field_name], list):
                    last_applied_manifest[field_name] = []

                for idx, resp_item in enumerate(child_resp):
                    # Ensure there is a dict in the manifest list for this item
                    if idx < len(last_applied_manifest[field_name]):
                        child_last_item = last_applied_manifest[field_name][idx]
                    else:
                        child_last_item = {}
                        last_applied_manifest[field_name].append(child_last_item)

                    # Recursively update each item
                    if isinstance(child_schema, list):
                        # Assume the same child schema applies to each item
                        update_last_applied_manifest_list_from_resp(
                            child_last_item,
                            child_schema,
                            resp_item,
                        )
                    else:
                        # Fallback: treat the child schema as a single dict schema
                        update_last_applied_manifest_list_from_resp(
                            child_last_item,
                            [child_schema],
                            resp_item,
                        )

    except Exception:
        # In case of any unexpected error, silently fail so that higher-level logic can handle it.
        pass

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest,
    observer_schema,
    response
):
    """Together with :func:`update_last_applied_manifest_dict_from_resp`, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being
