        observer_schema (list): partial ``observer_schema``
        response (list): partial response from the Kubernetes API.

    This function goes through all observed fields, and initializes their value in
    ``last_applied_manifest`` if they are not yet present
    """
    # Helper that works on individual dicts
    def _update_dict(target, schema, src):
        for field_def in schema:
            field = field_def.get("field")
            if not field:
                continue

            # Skip if field already exists in target
            if field in target:
                # If both target and src are dicts, recurse
                if isinstance(target[field], dict) and isinstance(src.get(field), dict):
                    _update_dict(target[field], field_def.get("child", []), src[field])
                # If both are lists of dicts, recurse on each element
                elif isinstance(target[field], list) and isinstance(src.get(field), list):
                    for i, sub_src in enumerate(src[field]):
                        if i < len(target[field]) and isinstance(target[field][i], dict):
                            _update_dict(target[field][i], field_def.get("child", []), sub_src)
                continue  # already present, skip

            # If source has the field, copy it over
            if field in src:
                val = src[field]
                # If a nested schema is provided and the value is a dict,
                # initialise a nested dict and recurse
                if isinstance(val, dict) and "child" in field_def:
                    nested_target = {}
                    target[field] = nested_target
                    _update_dict(nested_target, field_def["child"], val)
                # If a nested schema is provided and the value is a list of dicts,
                # initialise a list and recurse on each element
                elif isinstance(val, list) and "child" in field_def:
                    nested_list = []
                    target[field] = nested_list
                    for sub_src in val:
                        if isinstance(sub_src, dict):
                            nested_item = {}
                            nested_list.append(nested_item)
                            _update_dict(nested_item, field_def["child"], sub_src)
                        else:
                            nested_list.append(sub_src)
                else:
                    target[field] = val

    # Main logic: ``last_applied_manifest`` and ``response`` are expected to be
    # lists of dictionaries (each element being an individual manifest).
    # The function walks through each pair of elements and updates missing
    # fields in ``last_applied_manifest``.
    if not isinstance(last_applied_manifest, list) or not isinstance(observer_schema, list) or not isinstance(response, list):
        raise TypeError("Expected lists for last_applied_manifest, observer_schema, and response")

    # If the lists are empty or of different lengths, we cannot map elements
    if not response:
        return
    if not last_applied_manifest:
        # initialise an empty dict at the same index as response
        for _ in response:
            last_applied_manifest.append({})
    # Ensure lengths match
    min_len = min(len(last_applied_manifest), len(response))
    for idx in range(min_len):
        tgt = last_applied_manifest[idx]
        src = response[idx]
        if isinstance(tgt, dict) and isinstance(src, dict):
            _update_dict(tgt, observer_schema, src)
        else:
            # If types mismatch, log warning and skip
            continue
    # If response has more items than last_applied_manifest, append new ones
    if len(response) > len(last_applied_manifest):
        for idx in range(len(last_applied_manifest), len(response)):
            src = response[idx]
            if isinstance(src, dict):
                new_item = {}
                _update_dict(new_item, observer_schema, src)
                last_applied_manifest.append(new_item)
            else:
                last_applied_manifest.append(src)

def update_last_applied_manifest_list_from_resp(
