        raise TypeError("response must be a list or dict")

    # Normalise last_applied_manifest to a dict for easier handling.
    if isinstance(last_applied_manifest, list):
        last_applied_manifest = {}
    elif not isinstance(last_applied_manifest, dict):
        raise TypeError("last_applied_manifest must be a dict or list (converted to dict)")

    # Helper to handle nested structures
    def recursive_update(lam, schema, resp):
        if isinstance(schema, list):
            for item in schema:
                if isinstance(item, dict):
                    for key, sub_schema in item.items():
                        if key not in lam:
                            if key in resp:
                                if isinstance(sub_schema, (list, dict)):
                                    # Initialise nested structure
                                    nested_lam = lam.setdefault(key, {})
                                    nested_resp = resp.get(key, {})
                                    recursive_update(nested_lam, sub_schema, nested_resp)
                                else:
                                    lam[key] = resp[key]
                elif isinstance(item, str):
                    if item not in lam and item in resp:
                        lam[item] = resp[item]
        elif isinstance(schema, dict):
            for key, sub_schema in schema.items():
                if key not in lam and key in resp:
                    if isinstance(sub_schema, (list, dict)):
                        nested_lam = lam.setdefault(key, {})
                        nested_resp = resp.get(key, {})
                        recursive_update(nested_lam, sub_schema, nested_resp)
                    else:
                        lam[key] = resp[key]

    recursive_update(last_applied_manifest, observer_schema, response)

    # If the original argument was a list, return a list of key/value pairs
    if isinstance(response, list):
        return [(k, v) for k, v in last_applied_manifest.items()]
    return last_applied_manifest

def update_last_applied_manifest_list_from_resp(
