        response (list): partial response from the Kubernetes API.

    This function goes through all observed fields, and initializes their value in
    ``last_applied_manifest`` if they are not yet present

    """
    # Basic type validation; if types are unexpected, skip processing to avoid crashes.
    if not isinstance(last_applied_manifest, (dict, list)):
        return
    if not isinstance(response, (dict, list)):
        return

    # Observer schema might specify which fields to consider. If provided as a
    # list of field names or dicts with a ``name`` key, we use it to filter the
    # response.  If the schema is empty or missing, we process all keys.
    if isinstance(observer_schema, list):
        # Build a set of names to observe if possible.
        try:
            observed = {
                field.get("name") if isinstance(field, dict) else str(field)
                for field in observer_schema
                if field
            }
        except Exception:
            observed = None
    else:
        observed = None

    def _update(dest, src):
        """
        Recursively update dest dictionary with values from src.
        Only adds missing keys; for existing keys that are dicts or lists,
        recursively merge them.
        """
        for k, v in src.items():
            if observed is not None and k not in observed:
                # Skip keys that are not part of the observed schema
                continue
            if k not in dest:
                # Directly copy missing value
                dest[k] = v
            else:
                # If the value is a nested dict, recurse
                if isinstance(v, dict) and isinstance(dest[k], dict):
                    _update(dest[k], v)
                # If both are lists, merge element by element
                elif isinstance(v, list) and isinstance(dest[k], list):
                    for i, item in enumerate(v):
                        if i < len(dest[k]):
                            if isinstance(item, dict) and isinstance(dest[k][i], dict):
                                _update(dest[k][i], item)
                        else:
                            dest[k].append(item)

    if isinstance(response, dict):
        if isinstance(last_applied_manifest, dict):
            _update(last_applied_manifest, response)
    elif isinstance(response, list):
        # If the destination is also a list, merge each item
        if isinstance(last_applied_manifest, list):
            for i, item in enumerate(response):
                if i < len(last_applied_manifest):
                    if isinstance(item, dict) and isinstance(last_applied_manifest[i], dict):
                        _update(last_applied_manifest[i], item)
                else:
                    # Append new items that were not present
                    if isinstance(item, dict):
                        last_applied_manifest.append(item.copy())
                    else:
                        last_applied_manifest.append(item)

