def status_str(self, prefix=''):
    """Return string of validator status, with optional prefix."""
    # Attempt to find a meaningful status attribute
    if hasattr(self, 'valid'):
        status = 'OK' if self.valid else 'FAIL'
    elif hasattr(self, 'is_valid'):
        status = 'OK' if self.is_valid else 'FAIL'
    elif hasattr(self, 'status'):
        status = self.status
    elif hasattr(self, 'errors'):
        status = 'OK' if not self.errors else f"ERRORS({len(self.errors)})"
    else:
        # Fall back to a generic representation if nothing is found
        try:
            status = str(self)
        except Exception:
            status = '<no status available>'
    return f"{prefix}{status}"

def status_str(self, prefix=''):
    """Return string of validator status, with optional prefix."""
    try:
        status = getattr(self, 'status', None)
        if status is None:
            return prefix
        if isinstance(status, (list, tuple)):
            status_str = ', '.join(map(str, status))
        else:
            status_str = str(status)
        return f"{prefix}{status_str}"
    except Exception:
        return prefix

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    try:
        # Retrieve the validation log.  It may be stored under various
        # attribute names; common ones are `validation_log`, `log`, or
        # `validation_log_entries`.  If it is missing, simply return an
        # empty string.
        log = getattr(self, 'validation_log', None) or getattr(self, 'log', None) or getattr(self, 'validation_log_entries', None)
        if not log:
            return ''
        # Ensure that `log` is iterable.  If it is a single message, wrap it in a list.
        if isinstance(log, str):
            log = [log]
        # Convert each entry to a string and prepend the prefix.
        formatted_lines = []
        for entry in log:
            # If an entry has a sensible string representation, use it;
            # otherwise fall back to the built‑in `str` conversion.
            try:
                line = str(entry)
            except Exception:
                line = '<non‑string entry>'
            formatted_lines.append(f'{prefix}{line}')
        return '\n'.join(formatted_lines)
    except Exception as exc:
        # In the unlikely event that something goes wrong, return
        # a descriptive error message instead of propagating the
        # exception.
        return f'{prefix}Error generating status string: {exc}'

def status_str(self, prefix=''):
        """Return string representation of validation log, with optional prefix."""
        try:
            logs = getattr(self, 'validation', [])
        except AttributeError:
            logs = []

        lines = []
        for log in logs:
            # Get a readable message from the log entry.
            if hasattr(log, 'message'):
                msg = log.message
            else:
                msg = str(log)

            # If the log entry provides a severity level, prepend it.
            if hasattr(log, 'severity'):
                line = f"{log.severity}: {msg}"
            else:
                line = msg

            # Prefix each line with the supplied prefix.
            lines.append(prefix + line)

        # Join all lines into a single string; return empty string if no logs.
        return '\n'.join(lines)

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
