    log = getattr(self, 'validation_log', None)
    if log is None:
        return ''
    # If the log is a single string, just prefix and return it
    if isinstance(log, str):
        return f"{prefix}{log}"
    # If the log is an iterable of entries, format each line
    try:
        lines = []
        for entry in log:
            # Ensure each entry is represented as a string
            lines.append(f"{prefix}{str(entry)}")
        return '\n'.join(lines)
    except TypeError:
        # If log is not iterable, fall back to string representation
        return f"{prefix}{str(log)}"}

def status_str(self, prefix=''):
