    log = getattr(self, 'log', getattr(self, '_log', []))
    # Ensure we have an iterable of log entries
    if not isinstance(log, (list, tuple)):
        return ''
    # Prefix each entry and join into a single string
    prefixed_entries = [prefix + str(entry) for entry in log]
