def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    try:
        # Retrieve the validation log; default to empty iterable if missing
        log = getattr(self, 'validation_log', [])
        if not log:
            return prefix
        # Format each log entry with the provided prefix.
        formatted_lines = []
