def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    Parameters:
        inventory (dict): The inventory to validate.
        extract_spec_version (bool): Whether to extract a spec version
            from the inventory type field.

    Raises:
        TypeError: If ``inventory`` is not a dictionary.
        ValueError: If required fields are missing or invalid.
    """
    # Basic type check
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dictionary")

    # Extract spec version if requested
    if extract_spec_version:
        spec_type = inventory.get('type')
        # Mapping of type strings to spec versions; extend as needed
        spec_map = {
            '2.0': '2.0',
            '2.1': '2.1',
            '1.0': '1.0',
        }
        if spec_type in spec_map:
            self.spec_version = spec_map[spec_type]
        else:
            # If no valid type given, fall back to existing spec_version
            if not hasattr(self, 'spec_version') or not self.spec_version:
                raise ValueError(
                    "Spec version cannot be determined from inventory "
                    "and is missing on the object"
                )

    # Validate each inventory entry
    seen_ids = set()
    for name, entry in inventory.items():
        if not isinstance(entry, dict):
            raise TypeError(f"Inventory entry '{name}' must be a dict")

        # Required fields
        for field in ('id', 'name'):
            if field not in entry:
                raise ValueError(
                    f"Inventory entry '{name}' is missing required field "
                    f"'{field}'"
                )

        # Duplicate ID check
        entry_id = entry['id']
        if entry_id in seen_ids:
            raise ValueError(f"Duplicate id '{entry_id}' found in inventory")
        seen_ids.add(entry_id)

    return True

def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    # Inventory must be provided
    if inventory is None:
        raise ValueError("Inventory must not be None")

    # Helper: get attribute or key
    def get_attr(obj, key, default=None):
        if isinstance(obj, dict):
            return obj.get(key, default)
        return getattr(obj, key, default)

    # Attempt to extract type information if requested
    type_value = get_attr(inventory, 'type')
    known_versions = {"1.0", "2.0", "3.0"}  # Example known spec versions
    if extract_spec_version and type_value:
        if type_value in known_versions:
            self.spec_version = type_value
        else:
            raise ValueError(f"Unsupported specification version '{type_value}' in inventory")

    # Basic validation: ensure required attributes are present
    required_attrs = ["id", "name"]
    missing = [attr for attr in required_attrs if not get_attr(inventory, attr)]
    if missing:
        raise ValueError(f"Inventory is missing required attributes: {', '.join(missing)}")

    # Additional version‑specific checks could go here
    # Example: if spec_version < "2.0" require a "legacy" flag
    if getattr(self, "spec_version", None) and self.spec_version < "2.0":
        if not get_attr(inventory, "legacy"):
            raise ValueError("Legacy flag required for spec_version < 2.0")

    # If all checks pass, return True
    return True

def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    # Determine which spec_version to use
    spec_version = getattr(self, "spec_version", None)
    if extract_spec_version:
        type_val = inventory.get("type") if isinstance(inventory, dict) else None
        if type_val:
            try:
                spec_version = float(type_val)
            except Exception:
                # Keep the original spec_version if conversion fails
                pass

    # Core validation logic
    # Inventory must be a mapping
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a mapping (dict)")

    # Allowed keys in the inventory (example set – extend as needed)
    allowed_keys = {"type", "entries", "name", "metadata"}
    for key in inventory:
        if key not in allowed_keys:
            raise ValueError(f"Unexpected key '{key}' in inventory")

    # If a type key exists, it should start with a numeric version prefix when extracted
    if "type" in inventory:
        if not isinstance(inventory["type"], str):
            raise TypeError("inventory['type'] must be a string")
        if extract_spec_version and not inventory["type"].lower().startswith("v"):
            raise ValueError("inventory['type'] must start with 'v' when extracting spec version")

    # Validate entries list if present
    entries = inventory.get("entries")
    if entries is not None:
        if not isinstance(entries, list):
            raise TypeError("inventory['entries'] must be a list")
        for idx, e in enumerate(entries):
            if not isinstance(e, dict):
                raise TypeError(f"entry #{idx} in inventory['entries'] must be a mapping (dict)")
            # Each entry must contain at least an 'id' key
            if "id" not in e:
                raise ValueError(f"entry #{idx} in inventory['entries'] is missing required 'id' key")

    # If `metadata` key exists, it should be a dict
    if "metadata" in inventory and not isinstance(inventory["metadata"], dict):
        raise TypeError("inventory['metadata'] must be a dict if present")

    # Check spec_version is a supported format (example: float or None)
    if spec_version is not None and not isinstance(spec_version, (int, float)):
        raise ValueError("Determined spec_version must be numeric")

    # If all checks pass, validation succeeds
    return True

def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    # ------------------------------------------------------------------
    #  1. Optionally extract the specification version from the inventory
    # ------------------------------------------------------------------
    if extract_spec_version:
        try:
            # Try to read a `type` attribute from the inventory.  Handle both
            # dict-like inventories and objects with a `type` field.
            if isinstance(inventory, dict):
                type_val = inventory.get('type')
            else:
                type_val = getattr(inventory, 'type', None)
        except Exception as exc:
            raise ValueError("Unable to introspect inventory for type information") from exc

        if not type_val:
            raise ValueError(
                "extract_spec_version requested but inventory has no 'type' value"
            )

        # Very light parse – the spec_version is expected to be something like
        # '1.0', '1.1', 'v1.0', etc.  We allow optional leading 'v' or 'V'.
        import re  # only here because the function may be used in contexts
                    # without importing re globally

        match = re.match(r'^[vV]?(\d+(?:\.\d+)*)$', type_val)
        if not match:
            raise ValueError(
                f"Invalid type value '{type_val}' for specification version"
            )

        # Store the extracted spec version for later use
        self.spec_version = match.group(1)

    # ------------------------------------------------------------------
    #  2. Basic structural validation of the inventory
    # ------------------------------------------------------------------
    if not isinstance(inventory, dict):
        raise TypeError("Inventory must be a dictionary-like object")

    # If the subclass defines expectations for required keys, enforce them
    required_keys = getattr(self, "REQUIRED_INVENTORY_KEYS", None)
    if required_keys is not None:
        for key in required_keys:
            if key not in inventory:
                raise ValueError(f"Inventory missing required key: '{key}'")

    # ------------------------------------------------------------------
    #  3. Optional custom validation logic
    # ------------------------------------------------------------------
    # Subclasses might override or extend this method; for that purpose we
    # provide a hook that can be used for further checks.  By default the
    # hook does nothing and simply returns True.
    validated = True
    extra_validator = getattr(self, "inventory_extra_validator", None)
    if callable(extra_validator):
        try:
            validated = extra_validator(inventory, self.spec_version)
        except Exception as exc:
            raise ValueError(
                "Error during extra inventory validation"
            ) from exc

    return bool(validated)

def check_digests_present_and_used(self, manifest_files, digests_used):
        """Check all digests in manifest that are needed are present and used."""
        # Basic type checking
        if not isinstance(manifest_files, (list, tuple)):
            raise TypeError("manifest_files must be a list or tuple of (file, digest) pairs")
        if not isinstance(digests_used, (set, list)):
            raise TypeError("digests_used must be a set or list of digests")

        # Build the set of digests that appear in the manifest
        manifest_digests = set()
        for entry in manifest_files:
            try:
                digest = entry[1]
            except Exception as exc:
                raise ValueError(f"Malformed manifest entry {entry!r}: {exc}") from exc
            if not isinstance(digest, str):
                raise ValueError(f"Digest must be a string, got {type(digest).__name__} in entry {entry!r}")
            manifest_digests.add(digest)

        # Ensure every used digest appears in the manifest
        digests_used_set = set(digests_used)
        missing = digests_used_set - manifest_digests
        if missing:
            raise ValueError(f"Missing digests in manifest: {', '.join(sorted(missing))}")

        # Ensure every digest in the manifest is actually used (no unused digests)
        unused = manifest_digests - digests_used_set
        if unused:
            raise ValueError(f"Unreferenced digests in manifest: {', '.join(sorted(unused))}")

        # If we get here, everything is consistent
        return True

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    if not isinstance(manifest_files, dict):
        raise TypeError("manifest_files must be a mapping of file to digest")
    if not hasattr(digests_used, '__iter__'):
        raise TypeError("digests_used must be an iterable of digests")

    digests_used_set = set(digests_used)
    manifest_digests = set(manifest_files.values())

    # Ensure all digests in manifest are used
    for file, digest in manifest_files.items():
        if digest not in digests_used_set:
            raise ValueError(f"Digest for file '{file}' is not used: {digest}")

    # Ensure all digests used are present in manifest
    for digest in digests_used_set:
        if digest not in manifest_digests:
            raise ValueError(f"Used digest not present in manifest: {digest}")

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Basic type and presence checks
    if prior is None:
        raise ValueError("prior must not be None")
    try:
        from typing import TYPE_CHECKING  # dummy import to silence flake
    except Exception:
        pass
    if not isinstance(prior, InventoryValidator):
        raise TypeError("prior must be an InventoryValidator instance")

    # Ensure both inventories have an identifier
    current_id = getattr(self, "id", None)
    prior_id = getattr(prior, "id", None)
    if current_id is None or prior_id is None:
        raise ValueError("Both inventories must have an 'id' attribute")

    if current_id != prior_id:
        raise ValueError(
            f"Inventory IDs differ: current='{current_id}', prior='{prior_id}'"
        )

    # Check version numbers (higher numbers indicate newer)
    current_version = getattr(self, "version", None)
    prior_version = getattr(prior, "version", None)
    if current_version is None or prior_version is None:
        raise ValueError("Both inventories must have a 'version' attribute")

    try:
        current_num = float(current_version)
        prior_num = float(prior_version)
    except Exception:
        raise ValueError("Inventory 'version' attributes must be numeric or numeric-like")

    if prior_num > current_num:
        raise ValueError(
            f"Prior inventory has a higher version ({prior_num}) than the current inventory ({current_num})"
        )

    # Optional content consistency check: every key in prior should exist in self
    current_entries = getattr(self, "entries", None)
    prior_entries = getattr(prior, "entries", None)
    if current_entries is not None and prior_entries is not None:
        missing_keys = [
            key for key in prior_entries if key not in current_entries
        ]
        if missing_keys:
            raise ValueError(
                f"Current inventory missing entries from prior: {', '.join(missing_keys)}"
            )

    # If all checks pass, return True for convenience
    return True

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Ensure prior is the correct type
    if not isinstance(prior, InventoryValidator):
        raise TypeError("prior must be an InventoryValidator instance")
    # Ensure both objects expose an inventory
    if not hasattr(self, "inventory") or not hasattr(prior, "inventory"):
        raise AttributeError("Both objects must have an 'inventory' attribute")
    # Compare inventory IDs (if present)
    if hasattr(self.inventory, "id") and hasattr(prior.inventory, "id"):
        if self.inventory.id != prior.inventory.id:
            raise ValueError("Inventory IDs do not match")
    # Retrieve and compare version numbers
    v_self = getattr(self.inventory, "version", None)
    v_prior = getattr(prior.inventory, "version", None)
    if v_self is None or v_prior is None:
        raise ValueError("Both inventories must have a 'version' field")
    try:
        if v_prior >= v_self:
            raise ValueError(
                f"Prior inventory version ({v_prior}) must be less than current version ({v_self})"
            )
    except TypeError:
        raise TypeError("Inventory versions are not comparable")
    # Optional: compare timestamps if available
    if hasattr(self.inventory, "timestamp") and hasattr(prior.inventory, "timestamp"):
        t_self = getattr(self.inventory, "timestamp")
        t_prior = getattr(prior.inventory, "timestamp")
        try:
            if t_prior >= t_self:
                raise ValueError(
                    "Prior inventory timestamp must be earlier than current inventory"
                )
        except Exception:
            # If timestamps aren't comparable, ignore the check
            pass
    # If all checks pass, the prior inventory is valid
    return True

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.

    Parameters:
        prior (InventoryValidator): The proposed prior-version inventory.

    Returns:
        bool: ``True`` if ``prior`` is a valid prior version.

    Raises:
        TypeError: If ``prior`` is not an :class:`InventoryValidator` instance.
        AttributeError: If required attributes are missing.
        ValueError: If ``prior`` fails validation checks.
    """
    # Basic type check – use ``isinstance`` to avoid NameError if class is undefined.
    try:
        validator_cls = InventoryValidator
    except NameError:
        raise TypeError("InventoryValidator class is not available in this context")

    if not isinstance(prior, validator_cls):
        raise TypeError(f"prior must be an instance of {validator_cls.__name__}")

    # Ensure both inventories have a ``version`` attribute and that it is numeric.
    for attr_name in ('version',):
        if not hasattr(self, attr_name):
            raise AttributeError(f"Current inventory missing required attribute '{attr_name}'")
        if not hasattr(prior, attr_name):
            raise AttributeError(f"Prior inventory missing required attribute '{attr_name}'")
    if not isinstance(self.version, (int, float)):
        raise TypeError("Current inventory 'version' must be numeric")
    if not isinstance(prior.version, (int, float)):
        raise TypeError("Prior inventory 'version' must be numeric")

    # ``prior`` must be older than the current inventory.
    if prior.version >= self.version:
        raise ValueError(
            f"Prior inventory version ({prior.version}) "
            f"must be less than current inventory version ({self.version})"
        )

    # Check that the core structures of the two inventories are compatible.
    # Here we assume both inventories expose a mapping-like attribute named ``items``.
    # If the attribute is named differently, the error message will still point out
    # the missing property so that the user can adjust the implementation.
    for items_attr in ('items', 'entries', 'inventory'):
        if hasattr(prior, items_attr):
            prior_items = getattr(prior, items_attr)
            break
    else:
        raise AttributeError("Prior inventory missing 'items', 'entries', or 'inventory' attribute")

    for self_attr in ('items', 'entries', 'inventory'):
        if hasattr(self, self_attr):
            self_items = getattr(self, self_attr)
            break
    else:
        raise AttributeError("Current inventory missing 'items', 'entries', or 'inventory' attribute")

    # Ensure every key/value pair in the prior is present in the current inventory.
    # The comparison relies on equality of the associated objects.
    for key, value in prior_items.items():
        if key not in self_items:
            raise ValueError(f"Key '{key}' from prior inventory not found in current inventory")
        if self_items[key] != value:
            raise ValueError(
                f"Value mismatch for key '{key}': "
                f"prior={value!r} current={self_items[key]!r}"
            )

    return True

def validate_as_prior_version(self, prior):
        """Check that prior is a valid prior version of the current inventory object.

        The input variable prior is also expected to be an InventoryValidator object
        and both self and prior inventories are assumed to have been checked for
        internal consistency.
        """
        # Ensure that the prior object is of the correct type
        if not isinstance(prior, InventoryValidator):
            raise TypeError("prior must be an InventoryValidator instance")

        # If the prior inventory is empty, nothing to validate
        if not prior.inventory:
            return True

        # Ensure the current inventory is not missing any entries that existed in prior
        for item_id, prior_version in prior.inventory.items():
            if item_id not in self.inventory:
                raise ValueError(f"Item '{item_id}' was present in the prior inventory but is missing from the current inventory")
            current_version = self.inventory[item_id]
            if current_version < prior_version:
                raise ValueError(f"Item '{item_id}' has version {current_version} in the current inventory, which is older than the prior version {prior_version}")

        # Optionally compare timestamps if available
        if hasattr(prior, "timestamp") and hasattr(self, "timestamp"):
            if prior.timestamp > self.timestamp:
                raise ValueError("The prior inventory has a later timestamp than the current inventory")

        return True

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Validate input types
    if not isinstance(inventory, dict):
        raise TypeError(f"inventory must be a dict, got {type(inventory).__name__}")

    # Retrieve the state for the given version
    try:
        state = inventory[version]
    except KeyError:
        raise KeyError(f"Version {version!r} not found in inventory")

    # Prepare the result mapping
    logical_path_map = {}

    # Handle common representation where state is a dict mapping
    # logical_path -> file or list/set of files
    if isinstance(state, dict):
        for logical_path, files in state.items():
            if files is None:
                continue
            if isinstance(files, (list, set, tuple)):
                file_set = set(files)
            else:
                file_set = {files}
            logical_path_map[logical_path] = file_set
        return logical_path_map

    # If state is an object that provides .items() similar to a dict
    if hasattr(state, "items") and callable(state.items):
        try:
            for logical_path, files in state.items():
                if files is None:
                    continue
                if isinstance(files, (list, set, tuple)):
                    file_set = set(files)
                else:
                    file_set = {files}
                logical_path_map[logical_path] = file_set
        except Exception as exc:
            raise RuntimeError(f"Failed to iterate over state items: {exc}") from exc
        return logical_path_map

    # Attempt to interpret objects that hold a mapping of logical paths
    # via a .paths attribute or similar
    try:
        paths = getattr(state, "paths", None)
        if paths is None:
            raise AttributeError
        for logical_path in paths:
            files = getattr(state, logical_path, None)
            if files is None:
                continue
            if isinstance(files, (list, set, tuple)):
                file_set = set(files)
            else:
                file_set = {files}
            logical_path_map[logical_path] = file_set
        return logical_path_map
    except Exception:
        # If all strategies fail, raise an informative error
        raise TypeError(
            f"Unsupported state object type {type(state).__name__}; cannot extract logical path mapping"
        )
    # Should never reach here
    return logical_path_map

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
