    if isinstance(inventory, dict):
        states = inventory.get('states')
    else:
        states = getattr(inventory, 'states', None)

    if states is None:
        raise ValueError("Cannot locate 'states' in inventory")

    for state in states:
        try:
            if state.get('version') == version:
                path_map = {}
                # Expect state to have a 'paths' mapping logical_path -> iterable of files
                paths = state.get('paths', {})
                for logical_path, files in paths.items():
                    # Ensure files is an iterable; if already a set, copy it
                    if isinstance(files, set):
                        path_map[logical_path] = set(files)
                    else:
                        try:
                            path_map[logical_path] = set(files)
                        except TypeError:
                            # Fallback: single file string
                            path_map[logical_path] = {str(files)}
                return path_map
        except AttributeError:
            # If state is not a dict or missing 'get', skip
            continue

    # If we get here, the requested version was not found; return empty dict
    return {}

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    from collections import defaultdict

    def _to_numeric(v):
        try:
            return int(v)
        except Exception:
            return v

    # Determine version type for comparison
    v_cmp = _to_numeric(version)

    # Prepare the mapping
    logical_map = defaultdict(set)

    # Helper to add an item
    def _add_item(logical_path, content_file):
        if logical_path is None or content_file is None:
            return
        try:
            logical_map[logical_path].add(content_file)
        except Exception:
            # If logical_path is unhashable, skip it
            return

    # Handle inventory being dict of version -> list of entries
    try:
        if isinstance(inventory, dict):
            # If values are lists or tuples, iterate accordingly
            for inv_version, entries in inventory.items():
                if not isinstance(entries, (list, tuple)):
                    continue
                inv_v_cmp = _to_numeric(inv_version)
                # Include entries with version >= requested version
                if inv_v_cmp >= v_cmp:
                    for entry in entries:
                        # Entry may be dict, list, tuple
                        try:
                            if isinstance(entry, (list, tuple)):
                                # Assume order: logical_path, content_file, version
                                if len(entry) < 3:
                                    continue
                                logical_path, content_file, entry_version = entry[:3]
                            else:
                                # Assume dict
                                logical_path = entry.get("logical_path")
                                content_file = entry.get("content_file")
                                entry_version = entry.get("version")
                            # Check entry version matches or descendant
                            if _to_numeric(entry_version) >= v_cmp:
                                _add_item(logical_path, content_file)
                        except Exception:
                            continue
        else:
            # Assume inventory is a list of entries
            for entry in inventory:
                try:
                    if isinstance(entry, (list, tuple)):
                        if len(entry) < 3:
                            continue
                        logical_path, content_file, entry_version = entry[:3]
                    else:
                        logical_path = entry.get("logical_path")
                        content_file = entry.get("content_file")
                        entry_version = entry.get("version")
                    if _to_numeric(entry_version) >= v_cmp:
                        _add_item(logical_path, content_file)
                except Exception:
                    continue
    except Exception:
        # Unexpected structure; return empty mapping
        return {}

    return dict(logical_map)

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

