        raise TypeError("version must be a str or int")

    try:
        target_version = int(version)
    except Exception:
        target_version = version

    path_map = {}

    for comp_id, comp_info in inventory.items():
        # Handle a simple dict that maps versions directly
        if isinstance(comp_info, dict):
            # Direct lookup by version key
            if target_version in comp_info:
                entry = comp_info[target_version]
                logical_path = entry.get("logical_path")
                content_files = entry.get("content_files", set())
                if logical_path is None:
                    continue
                if logical_path in path_map:
                    path_map[logical_path].update(content_files)
                else:
                    path_map[logical_path] = set(content_files)
                continue

            # Fallback: the dict may contain a 'version' field
            if comp_info.get("version") == target_version:
                logical_path = comp_info.get("logical_path")
                content_files = comp_info.get("content_files", set())
                if logical_path is None:
                    continue
                if logical_path in path_map:
                    path_map[logical_path].update(content_files)
                else:
                    path_map[logical_path] = set(content_files)
                continue

            # Look for duplicate references in later versions
            for ver_key, entry in comp_info.items():
                try:
                    ver_num = int(ver_key)
                except Exception:
                    ver_num = ver_key
                if ver_num > target_version and isinstance(entry, dict):
                    logical_path = entry.get("logical_path")
