    if not isinstance(manifest_files, (set, list)):
        raise TypeError("`manifest_files` must be a set or list of filenames.")

    manifest_set = set(manifest_files)

    # Validate each entry in the fixity block
    for filename, hash_value in fixity.items():
        # Ensure the filename is present in the manifest
        if filename not in manifest_set:
            raise ValueError(f"Fixity references unknown file '{filename}' not present in the manifest.")

        # Basic validation of the hash value (e.g., MD5 hexadecimal string of length 32)
        if not isinstance(hash_value, str):
            raise ValueError(f"Hash value for file '{filename}' must be a string.")
        if len(hash_value) != 32 or not all(c in "0123456789abcdefABCDEF" for c in hash_value):
            raise ValueError(f"Invalid MD5 hash for file '{filename}': '{hash_value}'.")

    return True

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Validate inputs
    if fixity is None:
        # Nothing to validate
        return True

    if not hasattr(manifest_files, "__contains__"):
        raise TypeError("manifest_files must be a container supporting containment checks")

    # Ensure fixity is iterable (but not a string)
    if isinstance(fixity, str):
        raise TypeError("fixity must not be a string")
    try:
        iter(fixity)
    except TypeError:
        raise TypeError("fixity must be an iterable of file references")

    # Keep track of seen file paths to detect duplicates
    seen = set()

    for idx, entry in enumerate(fixity):
        # Accept dict or object with .path attribute
        path = None
        if isinstance(entry, dict):
            # Dictionary-based entry
            if "path" not in entry:
                raise ValueError(f"Entry {idx} in fixity does not contain a 'path' key")
            path = entry["path"]
            # Optionally check for checksum presence
            if "checksum" not in entry:
                raise ValueError(f"Entry {idx} in fixity missing 'checksum' key")
        elif hasattr(entry, "path"):
            path = getattr(entry, "path")
            if not hasattr(entry, "checksum"):
                raise ValueError(f"Entry {idx} in fixity missing 'checksum' attribute")
        else:
            raise TypeError(f"Entry {idx} in fixity is neither a dict nor has 'path' attribute")

        # Validate path type
        if not isinstance(path, (str, Path)):
            raise TypeError(f"Path for entry {idx} must be a string or pathlib.Path object")

        # Convert Path to string if needed
        path_str = str(path)

        # Check that path is in manifest
        if path_str not in manifest_files:
            raise ValueError(
                f"Path '{path_str}' referenced in fixity at index {idx} "
                "is not present in the manifest files."
            )

        # Detect duplicate paths in the fixity block
        if path_str in seen:
            raise ValueError(
                f"Duplicate reference to path '{path_str}' in fixity "
                f"at index {idx}"
            )
        seen.add(path_str)

    # If all checks passed
    return True

