def _eval_file(prefix, file_path):
    """Identifica o tipo de arquivo do pacote: `asset` ou `rendition`.

    Identifica o tipo de arquivo do pacote e atualiza ``packages`` com o tipo e
    o endereço do arquivo em análise.

    Parameters
    ----------
    prefix : str
        nome do arquivo XML sem extensão
    file_path : str
        caminho completo do arquivo

    Returns
    -------
    dict
        A dict containing ``type`` (``asset`` or ``rendition``) and ``path``.
    """
    # Validate input types
    if not isinstance(prefix, str):
        raise TypeError(f"Expected prefix to be str, got {type(prefix).__name__}")
    if not isinstance(file_path, str):
        raise TypeError(f"Expected file_path to be str, got {type(file_path).__name__}")

    # Normalise to lower case for case-insensitive matching
    prefix_lower = prefix.lower()
    path_lower = file_path.lower()

    # Heuristics to decide between asset and rendition
    if "rendition" in prefix_lower or "rendition" in path_lower or "rend" in prefix_lower:
        file_type = "rendition"
    elif "asset" in prefix_lower or "asset" in path_lower:
        file_type = "asset"
    else:
        # Default heuristic – if extension seems related to media
        if path_lower.endswith((".jpg", ".jpeg", ".png", ".gif", ".mp4", ".mp3")):
            file_type = "asset"
        else:
            # Ambiguous, default to asset but warn
            file_type = "asset"

    result = {"type": file_type, "path": file_path}

    # If a global `packages` dict is in scope, update it; otherwise just return result
    try:
        packages  # noqa: F821  # noqa: F821 to silence lint if packages not defined
    except NameError:
        return result
    else:
        # Safely update packages (if dict); ignore if not
        if isinstance(packages, dict):
            if "packages" not in packages:
                packages["packages"] = {}
            # Use prefix as key to avoid collision
            packages["packages"][prefix] = result
        return result

def add_rendition(self, lang, file_path):
    """Add a rendition mapping for the given language to this element.

    Args:
        lang (str): Language code (e.g., "en", "pt").
        file_path (str): Path to the rendition file.

    Raises:
        ValueError: If lang or file_path is not a string or empty.
    """
    # Basic validation of inputs
    if not isinstance(lang, str) or not lang:
        raise ValueError("lang must be a non-empty string")
    if not isinstance(file_path, str) or not file_path:
        raise ValueError("file_path must be a non-empty string")

    # Store the rendition in an internal dictionary for quick access
    if not hasattr(self, "_renditions"):
        self._renditions = {}
    self._renditions[lang] = file_path

    # Try to add a child element that represents the rendition.
    # The exact class name and constructor may differ; we attempt common patterns.
    try:
        # Assume a Rendition class that can be constructed with lang and href
        rendition = Rendition(lang=lang, href=file_path)
        # Common ways to add a child in XML‑style trees
        if hasattr(self, "addchild"):
            self.addchild(rendition)
        elif hasattr(self, "append"):
            self.append(rendition)
        elif hasattr(self, "children"):
            self.children.append(rendition)
        else:
            # If no obvious method exists, store the rendition object in a list
            if not hasattr(self, "_rendition_objects"):
                self._rendition_objects = []
            self._rendition_objects.append(rendition)
    except NameError:
        # Rendition class is not defined in this context; silently ignore
        pass
    except Exception as exc:
        # Any other error during child creation should be surfaced
        raise RuntimeError(f"Failed to add rendition for language '{lang}': {exc}") from exc

