def pretty(self, indent=0, debug=False):
    """Return a pretty formatted representation of self."""
    # Build the indent string
    indent_str = ' ' * indent
    parts = []

    # Basic element description
    desc = f"{indent_str}{self.__class__.__name__}"
    attrs = []

    # Include common attributes (id, class, etc.) if they exist
    for attr in ('id', 'cls'):
        value = getattr(self, attr, None)
        if value:
            attrs.append(f"{attr}='{value}'")

    if attrs:
        desc += " (" + ", ".join(attrs) + ")"

    parts.append(desc)

    # Optional debug information
    if debug:
        # Show number of direct children
        try:
            child_count = sum(1 for _ in self)
            parts.append(f"{indent_str}  ({child_count} children, type={type(self).__name__})")
        except Exception:
            # If iteration fails, skip
            pass

    # Recursively pretty-print each child
    for child in self:
        # Some child objects may not have pretty; skip those
        try:
            parts.append(child.pretty(indent + 2, debug))
        except AttributeError:
            # Fallback to simple representation
            parts.append(f"{indent_str}  {repr(child)}")

    return "\n".join(parts)

def pretty(self, indent=0, debug=False):
    """Return a pretty formatted representation of self."""
    def _format(node, level):
        indent_str = '  ' * level
        # Detect XML-like element objects
        tag = getattr(node, "tag", None)
        if tag:
            parts = [f"{indent_str}<{tag}"]
            # attributes
            attrs = getattr(node, "attributes", None)
            if attrs:
                for k, v in sorted(attrs.items()):
                    parts.append(f' {k}="{v}"')
            parts.append(">")
            # text content
            text = getattr(node, "text", None)
            if text:
                parts.append(text)
            # children
            # Check if node is iterable (has __iter__ but not str/bytes)
            if hasattr(node, "__iter__") and not isinstance(node, (str, bytes, bytearray)):
                for child in node:
                    parts.append("\n" + _format(child, level + 1))
                parts.append(f"\n{indent_str}</{tag}>")
            else:
                parts.append(f"</{tag}>")
            return "".join(parts)
        # Fallback: generic object representation
        return f"{indent_str}{repr(node)}"

    try:
        return _format(self, indent)
    except Exception as exc:
        if debug:
            raise
        return f"<Error pretty printing: {exc}>"

def pretty(self, indent=0, debug=False):
    """Return a pretty formatted representation of self."""
    # Basic type checks for the public API
    if not isinstance(indent, int) or indent < 0:
        raise ValueError("indent must be a non‑negative integer")
    if not isinstance(debug, bool):
        raise ValueError("debug must be a boolean")

    # Build the first line: class name and optional id
    parts = [f"{' ' * indent}{self.__class__.__name__}"]
    element_id = getattr(self, "id", None)
    if element_id is not None:
        parts.append(f"(id={element_id})")

    # Gather non‑internal attributes (excluding children and doc handles)
    attrs = {}
    for name, value in vars(self).items():
        if name in ("children", "doc"):
            continue
        if name.startswith("_"):
            continue
        attrs[name] = value

    if attrs:
        attr_str = ", ".join(f"{k}={v!r}" for k, v in attrs.items())
        parts.append(f" [{attr_str}]")

    # If there is a children iterable, render each child
    child_output = []
    children = getattr(self, "children", None)
    if children is not None:
        try:
            for child in children:
                try:
                    child_output.append(child.pretty(indent + 2, debug))
                except Exception:
                    # Fallback if child does not support pretty
                    child_output.append(f"{' ' * (indent + 2)}<unprintable child>")
        except TypeError:
            # children attribute is not iterable
            child_output.append(f"{' ' * (indent + 2)}<invalid children>")

    if child_output:
        parts.append("\n" + "\n".join(child_output))

    return "".join(parts)

def pretty(self, indent=0, debug=False):
        """
        Return a pretty formatted representation of self.
        """
        if not isinstance(indent, int) or indent < 0:
            raise ValueError("indent must be a non‑negative integer")
        # base indentation
        pad = '  ' * indent
        try:
            # Gather public attributes for display (skip private and callables)
            attrs = {k: v for k, v in vars(self).items()
                     if not k.startswith('_') and not callable(v)}
            attr_str = ', '.join(f"{k}={v!r}" for k, v in attrs.items())
            header = f"{pad}{self.__class__.__name__}({attr_str})"
        except Exception:
            header = f"{pad}{self.__class__.__name__}()"
        # If the element is iterable, pretty‑print its children
        children_str = []
        if hasattr(self, '__iter__'):
            for child in self:
                # Use the child's pretty method if available
                if hasattr(child, 'pretty'):
                    children_str.append(child.pretty(indent + 1, debug))
                else:
                    children_str.append(f"{'  ' * (indent + 1)}{repr(child)}")
        if children_str:
            body = '\n'.join(children_str)
            result = f"{header}\n{body}\n{pad}"
        else:
            result = header
        # Optionally append debug information
        if debug:
            try:
                result += f"  # debug: {self!r}"
            except Exception:
                result += "  # debug: <unrepresentable>"
        return result

def pretty(self, indent=0, debug=False):
    """Return a pretty formatted representation of self."""
    indent_str = ' ' * indent
    if debug:
        try:
            identifier = getattr(self, 'id', None)
            title = f"{indent_str}{self.__class__.__name__} (id={identifier})"
        except Exception:
            title = f"{indent_str}{self.__class__.__name__}"
    else:
        title = f"{indent_str}{self.__class__.__name__}"
    parts = [title]
    try:
        # Attempt to iterate over children if possible
        children = list(self)
        if children:
            for child in children:
                parts.append(child.pretty(indent + 4, debug=debug))
    except TypeError:
        # Not iterable – no children
        pass
    return '\n'.join(parts)

def absorb(self, args):
    """Given an ``args`` sequence of expressions, return a new list of
    expression applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    # Work on a mutable copy
    exprs = list(args)

    def _operator(expr):
        """Return the operator of a composite expression.

        This helper assumes that composite expression objects expose an
        ``operator`` attribute exposing a string such as ``'AND'``, ``'OR'``,
        or ``'NOT'``.  If the attribute is not present the function
        returns ``None``."""
        return getattr(expr, "operator", None)

    def _children(expr):
        """Return the children list of a composite expression.

        This helper assumes that composite expression objects expose a
        ``children`` list.  If the attribute is missing, an empty list is
        returned."""
        return getattr(expr, "children", [])

    def _make_composite(op, left, right):
        """Create a new composite expression.

        Concrete expression classes are application specific.  It is
        assumed that a class constructor takes the operator name and
        a list of children.  If the constructor does not match this
        signature, :class:`SyntaxError` is raised."""
        try:
            return type(left)(operator=op, children=[left, right])
        except Exception as exc:
            raise SyntaxError("Cannot construct %s expression" % op) from exc

    def _negation_of(expr, target):
        """Return ``True`` if ``expr`` is a negation of ``target``."""
        return _operator(expr) == "NOT" and _children(expr) and _children(expr)[0] == target

    def _apply_absorption(a, b):
        """Apply the absorption/negative absorption rules to a pair of
        expressions.  The function returns a simplified expression if a
        rule applies, otherwise it returns ``None``."""
        # Simple equality shortcut
        if a == b:
            return a

        op_a = _operator(a)
        op_b = _operator(b)
        ch_a = _children(a)
        ch_b = _children(b)

        # A & (A | B)  ->  A
        if op_a == "AND" and op_b == "OR" and a in ch_b:
            return a

        # A | (A & B)  ->  A
        if op_a == "OR" and op_b == "AND" and a in ch_b:
            return a

        # Negative absorption:
        # A & (~A | B) -> A & B
        if op_a == "AND":
            for c in ch_b:
                if _negation_of(c, a):
                    # find the other child of the OR
                    other = [x for x in ch_b if x is not c]
                    if other:
                        return _make_composite("AND", a, other[0])

        # A | (~A & B) -> A | B
        if op_a == "OR":
            for c in ch_b:
                if _negation_of(c, a):
                    other = [x for x in ch_b if x is not c]
                    if other:
                        return _make_composite("OR", a, other[0])

        return None

    # Iteratively apply absorption until no further changes.
    changed = True
    while changed:
        changed = False
        new_exprs = []
        used = set()
        for i, e1 in enumerate(exprs):
            if i in used:
                continue
            simplified = e1
            for j, e2 in enumerate(exprs):
                if i == j or j in used:
                    continue
                result = _apply_absorption(simplified, e2)
                if result is not None and result != simplified:
                    simplified = result
                    used.add(j)
                    changed = True
            new_exprs.append(simplified)
        exprs = new_exprs

    return exprs

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    def _apply(expr):
        """
        Recursively apply absorption rules to a single expression.
        Expressions are expected to be tuples of the form
            ('&', left, right) or ('|', left, right) or ('~', operand)
        Basic objects (e.g., variables) are left unchanged.
        """
        if isinstance(expr, tuple) and len(expr) >= 3:
            op = expr[0]
            left = expr[1]
            right = expr[2]
            # First apply recursively to sub‑expressions
            left_s = _apply(left)
            right_s = _apply(right)
            # Reconstruct after recursion
            new_expr = (op, left_s, right_s)

            # Absorption law
            if op == '&' and right_s and isinstance(right_s, tuple) and right_s[0] == '|':
                if left_s == right_s[1]:
                    # A & (A | B) -> A
                    return left_s
                if left_s == right_s[2]:
                    # A & (B | A) -> A
                    return left_s
            if op == '|' and right_s and isinstance(right_s, tuple) and right_s[0] == '&':
                if left_s == right_s[1]:
                    # A | (A & B) -> A
                    return left_s
                if left_s == right_s[2]:
                    # A | (B & A) -> A
                    return left_s

            # Negative absorption
            if op == '&':
                if right_s and isinstance(right_s, tuple) and right_s[0] == '|':
                    # A & (~A | B) -> A & B
                    neg_a = ('~', left_s)
                    if right_s[1] == neg_a:
                        return ('&', left_s, right_s[2])
                    if right_s[2] == neg_a:
                        return ('&', left_s, right_s[1])
            if op == '|':
                if right_s and isinstance(right_s, tuple) and right_s[0] == '&':
                    # A | (~A & B) -> A | B
                    neg_a = ('~', left_s)
                    if right_s[1] == neg_a:
                        return ('|', left_s, right_s[2])
                    if right_s[2] == neg_a:
                        return ('|', left_s, right_s[1])

            # If no rule applied, return the potentially simplified sub‑expressions
            return new_expr
        elif isinstance(expr, tuple) and len(expr) == 2 and expr[0] == '~':
            # negation
            return ('~', _apply(expr[1]))
        else:
            # atomic expression
            return expr

    # Apply rules to each argument, possibly iterating until no change
    simplified = []
    for a in args:
        prev = None
        current = a
        # Iteratively apply until stable
        while prev != current:
            prev = current
            current = _apply(current)
        simplified.append(current)

    return simplified

