    """Get version information or return default if unable to do so."""
    versions = {}
    # Try to get distribution version
    try:
        from importlib.metadata import version, PackageNotFoundError
        pkg_name = __package__ or __name__.split('.')[0]
        pkg_version = version(pkg_name)
        versions['dist'] = pkg_version
    except Exception:
        versions['dist'] = 'unknown'
    # Try to read a VERSION file in the root of the project
    try:
        import pathlib
        root = pathlib.Path(__file__).resolve().parent
        while root.parent != root:
            ver_file = root / 'VERSION'
            if ver_file.is_file():
                with ver_file.open('r', encoding='utf-8') as f:
                    versions['file'] = f.read().strip()
                break
            root = root.parent
        else:
            raise FileNotFoundError
    except Exception:
        versions['file'] = 'unknown'
    return versions

def get_versions():
    """Get version information or return default if unable to do so."""
    # Try to get version information from git if this repository is a git repo
    try:
        import subprocess
        # Retrieve the latest tag with additional info
        git_output = subprocess.check_output(
            ["git", "describe", "--tags", "--dirty", "--long"],
            stderr=subprocess.DEVNULL,
            text=True
        ).strip()
        # Parse output like 'v1.2.3-4-gabcd123'
        parts = git_output.split("-")
        if len(parts) >= 3:
            tag, commits, commit_hash = parts[0], parts[1], parts[2]
            if commits == "0":
                version = tag
            else:
                # Convert to PEP 440 compatible string
                version = f"{tag}+{commits}.dev{commit_hash}"
            full_rev = commit_hash
        else:
            # Fallback to raw output
            version = git_output
            full_rev = git_output
        return {"version": version, "full-revisionid": full_rev}
    except Exception:
        # If git is not available or not a repo, try retrieving package metadata
        try:
            # Use importlib.metadata for Python >=3.8
            try:
                from importlib.metadata import version as get_pkg_version
                pkg_ver = get_pkg_version(__package__ or "__main__")
                return {"version": pkg_ver, "full-revisionid": "unknown"}
            except Exception:
                pass
            # Fallback to pkg_resources if available
            try:
                import pkg_resources
                pkg_ver = pkg_resources.get_distribution(__package__ or "__main__").version
                return {"version": pkg_ver, "full-revisionid": "unknown"}
            except Exception:
                pass
        except Exception:
            pass
        # Final fallback to an unknown version
        return {"version": "0+unknown", "full-revisionid": "unknown"}

def get_versions():
    """Get version information or return default if unable to do so."""
    # Helper to execute a shell command and return its output
    def _run(cmd):
        subprocess = __import__("subprocess")
        try:
            out = subprocess.check_output(cmd, shell=True, stderr=subprocess.STDOUT)
            return out.decode("utf-8").strip()
        except Exception as exc:
            raise RuntimeError(str(exc)) from exc

    # Prepare the default return value
    default = {
        "version": "0+unknown",
        "full-revisionid": None,
        "dirty": False,
        "error": None,
    }

    try:
        os = __import__("os")

        # Check if we're in a Git repository
        if not os.path.isdir(".git") and not os.path.isdir(".svn"):
            raise RuntimeError("No VCS metadata found")

        # Get the short tag or commit hash
        desc = _run("git describe --tags --dirty --always")
        full_rev = _run("git rev-parse HEAD")
        dirty = desc.endswith("-dirty")

        return {
            "version": desc,
            "full-revisionid": full_rev,
            "dirty": dirty,
            "error": None,
        }
    except Exception as exc:
        default["error"] = str(exc)
        return default

