def register_vcs_handler(vcs, method):  # decorator
    """Create decorator to mark a method as the handler of a VCS."""
    if not isinstance(vcs, str):
        raise TypeError(f"The 'vcs' argument must be a string, got {type(vcs).__name__}.")
    if not callable(method):
        raise TypeError(f"The 'method' argument must be callable, got {type(method).__name__}.")
    # Register the handler in a module‑level registry.
    global _VCS_HANDLERS
    if "_VCS_HANDLERS" not in globals():
        _VCS_HANDLERS = {}
    if vcs in _VCS_HANDLERS:
        raise ValueError(f"A handler for VCS '{vcs}' is already registered.")
    _VCS_HANDLERS[vcs] = method
    return method

def register_vcs_handler(vcs, method):
    """Create decorator to mark a method as the handler of a VCS.

    This helper can be used in two ways:

    1. As a plain decorator with argument:

        @register_vcs_handler('git')
        def handle_git(...):
            ...

    2. As a direct registration call:

        @register_vcs_handler('git', handle_git)
        def handle_git(...):
            ...

    In both cases the function is stored in a module-level registry
    ``_VCS_HANDLERS`` mapping the VCS name to the callable.

    Args:
        vcs (str): Identifier for the version control system.
        method (callable or None): The method to register.  If ``None``,
            the function returns a decorator waiting for the callable.

    Returns:
        callable: The original method (when registered) or a decorator
        that accepts the method.

    Raises:
        TypeError: If ``vcs`` is not a string or ``method`` is not callable
        (when attempting to register).
    """
    try:
        # If ``method`` is not given or is a placeholder, we return a decorator
        if method is None or not callable(method):
            def decorator(func):
                return register_vcs_handler(vcs, func)
            return decorator

        if not isinstance(vcs, str):
            raise TypeError("vcs must be a string identifier")

        registry = globals().setdefault('_VCS_HANDLERS', {})
        if not callable(method):
            raise TypeError("method must be callable")

        # Store the handler; overwrite any existing handler for the same VCS.
        registry[vcs] = method
        return method
    except Exception as e:
        raise type(e)(f"Failed to register VCS handler for '{vcs}': {e}") from e

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    # Validate input types
    if not isinstance(validate_objects, bool):
        raise TypeError("validate_objects must be a boolean")
    if not isinstance(check_digests, bool):
        raise TypeError("check_digests must be a boolean")
    if not isinstance(show_warnings, bool):
        raise TypeError("show_warnings must be a boolean")

    num_objects = 0
    good_objects = 0
    stack = [self]

    while stack:
        obj = stack.pop()
        num_objects += 1

        # Assume each object is valid unless proven otherwise
        obj_valid = True
        digest_valid = True

        # Validate the object itself
        if validate_objects:
            try:
                if hasattr(obj, "validate") and callable(obj.validate):
                    obj_valid = bool(obj.validate())
                elif hasattr(obj, "is_valid") and callable(obj.is_valid):
                    obj_valid = bool(obj.is_valid())
                # If neither method exists we consider the object valid by default
            except Exception as exc:
                obj_valid = False
                if show_warnings:
                    try:
                        identifier = getattr(obj, "id", repr(obj))
                    except Exception:
                        identifier = repr(obj)
                    print(f"Warning: validation exception for {identifier}: {exc}")

        # Check the digest of the object
        if check_digests:
            try:
                if hasattr(obj, "check_digest") and callable(obj.check_digest):
                    digest_valid = bool(obj.check_digest())
                # If no method exists assume digest is valid
            except Exception as exc:
                digest_valid = False
                if show_warnings:
                    try:
                        identifier = getattr(obj, "id", repr(obj))
                    except Exception:
                        identifier = repr(obj)
                    print(f"Warning: digest check exception for {identifier}: {exc}")

        if obj_valid and digest_valid:
            good_objects += 1

        # Add children for recursive processing, if any
        try:
            # Only extend if the object is iterable and not a string/bytes
            if hasattr(obj, "__iter__") and not isinstance(obj, (str, bytes)):
                stack.extend(list(obj))
        except Exception:
            # Non‑iterable or error in iteration - skip
            pass

    return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    def _iter_recursive(node):
        """Yield a node and recursively yield its children."""
        stack = [node]
        while stack:
            current = stack.pop()
            yield current
            # Attempt to iterate over children if possible
            try:
                children = list(current)
            except Exception:
                children = []
            stack.extend(children)

    num_objects = 0
    good_objects = 0

    for obj in _iter_recursive(self):
        num_objects += 1
        is_valid = True

        # Validate the object itself if requested
        if validate_objects:
            try:
                # If the object has a validate method that returns a bool
                if hasattr(obj, "validate") and callable(obj.validate):
                    is_valid = obj.validate()
                # If validate raises an exception, treat as invalid
                else:
                    # Assume validity if no validate method
                    is_valid = True
            except Exception as exc:
                is_valid = False
                if show_warnings:
                    print(f"Warning: validation exception for {obj!r}: {exc}")

        # Check digest if requested and still valid so far
        if check_digests and is_valid:
            try:
                if hasattr(obj, "get_digest") and hasattr(obj, "_expected_digest"):
                    current_digest = obj.get_digest()
                    expected_digest = obj._expected_digest
                    if current_digest != expected_digest:
                        is_valid = False
                        if show_warnings:
                            print(f"Warning: digest mismatch for {obj!r}")
                else:
                    # Skip digest check if not available
                    pass
            except Exception as exc:
                is_valid = False
                if show_warnings:
                    print(f"Warning: digest check exception for {obj!r}: {exc}")

        if is_valid:
            good_objects += 1

    return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    # Validate input types
    if not isinstance(validate_objects, bool):
        raise TypeError("validate_objects must be a boolean.")
    if not isinstance(check_digests, bool):
        raise TypeError("check_digests must be a boolean.")
    if not isinstance(show_warnings, bool):
        raise TypeError("show_warnings must be a boolean.")

    num_objects = 0
    good_objects = 0

    # Use a stack for depth‑first traversal to avoid recursion limits
    stack = [self]

    while stack:
        item = stack.pop()
        num_objects += 1

        is_valid = True

        # Validate the object itself if requested
        if validate_objects:
            validate_method = getattr(item, "validate", None)
            if callable(validate_method):
                try:
                    # validate() is expected to return a truthy value on success
                    result = validate_method()
                    if not result:
                        is_valid = False
                except Exception as e:
                    is_valid = False
                    if show_warnings:
                        print(f"Warning: validation failed for {item!r}: {e}")

        # Check digests if requested
        if check_digests:
            digest_method = getattr(item, "check_digest", None)
            if callable(digest_method):
                try:
                    if not digest_method():
                        is_valid = False
                        if show_warnings:
                            print(f"Warning: digest mismatch for {item!r}")
                except Exception as e:
                    is_valid = False
                    if show_warnings:
                        print(f"Warning: digest check raised an exception for {item!r}: {e}")

        if is_valid:
            good_objects += 1

        # Add children to the stack if the current item is iterable
        if hasattr(item, "__iter__"):
            try:
                for child in item:
                    stack.append(child)
            except Exception:
                # If iteration fails, we simply skip children
                pass

    return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    # Validate input types
    if not isinstance(validate_objects, bool):
        raise ValueError("validate_objects must be a bool")
    if not isinstance(check_digests, bool):
        raise ValueError("check_digests must be a bool")
    if not isinstance(show_warnings, bool):
        raise ValueError("show_warnings must be a bool")

    # Determine a convenient way to iterate over all child objects.
    # Prefer a custom iterator if available, otherwise fall back to
    # a recursive walk over attributes that are instances of AbstractElement.
    def _iter_objects(obj):
        if hasattr(obj, "children") and hasattr(obj, "__iter__"):
            for child in obj:
                yield child
                yield from _iter_objects(child)
        else:
            # Fallback: iterate over attributes that look like objects
            for attr in dir(obj):
                candidate = getattr(obj, attr)
                if isinstance(candidate, type(self)) and candidate is not obj:
                    yield candidate
                    yield from _iter_objects(candidate)

    # Use a safe logging helper
    def _log(msg):
        if hasattr(self, "log_warning"):
            self.log_warning(msg)
        else:
            # default to printing if logger not available
            print(msg)

    num_objects = 0
    good_objects = 0

    for obj in _iter_objects(self):
        num_objects += 1
        valid = True
        if validate_objects:
            try:
                # Assume each object has a validate() method returning bool
                if hasattr(obj, "validate") and callable(getattr(obj, "validate")):
                    valid = obj.validate()
                else:
                    # If no validate method, consider it valid by default
                    valid = True
            except Exception as exc:
                valid = False
                if show_warnings:
                    _log(f"Validation failed for object {obj}: {exc}")

        if check_digests and valid:
            try:
                # Prefer a dedicated digest check method or compare stored digest
                digest_ok = True
                if hasattr(obj, "check_digest") and callable(getattr(obj, "check_digest")):
                    digest_ok = obj.check_digest()
                elif hasattr(obj, "digest") and hasattr(obj, "stored_digest"):
                    # Simple comparison, adjust as needed for the real implementation
                    digest_ok = (obj.digest == getattr(obj, "stored_digest", None))
                else:
                    digest_ok = True  # If no digest info, assume OK
                if not digest_ok:
                    valid = False
                    if show_warnings:
                        _log(f"Digest mismatch for object {obj}")
            except Exception as exc:
                valid = False
                if show_warnings:
                    _log(f"Digest check failed for object {obj}: {exc}")

        if valid:
            good_objects += 1

    return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
        """Validate storage root hierarchy.

        Returns:
            num_objects - number of objects checked
            good_objects - number of objects checked that were found to be valid
        """
        num_objects = 0
        good_objects = 0
        stack = [self]

        while stack:
            node = stack.pop()
            num_objects += 1

            # Assume node is valid until proven otherwise
            is_valid = True

            if validate_objects and hasattr(node, "validate"):
                try:
                    node.validate()
                except Exception as exc:
                    is_valid = False
                    if show_warnings:
                        try:
                            name = getattr(node, "id", str(type(node)))
                        except Exception:
                            name = str(type(node))
                        print(f"Validation failed for {name}: {exc}")

            if check_digests and hasattr(node, "check_digest"):
                try:
                    node.check_digest()
