                    children = None
            # Fallback to a 'children' attribute if available
            if children is None and hasattr(node, "children"):
                try:
                    children = node.children
                except Exception:
                    children = None

            if children:
                # Ensure children is an iterable
                try:
                    stack.extend(children)
