def initialize(self):
    """Create and initialize a new OCFL storage root."""
    import os
    root = getattr(self, 'path', None)
    if not root:
        raise ValueError("Root path not set.")
    if os.path.exists(root):
        raise FileExistsError(f"Root path '{root}' already exists.")
    try:
        os.makedirs(root, exist_ok=False)
        # Create necessary subdirectories for OCFL storage
        os.makedirs(os.path.join(root, 'objects'), exist_ok=False)
        os.makedirs(os.path.join(root, 'manifest'), exist_ok=False)
    except OSError as exc:
        raise RuntimeError(f"Failed to initialize OCFL storage root at {root}") from exc

def initialize(self):
    """Create and initialize a new OCFL storage root."""
    try:
        root = getattr(self, 'root_path', None)
        if root is None or not isinstance(root, str):
            raise ValueError("self.root_path must be set to a valid directory path")
        if not os.path.isdir(root):
            os.makedirs(root, exist_ok=True)
        ocfl_file = os.path.join(root, '.ocfl_root')
        if os.path.exists(ocfl_file):
            raise FileExistsError(f"OCFL root already initialized at {root}")
        with open(ocfl_file, 'w') as f:
            f.write('OCFL v1.0\n')
        self.initialized = True
    except Exception as e:
        raise RuntimeError(f"Failed to initialize OCFL root: {e}") from e

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str):
        raise TypeError("version must be a string")

    # Preserve leading 'v' or 'V' if present
    prefix = ''
    if version.lower().startswith('v'):
        prefix = version[0]
        version = version[1:]

    parts = version.split('.')
    if not parts:
        raise ValueError("Invalid version string")

    # Find the last numeric part
    for i in range(len(parts) - 1, -1, -1):
        part = parts[i]
        if part.isdigit():
            width = len(part)
            try:
                number = int(part)
            except ValueError:
                raise ValueError(f"Invalid numeric part in version: {part}")
            new_number = number + 1
            new_part = str(new_number).zfill(width)
            parts[i] = new_part
            return prefix + '.'.join(parts)

    # No numeric part found
    raise ValueError("No numeric part found in version string")

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str):
        raise TypeError("version must be a string")
    if not version.isdigit():
        raise ValueError("version must contain only digits")
    # Increment numeric value
    num = int(version) + 1
    # Preserve leading zero padding if present
    if len(version) > 1 and version.startswith("0"):
        return str(num).zfill(len(version))
    return str(num)

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str):
        raise TypeError("version must be a string")
    if not version:
        raise ValueError("empty version string")

    # Check if the string is purely numeric
    if not version.isdigit():
        raise ValueError("version must be a purely numeric string")

    # Determine if there are leading zeros
    has_leading_zeros = version.startswith('0') and len(version) > 1

    # Compute next numeric value
    try:
        num = int(version)
    except ValueError as exc:
        raise ValueError("invalid numeric value") from exc

    next_num = num + 1

    if has_leading_zeros:
        # Preserve original width (including leading zeros)
        width = len(version)
        return str(next_num).zfill(width)
    else:
        return str(next_num)

def validate_version_inventories(self, version_dirs):
    """
    Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    import os
    import json
    import xml.etree.ElementTree as ET

    # Helper to load an inventory file into a dict: href -> digest
    def _load_inventory(path):
        inv = {}
        if os.path.isfile(path):
            try:
                # Try XML first
                tree = ET.parse(path)
                root = tree.getroot()
                for file_elem in root.findall('.//file'):
                    href = file_elem.get('href')
                    digest = file_elem.get('digest')
                    if href and digest:
                        inv[href] = digest
                if inv:
                    return inv
            except Exception:
                pass  # fall back to JSON
        if os.path.isfile(path):
            try:
                with open(path, 'r', encoding='utf-8') as f:
                    data = json.load(f)
                if isinstance(data, dict):
                    return data
                # some JSON inventories store as list of objects
                for entry in data:
                    href = entry.get('href')
                    digest = entry.get('digest')
                    if href and digest:
                        inv[href] = digest
                return inv
            except Exception:
                pass
        raise FileNotFoundError(f"Inventory file not found: {path}")

    # Determine root inventory from the last version if not already present
    if hasattr(self, 'root_inventory') and isinstance(self.root_inventory, dict):
        root_inventory = self.root_inventory
    else:
        # load inventory from the last version directory as root
        last_dir = version_dirs[-1]
        inv_path_xml = os.path.join(last_dir, 'inventory.xml')
        inv_path_json = os.path.join(last_dir, 'inventory.json')
        root_inventory = {}
        for p in (inv_path_xml, inv_path_json):
            try:
                root_inventory = _load_inventory(p)
                break
            except Exception:
                continue
        # store for later reference
        self.root_inventory = root_inventory

    # Track digests that differ from root
    self.different_digests = []

    # Track cumulative inventory entries up to current version
    cumulative_inventory = {}

    for idx, dir_name in enumerate(version_dirs, start=1):
        inv_path_xml = os.path.join(dir_name, 'inventory.xml')
        inv_path_json = os.path.join(dir_name, 'inventory.json')

        try:
            inventory = _load_inventory(inv_path_xml)
        except FileNotFoundError:
            try:
                inventory = _load_inventory(inv_path_json)
            except FileNotFoundError:
                raise FileNotFoundError(f"No inventory found for version directory '{dir_name}'")

        # Verify that current inventory contains all entries from previous versions
        missing_files = [href for href in cumulative_inventory if href not in inventory]
        if missing_files:
            raise ValueError(
                f"Inventory in version '{dir_name}' is missing files from previous versions: {missing_files}"
            )

        # Update cumulative inventory with new entries
        cumulative_inventory.update(inventory)

        # Compare current digests with root inventory
        for href, digest in inventory.items():
            root_digest = root_inventory.get(href)
            if root_digest is not None and root_digest != digest:
                self.different_digests.append({
                    'file': href,
                    'version': idx,
                    'current_digest': digest,
                    'root_digest': root_digest
                })

    # Method performs validation and records discrepancies in self.different_digests
    # No explicit return value is required.

def validate_version_inventories(self, version_dirs):
        """Each version SHOULD have an inventory up to that point.

        Also keep a record of any content digests different from those in the
        root inventory so that we can also check them when validating the
        content.

        Parameters
        ----------
        version_dirs : list[str]
            An array of version directory names of the form ``'1'``, ``'2'``,
            ``'3'``, ... and is assumed to be in version sequence.
        """
        import os
        import json

        # validate input
        if not isinstance(version_dirs, (list, tuple)):
            raise TypeError("`version_dirs` must be a list or tuple of directory names")

        # collect digests that differ from the root inventory
        self.version_digests = {}
        # root inventory is expected to be a dict mapping relative paths to
        # digests; fall back to an empty dict if it is missing
        root_inventory = getattr(self, "root_inventory", {})

        # accumulate all entries seen so far so we can detect missing files
        all_entries = {}

        for idx, vdir in enumerate(version_dirs):
            if not isinstance(vdir, str):
                raise TypeError(f"each element of `version_dirs` must be a string, got {type(vdir)}")
            inventory_path = os.path.join(vdir, "inventory.json")
            try:
                with open(inventory_path, "r", encoding="utf-8") as fh:
                    inventory = json.load(fh)
            except FileNotFoundError:
                raise FileNotFoundError(f"Inventory file not found in directory '{vdir}'")
            except json.JSONDecodeError as exc:
                raise ValueError(f"Invalid JSON inventory in directory '{vdir}': {exc}")

            if not isinstance(inventory, dict):
                raise ValueError(f"Inventory in '{vdir}' must be a mapping of paths to digests")

            # check that each later inventory contains all entries from earlier inventories
            if idx > 0:
                missing = [path for path in all_entries if path not in inventory]
                if missing:
                    raise ValueError(
                        f"Inventory in '{vdir}' is missing entries from previous version(s): {missing}"
                    )

            # determine differences relative to the root inventory
            diff = {}
            for path, digest in inventory.items():
                root_digest = root_inventory.get(path)
                if root_digest is None:
                    # new content relative to the root
                    diff[path] = {"root": None, "current": digest}
                elif root_digest != digest:
                    # changed digest relative to the root
                    diff[path] = {"root": root_digest, "current": digest}

            self.version_digests[vdir] = diff
            all_entries.update(inventory)

        return self.version_digests

def validate_version_inventories(self, version_dirs):
        """Each version SHOULD have an inventory up to that point.

        Also keep a record of any content digests different from those in the root inventory
        so that we can also check them when validating the content.

        version_dirs is an array of version directory names and is assumed to be in
        version sequence (1, 2, 3...).
        """
        # initialise container for differences if not already present
        if not hasattr(self, "diff_inventory_digests"):
            self.diff_inventory_digests = {}
        if not hasattr(self, "errors"):
            self.errors = []

        # root inventory digest cache to compare against
        root_digest = None
        if hasattr(self, "root_inventory_digest"):
            root_digest = self.root_inventory_digest

        for idx, ver_dir in enumerate(version_dirs, start=1):
            # Inventories should exist for each version directory
            # Assume inventory file is named 'inventory.xml' inside the version dir
            inv_path = str(ver_dir).rstrip('/') + '/inventory.xml'
            try:
                with open(inv_path, 'r', encoding='utf-8') as f:
                    lines = f.readlines()
            except Exception as e:
                self.errors.append(f"Could not read inventory for version {idx} at '{inv_path}': {e}")
                continue

            # Basic extraction of digest from inventory, expecting a line like <digest>...</digest>
            digest = None
            for line in lines:
                if "<digest>" in line:
                    start = line.find("<digest>") + len("<digest>")
                    end = line.find("</digest>", start)
                    if end != -1:
                        digest = line[start:end].strip()
                        break

            if digest is None:
                self.errors.append(f"Could not find digest in inventory for version {idx} at '{inv_path}'")
                continue

            # Compare against root digest if available
            if root_digest is not None and digest != root_digest:
                # Record difference
                self.diff_inventory_digests.setdefault(idx, []).append({
                    'inventory_path': inv_path,
                    'root_digest': root_digest,
                    'version_digest': digest
                })

            # Update root_digest for subsequent comparisons if this is first or if missing from earlier versions
            if root_digest is None:
                root_digest = digest

        # After processing all directories, optionally return a summary
        return {
            'differences': self.diff_inventory_digests,
            'errors': self.errors
        }

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    Parameters:
        version_dirs (Iterable[str]): An array of version directory names
            and is assumed to be in version sequence (1, 2, 3...).

    Returns:
        dict: {
            'errors': List[str]           # problems reading or missing inventories
            'differences': List[dict]     # files whose digests differ from the root
        }

    Raises:
        None – all errors are collected in the returned dictionary instead.
    """
    # Import modules locally to avoid global imports
    try:
        import os
        import xml.etree.ElementTree as ET
    except Exception as exc:
        raise RuntimeError(f"Required modules not available: {exc}")

    root_inventory = None
    differences = []
    errors = []

    for idx, dir_name in enumerate(version_dirs):
        inv_path = os.path.join(dir_name, 'inventory.xml')
        if not os.path.exists(inv_path):
            errors.append(f"Missing inventory file in directory '{dir_name}'.")
            continue
        try:
            tree = ET.parse(inv_path)
            root = tree.getroot()
        except Exception as exc:
            errors.append(f"Failed to parse inventory in '{dir_name}': {exc}")
            continue

        # Build a mapping of file path → digest
        current_inv = {}
        # Accept either <file> tags or whatever the schema uses
        for fe in root.findall('.//file'):
            path = fe.get('path')
            digest = fe.get('digest')
            if path and digest:
                current_inv[path] = digest

        if idx == 0:
            # The first inventory is considered the “root” reference
            root_inventory = current_inv
            continue

        if root_inventory is None:
            errors.append(f"Cannot compare inventory in '{dir_name}' – root inventory is missing.")
            continue

        # Compare files
        for path, digest in current_inv.items():
            root_digest = root_inventory.get(path)
            if root_digest is None:
                # New file appearing in a later version
                continue
            if digest != root_digest:
                differences.append({
                    'file': path,
                    'root_digest': root_digest,
                    'version_digest': digest,
                    'version_dir': dir_name,
                })

    return {'errors': errors, 'differences': differences}

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    import os
    import json

    # Helper to load an inventory JSON file
    def _load_inventory(inv_path):
        try:
            with open(inv_path, 'r', encoding='utf-8') as f:
                return json.load(f)
        except FileNotFoundError:
            raise ValueError(f"Inventory file not found: {inv_path}")
        except json.JSONDecodeError as e:
            raise ValueError(f"Invalid JSON in inventory {inv_path}: {e}")

    # Determine root directory and root inventory
    root_dir = getattr(self, 'root_dir', os.getcwd())
    root_inv_path = os.path.join(root_dir, 'inventory.json')
    root_inv = _load_inventory(root_inv_path)

    # Dict to hold discovered digest mismatches: {file_path: (root_digest, version_digest)}
    digest_mismatches = {}

    for idx, dir_name in enumerate(version_dirs, start=1):
        version_path = os.path.join(root_dir, dir_name, 'inventory.json')
        version_inv = _load_inventory(version_path)

        # Ensure every entry in the version inventory is present in the root inventory
        missing_in_root = [k for k in version_inv if k not in root_inv]
        if missing_in_root:
            raise ValueError(
                f"Version '{dir_name}' missing entries in root inventory: {missing_in_root}"
            )

        # Record any digest differences
        for key, version_digest in version_inv.items():
            root_digest = root_inv.get(key)
            if root_digest != version_digest:
                digest_mismatches[key] = (root_digest, version_digest)

    # Return the mismatches; callers can decide how to handle them
    return digest_mismatches

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=* Namaste files to determine the directory type.
    """
    from pathlib import Path
    p = Path(path)

    if not p.exists():
        return "path does not exist"

    # Handle explicit file paths
    if p.is_file():
        if p.name.lower() == "namaste":
            try:
                lines = p.read_text(encoding="utf-8").splitlines()
            except Exception as e:
                return f"error reading NAMASTE: {e}"
            for line in lines:
                if line.startswith("0="):
                    content = line[2:].strip()
                    if content == "*":
                        return "root"
                    else:
                        return "object"
            return "file"
        else:
            return "file"

    # Handle directories
    namaste_file = p / "NAMASTE"
    if namaste_file.is_file():
        try:
            lines = namaste_file.read_text(encoding="utf-8").splitlines()
        except Exception as e:
            return f"error reading NAMASTE: {e}"
        for line in lines:
            if line.startswith("0="):
                content = line[2:].strip()
                if content == "*":
                    return "root"
                else:
                    return "object"
        # NAMASTE exists but does not contain a 0= line
        return "file"

    return f"no NAMASTE file found at {p}"

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    try:
        import os
    except Exception:
        return "Error: unable to import required modules"

    p = os.path.abspath(path)

    if not os.path.exists(p):
        return f"Not found: {p}"

    if os.path.isfile(p):
        return "file"

    if os.path.isdir(p):
        # Check for root: presence of .well-known/ocfl directory
        well_known = os.path.join(p, ".well-known", "ocfl")
        if os.path.isdir(well_known):
            return "root"

        # Check for object: presence of a directory starting with "0="
        try:
            for entry in os.listdir(p):
                full = os.path.join(p, entry)
                if os.path.isdir(full) and entry.startswith("0="):
                    # If the directory is an object, it typically has no other
                    # non-hidden subdirectories aside from the 0=... dir itself.
                    return "object"
        except PermissionError as exc:
            return f"Permission denied accessing directory '{p}': {exc}"
        except OSError as exc:
            return f"Error accessing directory '{p}': {exc}"

        # If none of the above matches
        return f"Directory at '{p}' does not look like an OCFL root or object"
    return f"Unknown path type for '{p}'"

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os

    if not os.path.exists(path):
        return f"error: path does not exist: {path}"

    if os.path.isfile(path):
        return 'file'

    if not os.path.isdir(path):
        return f"error: path is neither file nor directory: {path}"

    try:
        entries = os.listdir(path)
    except Exception as exc:
        return f"error: cannot list directory: {exc}"

    namaste_files = [e for e in entries if e.startswith('0=')]
    if not namaste_files:
        return "error: no '0=*' Namaste files found in directory"

    lower = [n.lower() for n in namaste_files]
    if '0=repo' in lower:
        return 'root'
    if '0=object' in lower:
        return 'object'

    # Default fallback: if any '0=*' file exists, assume an object directory
    return 'object'  # generic guess when specific marker absent

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root'   - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file'   - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os
    import re

    # Validate that the path can be accessed
    try:
        if not os.path.exists(path):
            return f"Path does not exist: {path}"
    except OSError as e:
        return f"Cannot access path: {e}"

    # If it is a file, return 'file'
    if os.path.isfile(path):
        return 'file'

    # It is a directory, examine its contents
    if os.path.isdir(path):
        try:
            entries = os.listdir(path)
        except PermissionError as e:
            return f"Permission denied while reading directory: {e}"
        except OSError as e:
            return f"Error reading directory: {e}"

        # A root has a HEAD file (and may also have a GENESIS or INDEX file)
        # but an object will not have a HEAD file
        if 'HEAD' in entries:
            # Check at least one Namaste directory exists to confirm an OCFL root
            for e in entries:
                if e.startswith('0=') and os.path.isdir(os.path.join(path, e)):
                    return 'root'
            # HEAD is present but nothing looks like a Namaste dir – still root
            return 'root'

        # Detect an object by presence of a directory that starts with '0='
        for e in entries:
            if e.startswith('0=') and os.path.isdir(os.path.join(path, e)):
                return 'object'

        return f"Unrecognised directory structure: {path}"

    # If we get here, the path is neither a normal file or directory
    return f"Unknown path type: {path}"

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os

    try:
        abs_path = os.path.abspath(path)
    except Exception as e:
        return f"Error determining absolute path: {e}"

    if not os.path.exists(abs_path):
        return f"Path does not exist: {abs_path}"

    if os.path.isfile(abs_path):
        return 'file'

    if not os.path.isdir(abs_path):
        return f"Unknown type for path: {abs_path}"

    # List the contents of the directory
    try:
        entries = os.listdir(abs_path)
    except Exception as e:
        return f"Could not list directory: {e}"

    # Helper to check for a "0=*" file in a given directory
    def has_namaste_file(dir_path):
        try:
            for name in os.listdir(dir_path):
                if os.path.isfile(os.path.join(dir_path, name)) and name.startswith('0='):
                    return True
        except Exception:
            pass
        return False

    # Check if the current directory itself looks like an object
    if has_namaste_file(abs_path):
        return 'object'

    # Check if any immediate subdirectory looks like an object,
    # which would indicate we are at the storage root
    for entry in entries:
        sub_dir = os.path.join(abs_path, entry)
        if os.path.isdir(sub_dir) and has_namaste_file(sub_dir):
            return 'root'

    return 'Unknown directory type'

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    if not isinstance(params, dict):
        raise TypeError("params must be a dictionary")
    if bug_ids is None:
        return params
    if isinstance(bug_ids, (list, tuple)):
        bug_id_str = ','.join(str(b) for b in bug_ids)
    elif isinstance(bug_ids, str):
        bug_id_str = bug_ids
    else:
        raise TypeError("bug_ids must be a list, tuple or string")
    params['ids'] = bug_id_str
    return params

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""

    # Validate params
    if not isinstance(params, dict):
        raise TypeError("params must be a dictionary")

    # Normalize bug_ids to a list of cleaned strings
    if isinstance(bug_ids, str):
        # split a comma separated string
        bug_ids = bug_ids.split(',')
    if isinstance(bug_ids, (int, str)):
        bug_ids = [bug_ids]
    try:
        iter(bug_ids)
    except TypeError:
        raise TypeError("bug_ids must be an iterable of IDs")

    ids_list = []
    for bid in bug_ids:
        if isinstance(bid, int):
            ids_list.append(str(bid))
        elif isinstance(bid, str):
            cleaned = bid.strip()
            if cleaned:
                ids_list.append(cleaned)
        else:
            raise TypeError("Each bug ID must be a string or integer")

    if not ids_list:
        raise ValueError("bug_ids contains no valid IDs")

    # Determine the key to use for Bugzilla IDs (common keys)
    id_key = None
    for key in ("ids", "ids[]", "id"):
        if key in params:
            id_key = key
            break

    # Merge into params
    if id_key:
        existing = params[id_key]
        if isinstance(existing, list):
            combined = existing + ids_list
        else:
            combined = [existing] + ids_list
        # Remove duplicates while preserving order
        seen = set()
        deduped = []
        for item in combined:
            if item not in seen:
                seen.add(item)
                deduped.append(item)
        params[id_key] = deduped
    else:
        # Default key
        params["ids"] = ids_list
    # No explicit return; params is modified in place

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    # Validate the base parameters dictionary
    if not isinstance(params, dict):
        raise TypeError(f"params must be a dict, got {type(params).__name__}")

    # Guard against no bug IDs to add
    if bug_ids is None:
        return

    # Convert bug_ids to a list of cleaned string IDs
    if isinstance(bug_ids, str):
        # Split by comma and strip whitespace
        ids_list = [s.strip() for s in bug_ids.split(',') if s.strip()]
    else:
        try:
            iter(bug_ids)
        except TypeError:
            # Not iterable – treat as a single value
            ids_list = [str(bug_ids).strip()]
        else:
            ids_list = [str(b).strip() for b in bug_ids if str(b).strip()]

    if not ids_list:
        return

    # Merge with any existing ids in the params
    if 'ids' in params:
        # Existing ids may be a string or a list
        existing = []
        existing_value = params['ids']
        if isinstance(existing_value, list):
            existing = [str(i).strip() for i in existing_value]
        else:
            # Assume a comma‑separated string
            existing = [s.strip() for s in str(existing_value).split(',') if s.strip()]

        # Combine and de‑duplicate while preserving order
        combined = list(dict.fromkeys(existing + ids_list))
        params['ids'] = ','.join(combined)
    else:
        params['ids'] = ','.join(ids_list)

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    if not isinstance(params, dict):
        raise TypeError("params must be a dict")
    if bug_ids is None:
        raise ValueError("bug_ids cannot be None")
    try:
        iter(bug_ids)
    except TypeError:
        raise TypeError("bug_ids must be an iterable")
    ids = []
    for bid in bug_ids:
        if isinstance(bid, (int, float)):
            ids.append(str(int(bid)))
        elif isinstance(bid, str):
            ids.append(bid.strip())
        else:
            raise TypeError(f"bug_id {bid!r} must be int or str")
    if not ids:
        return params
    if "ids" in params:
        existing = params["ids"]
        if isinstance(existing, str):
            existing_ids = [i.strip() for i in existing.split(",") if i.strip()]
        else:
            existing_ids = list(map(str, existing))
        combined = existing_ids + [i for i in ids if i not in existing_ids]
        params["ids"] = ",".join(combined)
    else:
        params["ids"] = ",".join(ids)
    return params

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    from ruamel.yaml.nodes import MappingNode, ScalarNode  # local import to avoid external dependency

    def _merge_values(v1, v2):
        # If both are MappingNode, merge recursively
        if isinstance(v1, MappingNode) and isinstance(v2, MappingNode):
            # Build a dict of old entries for quick lookup
            old_entries = {k.value: (k, val) for k, val in v1.value}
            new_entries = []
            # Preserve order from the first MappingNode
            for k_old, val_old in v1.value:
                key = k_old.value
                if key in old_entries:
                    # merge the values
                    merged_val = _merge_values(val_old, old_entries[key][1])
                else:
                    merged_val = val_old
                new_entries.append((k_old, merged_val))
            # Add new keys from v2 that weren't in v1
            for k_new, val_new in v2.value:
                if k_new.value not in old_entries:
                    new_entries.append((k_new, val_new))
            return MappingNode(tag=v1.tag, value=new_entries)
        else:
            # Last one wins
            return v2

    result_dict = {}
    key_order = []

    for key_node, value_node in nodes:
        # Ensure key_node is ScalarNode
        if not isinstance(key_node, ScalarNode):
            continue  # skip invalid entries
        key_str = key_node.value
        if key_str not in result_dict:
            result_dict[key_str] = value_node
            key_order.append(key_str)
        else:
            # Merge with existing
            result_dict[key_str] = _merge_values(result_dict[key_str], value_node)

    # Build result list preserving original order of first appearance
    merged = [(key_node, result_dict[key_str]) for key_str, key_node in zip(key_order, (kn for kn, _ in nodes if kn.value in key_order))]
    # The above might duplicate keys; to ensure correct key nodes, rebuild with stored key_node
    merged = [(key_node, result_dict[key_node.value]) for key_node in (kn for kn, _ in nodes if kn.value in key_order)]
    # Remove duplicates preserving order
    seen = set()
    final_result = []
    for k, v in merged:
        if k.value not in seen:
            seen.add(k.value)
            final_result.append((k, v))
    return final_result

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    if not isinstance(nodes, list):
        raise TypeError('nodes must be a list of (key_node, value_node) tuples')

    # Helper to merge two MappingNode instances
    def _merge_mappings(a, b):
        # Build a key -> value mapping for 'a'
        merged_items = {}
        for k_node, v_node in a.value:
            merged_items[k_node.value] = v_node
        # Merge entries from 'b'
        for k_node, v_node in b.value:
            if k_node.value in merged_items:
                existing = merged_items[k_node.value]
                if hasattr(existing, 'value') and hasattr(v_node, 'value'):  # both MappingNodes
                    merged_items[k_node.value] = _merge_mappings(existing, v_node)
                else:
                    merged_items[k_node.value] = v_node
            else:
                merged_items[k_node.value] = v_node
        # Reconstruct the list preserving key node order from 'a', then new keys from 'b'
        new_list = []
        seen = set()
        for k_node, _ in a.value:
            new_list.append((k_node, merged_items[k_node.value]))
            seen.add(k_node.value)
        for k_node, _ in b.value:
            if k_node.value not in seen:
                new_list.append((k_node, merged_items[k_node.value]))
                seen.add(k_node.value)
        return ruamel.yaml.nodes.MappingNode(tag=a.tag, value=new_list)

    key_map = {}          # key string -> value node
    order = []            # preserve first appearance order of keys

    for key_node, value_node in nodes:
        if not hasattr(key_node, 'value'):
            raise TypeError('Expected key node with .value attribute')
        key_str = key_node.value
        if key_str in key_map:
            existing_val = key_map[key_str]
            if hasattr(existing_val, 'value') and hasattr(value_node, 'value'):  # both MappingNodes
                key_map[key_str] = _merge_mappings(existing_val, value_node)
            else:
                key_map[key_str] = value_node
        else:
            key_map[key_str] = value_node
            order.append(key_str)

    # Build result list preserving original key node objects
    result = []
    for key_node in (k for k, _ in nodes if k.value in order):
        if key_node.value in order:
            result.append((key_node, key_map[key_node.value]))
            order.remove(key_node.value)  # ensure each key appears only once

    return result

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    # Helper to recursively merge two MappingNode instances
    def _merge_mapping_nodes(a, b):
        merged_pairs = list(a.value)
        for key_b, val_b in b.value:
            key_b_str = key_b.value
            for idx, (key_a, val_a) in enumerate(merged_pairs):
                if key_a.value == key_b_str:
                    if isinstance(val_a, MappingNode) and isinstance(val_b, MappingNode):
                        merged_pairs[idx] = (key_a, _merge_mapping_nodes(val_a, val_b))
                    else:
                        merged_pairs[idx] = (key_a, val_b)
                    break
            else:
                merged_pairs.append((key_b, val_b))
        return MappingNode(a.tag, merged_pairs)

    result = {}
    order = []

    for key_node, val_node in nodes:
        key_str = key_node.value
        if key_str not in result:
            # first occurrence
            result[key_str] = (key_node, val_node)
            order.append(key_str)
        else:
            existing_key_node, existing_val = result[key_str]
            if isinstance(existing_val, MappingNode) and isinstance(val_node, MappingNode):
                merged_val = _merge_mapping_nodes(existing_val, val_node)
                result[key_str] = (existing_key_node, merged_val)
            else:
                # non-mapping: last wins
                result[key_str] = (existing_key_node, val_node)

    return [(result[k][0], result[k][1]) for k in order]

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    if parser is None:
        raise ValueError("parser argument cannot be None")

    flags = []

    try:
        actions = getattr(parser, "_actions", [])
