import argparse

def parse_arguments(*unparsed_arguments):
    """
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    """
    parser = argparse.ArgumentParser()
    # Example global option(s) – can be extended as needed
    parser.add_argument('--verbose', action='store_true', help='Enable verbose output')
    # Create subparsers container (empty; subparsers can be added by the caller if needed)
    subparsers = parser.add_subparsers(dest='subparser')
    # Note: If specific subparsers are added elsewhere, their arguments will be captured in the
    # resulting Namespace under 'subparser' key.
    try:
        namespace, unknown = parser.parse_known_args(unparsed_arguments)
    except SystemExit:  # argparse throws SystemExit on parse errors (e.g., --help)
        # If parsing fails, return an empty mapping; the caller can decide how to handle it.
        return {}
    result = {'global': namespace}
    # If a subparser was provided, create a separate namespace for it
    if getattr(namespace, 'subparser', None):
        result[namespace.subparser] = namespace
    return result

def parse_subparser_arguments(unparsed_arguments, subparsers):
    """
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    """
    if not isinstance(subparsers, dict):
        raise TypeError("subparsers must be a dictionary mapping name to ArgumentParser")

    # Ensure we work on a list copy so we can iterate safely
    args = list(unparsed_arguments) if unparsed_arguments is not None else []

    parsed_results = {}
    unknown_by_parser = {}

    for name, parser in subparsers.items():
        try:
            ns, unknown = parser.parse_known_args(args)
            parsed_results[name] = ns
            unknown_by_parser[name] = unknown
        except SystemExit:
            # The parser printed a usage message and exited; skip this parser
            # but we keep unknown_by_parser empty for consistency
            unknown_by_parser[name] = []

    # Determine arguments not claimed by any subparser
    if unknown_by_parser:
        shared_unknown = set(unknown_by_parser[next(iter(unknown_by_parser))])
        for unknowns in unknown_by_parser.values():
            shared_unknown.intersection_update(unknowns)

        remaining = [arg for arg in args if arg in shared_unknown]
    else:
        remaining = args

    return parsed_results, remaining

def deep_merge_nodes(nodes):
    '''
    Deep merges a list of (ScalarNode, value_node) tuples, merging mappings for duplicate keys.
    '''
    # Helper to merge two values (nodes)
    def merge_values(val1, val2):
        # If both are mapping nodes, deep merge them
        if isinstance(val1, ruamel.yaml.nodes.MappingNode) and isinstance(val2, ruamel.yaml.nodes.MappingNode):
            # Build a dict from existing mapping
            existing_map = {k.value: (k, v) for k, v in val1.value}
            # Merge new mapping into existing dict
            for k2, v2 in val2.value:
                key_name = k2.value
                if key_name in existing_map:
                    # Recursively merge the values
                    _, existing_val = existing_map[key_name]
                    merged_val = merge_values(existing_val, v2)
                    existing_map[key_name] = (k2, merged_val)
                else:
                    existing_map[key_name] = (k2, v2)
            # Preserve order: start with keys from val1, then new ones
            merged_list = []
            seen_keys = set()
            for k, v in val1.value:
                key_name = k.value
                if key_name in seen_keys:
                    # should not happen but skip duplicates
                    continue
                seen_keys.add(key_name)
                merged_list.append((k, existing_map[key_name][1]))
            for k, v in val2.value:
                key_name = k.value
                if key_name not in seen_keys:
                    merged_list.append((k, v))
            return ruamel.yaml.nodes.MappingNode(tag=val1.tag, value=merged_list)
        # If not both mapping nodes, last value wins
        return val2

    # Use a dict to keep track of merged values, keyed by the key's scalar value
    merged = {}
    order = []

    for key_node, value_node in nodes:
        # Ensure key_node is a ScalarNode; use its value for dict key
        key = key_node.value if hasattr(key_node, 'value') else key_node
        if key not in merged:
            merged[key] = value_node
            order.append(key)
        else:
            merged[key] = merge_values(merged[key], value_node)

    # Reconstruct the list preserving original order
    result = [(key_node, merged[key]) for key_node, _ in nodes if (key_node.value if hasattr(key_node, 'value') else key_node) in merged and key_node.value if hasattr(key_node, 'value') else key_node in order]
    return result

