            seen = {}
            # add entries from first mapping
            for k_node, val in v1.value:
                k = k_node.value
                seen[k] = (k_node, val)
                merged_pairs.append((k_node, val))
            # merge entries from second mapping
            for k_node2, val2 in v2.value:
