                    seen[k] = (k_node2, merged_val)
                    # replace in merged_pairs
                    for idx, (k_obj, _) in enumerate(merged_pairs):
                        if k_obj.value == k:
                            merged_pairs[idx] = (k_node2, merged_val)
                            break
                else:
                    merged_pairs.append((k_node2, val2))
                    seen[k] = (k_node2, val2)
            return type(v1)(tag=v1.tag, value=merged_pairs)
        else:
            # non-mapping types: last one wins
            return v2

    merged_dict = {}
    order = []
    for key_node, val in nodes:
        key = key_node.value
        if key not in merged_dict:
            merged_dict[key] = (key_node, val)
            order.append(key)
        else:
            existing_key_node, existing_val = merged_dict[key]
            merged_val = merge_values(existing_val, val)
            merged_dict[key] = (existing_key_node, merged_val)

