def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.
    '''
    # Helper to merge two MappingNode values
    def _merge_mapping_nodes(m1, m2):
        """Recursively merge two ruamel.yaml MappingNode objects."""
        if not isinstance(m1, MappingNode) or not isinstance(m2, MappingNode):
            # non-mapping values: last wins
            return m2
        # Build lookup for first mapping (preserve order)
        list1 = m1.value  # list of (key, val) pairs
        mapping = {kv[0].value: (kv[0], kv[1]) for kv in list1}
        # Merge second mapping
        for keynode, valnode in m2.value:
            key = keynode.value
            if key in mapping:
                old_keynode, old_valnode = mapping[key]
                # deep merge if both are MappingNode
                if isinstance(old_valnode, MappingNode) and isinstance(valnode, MappingNode):
                    merged_val = _merge_mapping_nodes(old_valnode, valnode)
                    mapping[key] = (old_keynode, merged_val)
                else:
                    mapping[key] = (old_keynode, valnode)
            else:
                mapping[key] = (keynode, valnode)
        # Preserve original order from first mapping, then append new keys
        new_list = []
        seen_keys = set()
        for keynode, _ in list1:
            k = keynode.value
            new_list.append(mapping[k])
            seen_keys.add(k)
        for key, (knode, vnode) in mapping.items():
            if key not in seen_keys:
                new_list.append((knode, vnode))
                seen_keys.add(key)
        return MappingNode(m1.tag, new_list)

    if not isinstance(nodes, list):
        raise TypeError('nodes must be a list')
    merged = {}
    order = []
    for keynode, valnode in nodes:
        if not hasattr(keynode, 'value'):
            raise TypeError('keynode must have a value attribute')
        key = keynode.value
        if key not in order:
            order.append(key)
        if key in merged:
            old_key, old_val = merged[key]
            if isinstance(old_val, MappingNode) and isinstance(valnode, MappingNode):
                merged_val = _merge_mapping_nodes(old_val, valnode)
                merged[key] = (old_key, merged_val)
            else:
                # last wins for non-mapping values
                merged[key] = (old_key, valnode)
        else:
            merged[key] = (keynode, valnode)
    return [(merged[k][0], merged[k][1]) for k in order]

