    """Replace any custom string URL items with values in args"""
    if not isinstance(url, str):
        raise TypeError("url must be a string")
    if not url_args:
        return url

    # Handle mapping arguments first
    if isinstance(url_args, dict):
        for key, value in url_args.items():
            placeholder = '{' + str(key) + '}'
            if placeholder in url:
                url = url.replace(placeholder, '' if value is None else str(value))
        return url

    # Handle list/tuple arguments for positional placeholders
    if isinstance(url_args, (list, tuple)):
        for idx, value in enumerate(url_args):
            placeholder = '{' + str(idx) + '}'
            if placeholder in url:
                url = url.replace(placeholder, '' if value is None else str(value))
        return url

    # Fallback: attempt to use built‑in format syntax if possible
    try:
        return url.format(**url_args)
    except Exception:
        # If formatting fails, return the original URL unchanged
        return url

