def get_repo_archive(url: str, destination_path: Path) -> Path:
    """Given an url and a destination path, retrieve and extract .tar.gz archive
    which contains 'desc' file for each package.
    Each .tar.gz archive corresponds to an Arch Linux repo ('core', 'extra', 'community').

    Args:
        url: url of the .tar.gz archive to download
        destination_path: the path on disk where to extract archive

    Returns:
        a directory Path where the archive has been extracted to.
    """
    try:
        response = requests.get(url, stream=True, timeout=30)
        response.raise_for_status()
    except Exception as exc:
        raise RuntimeError(f"Could not download archive from {url}") from exc

    # Ensure destination directory exists
    try:
        destination_path.mkdir(parents=True, exist_ok=True)
    except Exception as exc:
        raise RuntimeError(f"Could not create destination directory {destination_path}") from exc

    temp_file = destination_path / "repo.tar.gz"

    # Write the downloaded content to a temporary file
    try:
        with temp_file.open("wb") as fh:
            for chunk in response.iter_content(chunk_size=8192):
                if chunk:
                    fh.write(chunk)
    except Exception as exc:
        # Clean up partially written file if something goes wrong
        try:
            temp_file.unlink(missing_ok=True)
        except Exception:
            pass
        raise RuntimeError(f"Failed to write archive to {temp_file}") from exc

    # Extract the .tar.gz archive
    try:
        import tarfile
        with tarfile.open(temp_file, "r:gz") as tar:
            tar.extractall(path=destination_path)
    except Exception as exc:
        raise RuntimeError(f"Failed to extract archive {temp_file}") from exc
    finally:
        # Always try to delete the temporary archive
        try:
            temp_file.unlink(missing_ok=True)
        except Exception:
            pass

    return destination_path

