def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    Uses regular expressions for a fast and lightweight implementation.
    """
    # Map user input to internal mode
    if platform in ('this', None):
        mode = 1 if os.name != 'nt' else 0
    elif platform in (1, '1'):
        mode = 1
    elif platform in (0, '0'):
        mode = 0
    else:
        raise ValueError("Unsupported platform value: %r" % (platform,))

    if mode == 1:  # POSIX-like
        # Fast POSIX splitter based on shlex but re‑used for speed
        token_re = re.compile(
            r'''
            (?:
              "(?P<dq>[^\"]*)"   |   # double-quoted
              '(?P<sq>[^\']*)'   |   # single-quoted
              (?P<word>[^\s"']+)      # unquoted
            )
            ''',
            re.VERBOSE,
        )
        out = []
        pos = 0
        while pos < len(s):
            m = token_re.search(s, pos)
            if not m:
                break
            if m.group('dq') is not None:
                out.append(m.group('dq').replace('\\"', '"').replace('\\\\', '\\'))
            elif m.group('sq') is not None:
                out.append(m.group('sq').replace("\\'", "'").replace('\\\\', '\\'))
            else:
                out.append(m.group('word').replace('\\ ', ' '))
            pos = m.end()
        return out

    else:  # Windows/CMD-like
        items = []
        i = 0
        n = len(s)
        while i < n:
            while i < n and s[i].isspace():
                i += 1
            if i >= n:
                break
            if s[i] in ('"', "'"):
                quote = s[i]
                i += 1
                buf = ''
                while i < n:
                    if s[i] == quote:
                        i += 1
                        break
                    if s[i] == '\\':
                        i += 1
                        if i < n:
                            buf += s[i]
                            i += 1
                    else:
                        buf += s[i]
                        i += 1
                items.append(buf)
            else:
                buf = ''
                while i < n and not s[i].isspace():
                    if s[i] == '\\':
                        i += 1
                        if i < n:
                            buf += s[i]
                            i += 1
                    else:
                        buf += s[i]
                        i += 1
                items.append(buf)
        return items

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import sys
    # Determine actual platform if 'this'
    if platform == 'this':
        if sys.platform.startswith('win'):
            platform = 0
        else:
            platform = 1

    # POSIX: use shlex for reliable behaviour
    if platform == 1:
        import shlex
        try:
            return shlex.split(s)
        except Exception:
            # Fallback to regex split on simple spaces if shlex fails
            return [token for token in s.split() if token]

    # Windows/CMD: custom regex splitting
    # Matches either a double-quoted string (allowing escaped quotes) or a non-space token
    pattern = r'(?:"((?:\\.|[^"])*)"|(\S+))'
    tokens = []
    for m in re.finditer(pattern, s):
        quoted = m.group(1)
        if quoted is not None:
            # Handle escaped characters inside the quoted string
            token = quoted.replace(r'\"', '"').replace(r'\\', '\\')
            tokens.append(token)
        else:
            tokens.append(m.group(2))
    return tokens

