        elif archive_lower.endswith('.zip'):
            _run(['unzip', '-q', '-o', archive_path, '-d', str(dest_dir)])
        elif archive_lower.endswith('.gz'):
            # Handle single gzipped file
            _run(['gunzip', '-c', archive_path])
