    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    import os
    import subprocess
    from pathlib import Path

    # Sanity checks
    archive = Path(archive_path)
    if not archive.is_file():
        raise FileNotFoundError(f"Archive file not found: {archive_path}")

    tmp_dir = Path(tmp_path)
    try:
        tmp_dir.mkdir(parents=True, exist_ok=True)
    except Exception as e:
        raise RuntimeError(f"Could not create temporary directory '{tmp_dir}': {e}")

    # Determine extraction folder name
    if filename is None:
        # Use the archive stem (e.g., 'myrepo' for 'myrepo.tar.gz')
        filename = archive.stem
    out_dir = tmp_dir / filename
    if not out_dir.exists():
        try:
            out_dir.mkdir(parents=True, exist_ok=True)
        except Exception as e:
            raise RuntimeError(f"Could not create extraction directory '{out_dir}': {e}")

    # Uncompress using tar (supports .tar, .tar.gz, .tgz, .tar.bz2, .tar.xz, .zip)
    try:
        # Try to use tar first; if fails, fall back to zip
        subprocess.run(
            ["tar", "-xf", str(archive), "-C", str(out_dir)],
            check=True,
            stderr=subprocess.PIPE,
            stdout=subprocess.PIPE,
        )
    except subprocess.CalledProcessError:
        # Fallback for zip archives
        try:
            subprocess.run(
                ["unzip", "-q", str(archive), "-d", str(out_dir)],
                check=True,
                stderr=subprocess.PIPE,
                stdout=subprocess.PIPE,
            )
        except subprocess.CalledProcessError as e:
            raise RuntimeError(f"Failed to extract archive '{archive_path}': {e.stderr.decode().strip()}")

    # Return a file URI that can be used as a repo origin
    return out_dir.resolve().as_uri()

