    else:
        raise ValueError(f"Unsupported time unit in frequency: '{unit}'")
    return datetime.timedelta(**kwargs)

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None:
        return None
    freq_str = str(frequency).strip().lower()
    if not freq_str or freq_str == "always":
        return None

    parts = freq_str.split()
    if len(parts) != 2:
        raise ValueError(f"Invalid frequency format: {frequency!r}")

    number_str, unit = parts
    try:
        number = int(number_str)
    except ValueError:
        raise ValueError(f"Invalid number in frequency: {number_str!r}")

    unit_map = {
        'day': 'days', 'days': 'days',
        'week': 'weeks', 'weeks': 'weeks',
        'hour': 'hours', 'hours': 'hours',
        'minute': 'minutes', 'minutes': 'minutes',
        'second': 'seconds', 'seconds': 'seconds',
        'millisecond': 'milliseconds', 'milliseconds': 'milliseconds',
        'microsecond': 'microseconds', 'microseconds': 'microseconds',
    }

    if unit not in unit_map:
        raise ValueError(f"Unsupported time unit in frequency: {unit!r}")

    kwargs = {unit_map[unit]: number}
    return datetime.timedelta(**kwargs)

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not isinstance(host, str):
        raise TypeError("host must be a string")
    host = host.strip()
    if host == '':
        raise ValueError("host cannot be empty")
    loopback_addresses = {'127.0.0.1', '::1'}
    # Direct string matches for localhost
    if host.lower() == 'localhost':
        return True
    try:
        # IPv4 resolution
        ip = socket.gethostbyname(host)
        if ip in loopback_addresses:
            return True
    except socket.gaierror:
        # Might be an IPv6 address or name that resolves only to IPv6
        try:
            infos = socket.getaddrinfo(host, None, socket.AF_INET6)
            for info in infos:
                if info[4][0] == '::1':
                    return True
        except socket.gaierror:
            pass
    return False

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not host:
        return False
    # Direct matches for common localhost names and addresses
    localnames = {'localhost', '127.0.0.1', '::1'}
    if host in localnames:
        return True
    # Handle IPv4 addresses beginning with 127.
    if host.count('.') == 3:
        try:
            parts = [int(p) for p in host.split('.')]
            if len(parts) == 4 and parts[0] == 127 and all(0 <= p <= 255 for p in parts):
                return True
        except Exception:
            pass
    # Try to resolve
    try:
        # socket.getaddrinfo returns a list of tuples; the address is at index 4[0]
        for result in socket.getaddrinfo(host, None):
            addr = result[4][0]
            if addr == '127.0.0.1' or addr == '::1':
                return True
    except (socket.gaierror, OverflowError, ValueError):
        # hostname could not be resolved or address invalid
        pass
    return False

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not host:
        return False

    host_lc = host.lower()
    if host_lc == 'localhost':
        return True

    try:
        # Resolve the host to all addresses (IPv4 and IPv6)
        for res in socket.getaddrinfo(host, None):
            family, _, _, _, sockaddr = res
            if family == socket.AF_INET:
                ip = sockaddr[0]
                if ip.startswith('127.'):
                    return True
            elif family == socket.AF_INET6:
                ip = sockaddr[0]
                # Remove optional zone identifier
                ip = ip.split('%')[0]
                if ip == '::1':
                    return True
    except socket.gaierror:
        # Host could not be resolved
        return False

    return False

def is_local(host):
    """Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost, False otherwise
    """
    # Accept common localhost notations directly
    if host in ('localhost', '127.0.0.1', '::1'):
        return True

    try:
        # Resolve the host to all IPs it could be associated with
        addrinfo = socket.getaddrinfo(host, None)
    except socket.gaierror:
        return False

    for entry in addrinfo:
        # Each entry's 4th element is a tuple; first element is the IP address string
        ip_addr = entry[4][0]
        # Check for IPv4 loopback
        if ip_addr == '127.0.0.1':
            return True
        # Check for IPv6 loopback
        if ip_addr == '::1':
            return True
        # Some systems may return loopback addresses in other forms; handle them
        try:
            # Try interpreting the IP as an IPv4 address and check if it falls into 127.0.0.0/8
            import ipaddress
            if ipaddress.ip_address(ip_addr).is_loopback:
                return True
        except Exception:
            pass

    return False

def is_gitbash():
    """
    returns True if you run in a Windows gitbash
    :return: True if gitbash
    """
    try:
        # Windows gitbash usually sets OSTYPE to something containing 'msys' or 'cygwin'
        ostype = os.environ.get('OSTYPE', '').lower()
        if 'msys' in ostype or 'cygwin' in ostype:
            return True
        # In some cases, the SHELL variable will point to 'bash'
        if os.path.basename(os.environ.get('SHELL', '')).lower() == 'bash':
            # Additional check: use the cygwin path pattern 'C:\\...' which appears in HOME
            home = os.environ.get('HOME', '')
            if home and ('/' in home or '\\' in home):
                return True
        return False
    except Exception:
        return False

def write_configuration(config_filename, rendered_config, mode=0o600, overwrite=False):
    """
    Given a target config filename and rendered config YAML, write it out to file. Create any
    containing directories as needed. But if the file already exists and overwrite is False,
    abort before writing anything.
    """
    # Basic validation of arguments
    if not isinstance(config_filename, str):
        raise TypeError("config_filename must be a string path")
    if not isinstance(rendered_config, str):
        raise TypeError("rendered_config must be a string containing YAML")
    if not isinstance(mode, int):
        raise TypeError("mode must be an integer file permission")
    if not isinstance(overwrite, bool):
        raise TypeError("overwrite must be a boolean")

    # Normalize path
    config_path = os.path.expanduser(config_filename)
    config_dir = os.path.dirname(config_path)

    # Create containing directories if they do not exist
    if config_dir and not os.path.isdir(config_dir):
        try:
            os.makedirs(config_dir, exist_ok=True)
        except OSError as exc:
            raise OSError(f"Failed to create directories for '{config_dir}': {exc}") from exc

    # If file exists and we are not allowed to overwrite, abort
    if os.path.exists(config_path) and not overwrite:
        raise FileExistsError(f"The file '{config_path}' already exists and overwrite is set to False")

    # Write the configuration to the file
    try:
        with open(config_path, "w", encoding="utf-8") as f:
            f.write(rendered_config)
    except OSError as exc:
        raise OSError(f"Failed to write to '{config_path}': {exc}") from exc

    # Set the file permissions (mode) after writing
    try:
        os.chmod(config_path, mode)
    except OSError as exc:
        raise OSError(f"Failed to set mode on '{config_path}': {exc}") from exc

    return None

