    if os.path.exists(config_filename) and not overwrite:
        raise FileExistsError(f"File '{config_filename}' already exists and overwrite is False")

    # Write to file
    try:
        with open(config_filename, 'wb') as f:
            f.write(content)
        # Set file permissions
        try:
            os.chmod(config_filename, mode)
        except Exception as exc:
            # Not critical enough to stop; log warning instead
            raise OSError(f"Failed to set mode {oct(mode)} on '{config_filename}': {exc}") from exc
    except Exception as exc:
        raise OSError(f"Error writing configuration to '{config_filename}': {exc}") from exc

def oneline(script, seperator=" && "):
    """
    converts a script to one line command.
    THis is useful to run a single ssh command and pass a one line script.

    :param script:
    :return:
    """
    if script is None:
        return ""

    if isinstance(script, str):
        # Remove any common leading whitespace
        script = textwrap.dedent(script)
        lines = script.splitlines()
    elif isinstance(script, (list, tuple)):
        lines = [str(item) for item in script]
    else:
        raise ValueError("script must be a string, list, or tuple")

    # Strip each line and ignore blank lines
    cleaned = [line.strip() for line in lines if line.strip()]

    if not cleaned:
        return ""

    return seperator.join(cleaned)

def _resolve_string(matcher):
    '''
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    '''
    # Determine name and default from the matcher
    if isinstance(matcher, str):
        parts = matcher.split('=', 1)
        name = parts[0]
        default = parts[1] if len(parts) > 1 else None
    elif isinstance(matcher, (tuple, list)):
        if not matcher:
            raise ValueError("Matcher cannot be empty")
        name = matcher[0]
        default = matcher[1] if len(matcher) > 1 else None
    else:
        raise TypeError("Matcher must be a string or a tuple/list")

    if not isinstance(name, str):
        raise TypeError("Environment variable name must be a string")

    # Retrieve the environment variable
    value = os.getenv(name)
    if value is None:
        if default is not None:
            return default
        else:
            raise KeyError(f"Environment variable '{name}' is not set and no default was provided")
    return value

def _resolve_string(matcher):
    '''
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    '''
    if matcher is None or not isinstance(matcher, str):
        raise TypeError("Matcher must be a non‑empty string")
    matcher = matcher.strip()
    if ':' in matcher:
        name, default = matcher.split(':', 1)
        name = name.strip()
        default = default.strip()
    else:
        name = matcher
        default = None

    try:
        return os.environ[name]
    except KeyError:
        if default is not None:
            return default
        raise RuntimeError(f"Environment variable '{name}' is not set and no default value provided")

