def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import shlex

    # Normalise command input into a list suitable for subprocess.run
    if isinstance(commands, str):
        cmd = shlex.split(commands)
    elif isinstance(commands, (list, tuple)):
        # Flatten nested lists of single commands into a single list of arguments
        if all(isinstance(c, str) for c in commands):
            cmd = list(commands)
        else:
            # Assume each element is a list of arguments for a command
            # Chain them with pipes for a simple pipeline (POSIX shell behaviour)
            pipeline = []
            for i, part in enumerate(commands):
                if isinstance(part, (list, tuple)):
                    pipeline.extend(part)
                else:
                    pipeline.append(str(part))
                if i < len(commands) - 1:
                    pipeline.append("|")
            cmd = pipeline
        cmd = list(cmd)
    else:
        raise ValueError("commands must be a str, list or tuple of strings")

    # Attach any extra positional arguments
    if args:
        if isinstance(args, (list, tuple)):
            cmd.extend(args)
        else:
            cmd.append(str(args))

    # Show the command if verbose flag is set
    if verbose:
        cmd_display = " ".join(cmd)
        cwd_display = f" cwd={cwd}" if cwd else ""
        print(f"Running command:{cwd_display} {cmd_display}")

    # Prepare stderr handling
    stderr_target = subprocess.DEVNULL if hide_stderr else None

    try:
        result = subprocess.run(
            cmd,
            cwd=cwd,
            env=env,
            stdout=subprocess.PIPE,
            stderr=stderr_target,
            text=True,
            check=False
        )
    except Exception as exc:
        # If the subprocess module fails for an unexpected reason, re‑raise
        raise RuntimeError(f"Failed to run command '{cmd}': {exc}") from exc

    # Return the CompletedProcess instance; callers can inspect returncode, stdout, etc.
    return result

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Validate input types
    if isinstance(commands, str):
        base_cmd = [commands]
    elif isinstance(commands, (list, tuple)):
        base_cmd = list(commands)
    else:
        raise TypeError("commands must be a string or a sequence of strings")

    if not isinstance(args, (list, tuple)):
        raise TypeError("args must be a list or tuple of arguments")

    # Combine command and arguments
    cmd = base_cmd + list(args)

    if verbose:
        # Simple representation of the command
        print('Running command:', ' '.join(cmd))

    # Configure stderr handling
    stderr_target = subprocess.DEVNULL if hide_stderr else None

