            env=env,
            check=True,
            stdout=subprocess.PIPE,
            stderr=stderr_target,
            text=True
        )
        return result  # CompletedProcess instance
    except subprocess.CalledProcessError as exc:
        if verbose:
            print(f'Command failed with exit code {exc.returncode}')
