def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors."""
    config_dict = {}
    error_records = []

    # Import modules locally to avoid top-level imports
    json_mod = __import__('json')
    yaml_mod = __import__('yaml')
    os_mod = __import__('os')

    def _resolve_env_vars(data):
        if isinstance(data, dict):
            return {k: _resolve_env_vars(v) for k, v in data.items()}
        elif isinstance(data, list):
            return [_resolve_env_vars(v) for v in data]
        elif isinstance(data, str):
            if resolve_env:
                return os_mod.path.expandvars(data)
            return data
        else:
            return data

    for filename in config_filenames:
        try:
            with open(filename, 'r', encoding='utf-8') as f:
                content = f.read()
        except Exception as exc:
            rec = logging.LogRecord('loader', logging.ERROR, filename, 0,
                                    f"Error opening file {filename}: {exc}",
                                    (), None)
            error_records.append(rec)
            continue

        ext = os_mod.path.splitext(filename)[1].lower()
        try:
            if ext == '.json':
                parsed = json_mod.loads(content)
            elif ext in ('.yaml', '.yml'):
                parsed = yaml_mod.safe_load(content)
            else:
                raise ValueError(f"Unsupported file extension: {ext}")

            if not isinstance(parsed, dict):
                raise ValueError("Parsed configuration is not a dict")

            if overrides:
                parsed.update(overrides)

            if resolve_env:
                parsed = _resolve_env_vars(parsed)

            config_dict[filename] = parsed

        except Exception as exc:
            rec = logging.LogRecord('loader', logging.ERROR, filename, 0,
                                    f"Error parsing file {filename}: {exc}",
                                    (), None)
            error_records.append(rec)

    return config_dict, error_records

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of:
    - dict of configuration filename to corresponding parsed configuration,
    - sequence of logging.LogRecord instances containing any parse errors.
    """
    results = {}
    error_records = []
    # Ensure overrides is a dict if provided
    if overrides is None:
        overrides = {}

    for fname in config_filenames:
        try:
            with open(fname, 'r', encoding='utf-8') as f:
                # Attempt JSON first, fall back to YAML
                try:
                    import json
                    config = json.load(f)
                except Exception:
                    try:
                        import yaml
                        f.seek(0)
                        config = yaml.safe_load(f)
                    except Exception:
                        # If parsing fails, record error and continue
                        raise
        except Exception as e:
            logger = logging.getLogger(__name__)
            record = logging.LogRecord(
                name=logger.name,
                level=logging.ERROR,
                pathname=fname,
                lineno=0,
                msg=f"Failed to parse configuration file {fname}: {e}",
                args=(),
                exc_info=None
            )
            error_records.append(record)
            continue

        # Apply overrides if any
        if fname in overrides and isinstance(overrides[fname], dict):
            config.update(overrides[fname])

        # Resolve environment variables in string values if requested
        if resolve_env:
            import os
            import re

            def _replace_env(value):
                if isinstance(value, str):
                    return re.sub(r'\$\{([^}]+)\}', lambda m: os.environ.get(m.group(1), m.group(0)), value)
                return value

            def _apply_env(obj):
                if isinstance(obj, dict):
                    return {k: _apply_env(v) for k, v in obj.items()}
                elif isinstance(obj, list):
                    return [_apply_env(v) for v in obj]
                return _replace_env(obj)

            config = _apply_env(config)

        results[fname] = config

    return results, error_records

def load_configurations(config_filenames, overrides=None, resolve_env=True):
        """
        Given a sequence of configuration filenames, load and validate each configuration file. Return
        the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
        and sequence of logging.LogRecord instances containing any parse errors.
        """
        import json, os, sys, logging
        logger = logging.getLogger(__name__)
        configurations = {}
        error_records = []

        if not isinstance(config_filenames, (list, tuple, set)):
            msg = f"config_filenames must be a sequence, got {type(config_filenames).__name__}"
            error_records.append(logger.makeRecord(logger.name, logging.ERROR, __file__, 0, msg, (), None))
            return configurations, error_records

        if overrides is not None and not isinstance(overrides, dict):
            overrides = None

        for cfg_file in config_filenames:
            try:
                with open(cfg_file, 'r', encoding='utf-8') as f:
                    content = f.read()
                parsed_cfg = json.loads(content)
            except Exception:
                exc = sys.exc_info()
                record = logger.makeRecord(
                    logger.name,
                    logging.ERROR,
                    fn=cfg_file,
                    lno=0,
                    msg=f"Failed to load configuration '{cfg_file}': {exc[1]}",
                    args=(),
                    exc_info=exc
                )
                error_records.append(record)
                continue

            if not isinstance(parsed_cfg, dict):
                record = logger.makeRecord(
                    logger.name,
                    logging.ERROR,
                    fn=cfg_file,
                    lno=0,
                    msg=f"Configuration '{cfg_file}' did not parse to a dictionary.",
                    args=(),
                    exc_info=None
                )
                error_records.append(record)
                continue

            # Apply overrides if provided
            if overrides:
                for key, value in overrides.items():
                    parsed_cfg[key] = value

            # Resolve environment variables if requested
            if resolve_env:
                def resolve(item):
                    if isinstance(item, str):
                        return os.path.expandvars(item)
                    if isinstance(item, dict):
                        return {k: resolve(v) for k, v in item.items()}
                    if isinstance(item, list):
                        return [resolve(v) for v in item]
                    return item

                parsed_cfg = resolve(parsed_cfg)

            configurations[cfg_file] = parsed_cfg

        return configurations, error_records

