def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # Guard against None
    if seq is None:
        seq = []
    # If seq is already a sequence type we keep it
    if isinstance(seq, (list, tuple, set, dict)):
        sequence = seq
    else:
        # Try to coerce to a list; if not iterable, wrap in a list
        try:
            sequence = list(seq)
        except Exception:
            sequence = [seq]
    # Optionally wrap the sequence with a deque if a buffer size is provided
    if bufsize is not None:
        try:
            from collections import deque
            sequence = deque(sequence, maxlen=bufsize)
        except Exception:
            # If deque creation fails, fall back to the original sequence
            pass
    return sequence, type(sequence).__name__

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # If seq is already a sequence type we can just return it
    if isinstance(seq, (list, tuple, set, str, bytes, bytearray)):
        return seq, type(seq)

    # Otherwise we try to consume the iterator/generator into a list.
    try:
        if bufsize is None:
            # Simple conversion
            seq_list = list(seq)
        else:
            # Consume in chunks of size bufsize to keep memory usage moderate.
            from itertools import islice
            it = iter(seq)
            seq_list = []
            while True:
                chunk = list(islice(it, bufsize))
                if not chunk:
                    break
                seq_list.extend(chunk)
    except Exception as exc:
        raise TypeError(f"Object of type {type(seq).__name__} is not iterable") from exc

    return seq_list, type(seq_list)

