        return None, type(None)

    # If seq is a recognised sequence type, return as is
    if isinstance(seq, (list, tuple, set)):
        return seq, type(seq)

    # Strings and bytes are also iterable but may be treated specially
    if isinstance(seq, (str, bytes)):
        return seq, type(seq)

    # Try to convert non-sequence iterables into a list
    try:
        it = iter(seq)
    except TypeError:
        # Not iterable; return as is
        return seq, type(seq)

    # If the iterable has a defined length and is not a tuple/list/set, we could
    # preserve its type, but for simplicity we convert it to a list
    if bufsize is None:
        result_seq = list(it)
    else:
        # Limited buffering
        result_seq = []
        for _ in range(bufsize):
            try:
                result_seq.append(next(it))
            except StopIteration:
                break

    return result_seq, type(seq)

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # If seq is a bytes-like object, keep it
    if isinstance(seq, (bytes, bytearray)):
        return seq, type(seq)

    # If seq is a string, keep it
    if isinstance(seq, str):
        return seq, str

    # Common sequence types: list, tuple, set, dict
    if isinstance(seq, (list, tuple, set, dict)):
        return seq, type(seq)

    # If seq looks like a file‑like object, read its contents
    if hasattr(seq, "read"):
        try:
            # Some file objects support a size argument; fall back to no argument
            if bufsize is not None:
                data = seq.read(bufsize)
            else:
                data = seq.read()
        except TypeError:
            data = seq.read()
        return data, type(data)

    # Unsupported type
    raise TypeError(f"Unsupported sequence type: {type(seq)}")

def _get_seq_with_type(seq, bufsize=None):
    """
    Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    from collections.abc import Sequence
    # Don't treat strings or bytes as sequences of elements
    if isinstance(seq, Sequence) and not isinstance(seq, (str, bytes, bytearray)):
        seq_to_use = seq
    else:
        # Try to convert an iterator or other iterable to a list
        try:
            seq_to_use = list(seq)
        except Exception:
            # If not iterable, treat as a single element sequence
            seq_to_use = [seq]
    return seq_to_use, type(seq_to_use)

def scale(self, other=None, recompute=False):
    """Compute or set scale (integral of the histogram).

    If *other* is ``None``, return scale of this histogram.
    If its scale was not computed before, it is computed and stored for subsequent use
    (unless explicitly asked to *recompute*).
    Note that after changing (filling) the histogram one must explicitly recompute the scale
    if it was computed before.

    If a float *other* is provided, rescale self to *other*.

    Histograms with scale equal to zero can't be rescaled.
    :exc:`.LenaValueError` is raised if one tries to do that.
    """
    # Ensure recompute is a boolean.
    if not isinstance(recompute, bool):
        raise TypeError("recompute must be a boolean")

    # Helper to compute current scale.
    def _compute_scale():
        try:
            data = getattr(self, "_values")
        except AttributeError:
            data = getattr(self, "values", None)
        if data is None:
            # If no explicit storage, try to use the instance itself
            if hasattr(self, "__iter__"):
                data = self
            else:
                raise ValueError("Cannot determine histogram data")
        try:
            return sum(data)
        except TypeError as e:
            raise ValueError("Histogram data is not numeric") from e

    # Get or compute the current scale.
    current_scale = getattr(self, "_scale", None)
    if (current_scale is None) or recompute:
        current_scale = _compute_scale()
        setattr(self, "_scale", current_scale)

    # If other is None → return the (possibly computed) scale.
    if other is None:
        return current_scale

    # If other is provided, it has to be a number.
    if not isinstance(other, (int, float)):
        raise TypeError("other must be a float or None")

    # Cannot rescale if current scale is zero.
    if current_scale == 0:
        raise LenaValueError("Cannot rescale histogram with zero scale")

    # Compute scaling factor.
    factor = other / current_scale

    # Rescale the data.
    try:
        data = getattr(self, "_values")
    except AttributeError:
        data = getattr(self, "values", None)
    if data is None:
        # Attempt to operate on self directly if it's a list/tuple/array.
        if hasattr(self, "__iter__"):
            data = list(self)
            setattr(self, "_values", data)
        else:
            raise ValueError("Cannot rescale histogram: no data found")

    # Apply the factor.
    try:
        new_data = [v * factor for v in data]
    except TypeError as e:
        raise ValueError("Histogram data contains non-numeric entries") from e

    # Store the rescaled data back.
    setattr(self, "_values", new_data)

    # Update stored scale.
    setattr(self, "_scale", other)
    return self

def scale(self, other=None, recompute=False):
    """Compute or set scale (integral of the histogram).

    If *other* is ``None``, return scale of this histogram.
    If its scale was not computed before,
    it is computed and stored for subsequent use
    (unless explicitly asked to *recompute*).
    Note that after changing (filling) the histogram
    one must explicitly recompute the scale
    if it was computed before.

    If a float *other* is provided, rescale self to *other*.

    Histograms with scale equal to zero can't be rescaled.
    :exc:`.LenaValueError` is raised if one tries to do that.
    """
    # Import error class lazily to avoid unnecessary dependency if not used
    try:
        from .errors import LenaValueError  # type: ignore
    except Exception:
        try:
            from errors import LenaValueError  # fallback
        except Exception:
            # Fallback minimal implementation
            class LenaValueError(ValueError):
                pass

    # Validate ``other`` argument
    if other is not None and not isinstance(other, (int, float)):
        raise TypeError("other must be a numeric value or None")

    # Helper to compute current scale
    def _compute_scale():
        # Try to find the numeric values that represent the histogram counts.
        # Common attribute names are ``values`` or ``data`` or the object itself may be iterable.
        try:
            elems = getattr(self, "values")
        except AttributeError:
            try:
                elems = getattr(self, "data")
            except AttributeError:
                # Fallback: try to iterate over self and pick numeric items
                elems = []
                for item in self:
                    if isinstance(item, (int, float)):
                        elems.append(item)
        return float(sum(elems))

    # Retrieve or compute current scale
    try:
        current_scale = self._scale  # type: ignore
    except AttributeError:
        current_scale = None

    if other is None:
        # Return the current scale, computing it if needed
        if current_scale is None or recompute:
            current_scale = _compute_scale()
            try:
                self._scale = current_scale  # type: ignore
            except Exception:
                # The object might not allow setting arbitrary attributes
                pass
        return current_scale

    # Rescaling path
    new_scale = float(other)
    if current_scale is None or recompute:
        current_scale = _compute_scale()
        try:
            self._scale = current_scale  # type: ignore
        except Exception:
            pass

    if current_scale == 0.0:
        raise LenaValueError("Histogram with scale zero cannot be rescaled.")

    factor = new_scale / current_scale

    # Apply rescaling to underlying data
    try:
        # Common attributes: ``values`` or ``data``, or the object itself is mutable
        if hasattr(self, "values"):
            new_vals = [v * factor for v in self.values]  # type: ignore
            self.values = new_vals  # type: ignore
        elif hasattr(self, "data"):
            new_vals = [v * factor for v in self.data]  # type: ignore
            self.data = new_vals  # type: ignore
        else:
            # If the object is iterable and mutable, try in-place update
            for i, val in enumerate(self):
                # Replace element if numeric
                if isinstance(val, (int, float)):
                    try:
                        self[i] = val * factor  # type: ignore
                    except Exception:
                        pass
    except Exception as exc:
        # If any part of the update fails, raise a generic error
        raise RuntimeError(f"Failed to rescale histogram: {exc}") from exc

    # Store the new scale
    try:
        self._scale = new_scale  # type: ignore
    except Exception:
        pass

    return new_scale

def scale(self, other=None, recompute=False):
    """Compute or set scale (integral of the histogram).

    If *other* is ``None``, return scale of this histogram.
    If its scale was not computed before,
    it is computed and stored for subsequent use
    (unless explicitly asked to *recompute*).
    Note that after changing (filling) the histogram
    one must explicitly recompute the scale
    if it was computed before.

    If a float *other* is provided, rescale self to *other*.

    Histograms with scale equal to zero can't be rescaled.
    :exc:`.LenaValueError` is raised if one tries to do that.
    """
    # Helper to compute current integral
    def _current_scale():
        if hasattr(self, 'data'):
            return sum(self.data)
        if hasattr(self, 'entries'):
            return sum(self.entries)
        if hasattr(self, 'values'):
            return sum(self.values)
        raise AttributeError("Histogram data not found; cannot compute scale.")

    # Decide whether to recompute the stored scale
    need_recompute = recompute or not hasattr(self, "_scale") or self._scale is None

    if other is None:
        # Return (and possibly compute) the current scale
        if need_recompute:
            self._scale = _current_scale()
        return self._scale

    # Rescaling to new target value
    if not isinstance(other, (int, float)):
        raise TypeError("Scale must be a numeric value.")
    # Ensure we have the current scale
    if need_recompute:
        current = _current_scale()
        self._scale = current
    else:
        current = self._scale

    if current == 0:
        raise ValueError("Cannot rescale a histogram with zero scale.")  # .LenaValueError

    factor = other / current

    # Apply scaling to histogram data
    if hasattr(self, 'data'):
        self.data = [v * factor for v in self.data]
    elif hasattr(self, 'entries'):
        self.entries = [v * factor for v in self.entries]
    elif hasattr(self, 'values'):
        self.values = [v * factor for v in self.values]
    else:
        raise AttributeError("Histogram data not found; cannot rescale.")

    # Store the new scale
    self._scale = other
    return None

def scale(self, other=None):
        """Get or set the scale of the graph.

        If *other* is ``None``, return the scale of this graph.

        If a numeric *other* is provided, rescale to that value.
        If the graph has unknown or zero scale,
        rescaling that will raise :exc:`~.LenaValueError`.

        To get meaningful results, graph's fields are used.
        Only the last coordinate is rescaled.
        For example, if the graph has *x* and *y* coordinates,
        then *y* will be rescaled, and for a 3-dimensional graph
        *z* will be rescaled.
        All errors are rescaled together with their coordinate.
        """
        # Return existing scale if no new value is requested
        if other is None:
            return getattr(self, "scale", None)

        # Validate the new scale value
        if not isinstance(other, (int, float)):
            raise TypeError("scale expects a numeric value as the new scale.")

        # Check that the graph currently has a valid scale to work from
        current_scale = getattr(self, "scale", None)
        if current_scale is None or current_scale == 0:
            raise LenaValueError("Cannot rescale a graph with unknown or zero scale.")

        # Compute the factor by which to multiply the last coordinate values
        factor = other / current_scale

        # Determine which field constitutes the last coordinate to be rescored
        if hasattr(self, "fields") and isinstance(self.fields, list) and self.fields:
            last_field = self.fields[-1]
        else:
            # If no explicit fields list, attempt to infer from data item keys
            if hasattr(self, "data") and self.data:
                sample_item = self.data[0]
            elif hasattr(self, "points") and self.points:
                sample_item = self.points[0]
            else:
                raise LenaValueError("Graph contains no data to rescale.")
            if isinstance(sample_item, dict):
                keys = list(sample_item.keys())
                if not keys:
                    raise LenaValueError("Data items contain no coordinate keys.")
                last_field = keys[-1]
            else:
                # Use attribute names of the sample item as a fallback
                attrs = [attr for attr in dir(sample_item) if not attr.startswith("_")]
                if not attrs:
                    raise LenaValueError("Data items contain no coordinate attributes.")
                last_field = attrs[-1]

        # Rescale the last coordinate (and its error, if present) for every data point
        data_container = getattr(self, "data", None) or getattr(self, "points", None) or []
        for item in data_container:
            if isinstance(item, dict):
                # Rescale the coordinate value
                if last_field in item:
                    try:
                        item[last_field] *= factor
                    except Exception:
                        # Skip if value cannot be scaled
                        pass
                # Rescale any associated error field
                error_key = f"{last_field}_error"
                if error_key in item:
                    try:
                        item[error_key] *= factor
                    except Exception:
                        pass
            else:
                # Rescale the coordinate attribute
                if hasattr(item, last_field):
                    val = getattr(item, last_field)
                    try:
                        setattr(item, last_field, val * factor)
                    except Exception:
                        pass
                # Rescale the error attribute, if it follows the naming convention
                error_attr = f"{last_field}_error"
                if hasattr(item, error_attr):
                    err_val = getattr(item, error_attr)
                    try:
                        setattr(item, error_attr, err_val * factor)
                    except Exception:
                        pass

        # Update the graph's scale to the new value
        self.scale = other
        return None

def scale(self, other=None):
    """Get or set the scale of the graph.

    If *other* is ``None``, return the scale of this graph.

    If a numeric *other* is provided, rescale to that value.
    If the graph has unknown or zero scale,
    rescaling that will raise :exc:`~.LenaValueError`.

    To get meaningful results, graph's fields are used.
    Only the last coordinate is rescaled.
    For example, if the graph has *x* and *y* coordinates,
    then *y* will be rescaled, and for a 3-dimensional graph
    *z* will be rescaled.
    All errors are rescaled together with their coordinate.
    """
    # Current scale (may be stored on the instance)
    current_scale = getattr(self, "scale", None)

    # If no argument given, simply return the current scale
    if other is None:
        return current_scale

    # Validate new scale
    if not isinstance(other, (int, float)):
        raise TypeError(f"Scale must be numeric, got {type(other).__name__}")
    if current_scale is None or current_scale == 0:
        raise LenaValueError("Cannot rescale graph with unknown or zero scale")

    # Calculate scaling factor
    factor = other / current_scale

    # Determine the last field (if available)
    last_field = None
    if hasattr(self, "get_fields") and callable(self.get_fields):
        try:
            fields = self.get_fields()
            if fields:
                last_field = fields[-1]
        except Exception:
            pass

    # Helper to rescale a coordinate entry
    def _scale_coord(coord, idx):
        if last_field is None:
            # Assume coord is a sequence and take the last element
            coord[-1] = coord[-1] * factor
        else:
            # If coord is a mapping, use the last field
            if isinstance(coord, dict) and last_field in coord:
                coord[last_field] = coord[last_field] * factor

    # Rescale data points
    data_attrs = ["data", "points", "nodes"]
    for attr in data_attrs:
        points = getattr(self, attr, None)
        if points and isinstance(points, (list, tuple)):
            for i, point in enumerate(points):
                try:
                    if isinstance(point, (list, tuple)):
                        _scale_coord(point, i)
                    elif isinstance(point, dict):
                        _scale_coord(point, i)
                except Exception:
                    continue

    # Rescale error values
    error_attrs = ["errors", "point_errors", "data_errors"]
    for attr in error_attrs:
        errs = getattr(self, attr, None)
        if errs and isinstance(errs, (list, tuple)):
            for i, err in enumerate(errs):
                try:
                    if isinstance(err, (list, tuple)):
                        _scale_coord(err, i)
                    elif isinstance(err, dict):
                        _scale_coord(err, i)
                except Exception:
                    continue

    # Update the stored scale value
    self.scale = other
    return None

def scale(self, other=None):
    """
    Get or set the scale of the graph.

    If *other* is ``None``, return the scale of this graph.

    If a numeric *other* is provided, rescale to that value.
    If the graph has unknown or zero scale,
    rescaling that will raise :exc:`~.LenaValueError`.

    To get meaningful results, graph's fields are used.
    Only the last coordinate is rescaled.
    For example, if the graph has *x* and *y* coordinates,
    then *y* will be rescaled, and for a 3-dimensional graph
    *z* will be rescaled.
    All errors are rescaled together with their coordinate.
    """
    # getter
    if other is None:
        return getattr(self, "scale", None)

    # validate numeric new scale
    try:
        new_scale = float(other)
    except TypeError:
        raise TypeError("Scale must be numeric, not %r" % (other,))
    if new_scale == 0.0:
        raise LenaValueError("Cannot rescale to zero scale")

    # current scale must exist
    current_scale = getattr(self, "scale", None)
    if current_scale is None or current_scale == 0.0:
        raise LenaValueError("Current scale unknown or zero; cannot rescale")

    # if scale unchanged, nothing to do
    if current_scale == new_scale:
        return

    # scaling factor
    factor = new_scale / current_scale

    # fetch fields to modify; a graph should expose an iterable of field objects
    fields = getattr(self, "fields", [])
    if not fields:
        raise LenaValueError("Graph has no fields; cannot rescale")

    last_field = fields[-1]

    for f in fields:
        # rescale coordinate values of the last field only
        if f is last_field:
            if hasattr(f, "values"):
                try:
                    f.values = [v * factor for v in f.values]
                except Exception:
                    pass  # ignore if values not numeric
            if hasattr(f, "value"):  # accommodate single‑value fields
                try:
                    f.value = f.value * factor
                except Exception:
                    pass

        # rescale errors associated with any field
        if hasattr(f, "error"):
            try:
                f.error = [e * factor for e in f.error]
            except Exception:
                pass
        if hasattr(f, "error_values"):
            try:
                f.error_values = [e * factor for e in f.error_values]
            except Exception:
                pass

    # store the new scale
    self.scale = new_scale
    return None

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    """Convert a :class:`.histogram` to a :class:`.graph`.

    *make_value* is a function to set the value of a graph's point.
    By default it is bin content.
    *make_value* accepts a single value (bin content) without context.

    This option could be used to create graph's error bars.
    For example, to create a graph with errors
    from a histogram where bins contain
    a named tuple with fields *mean*, *mean_error* and a context
    one could use

    >>> make_value = lambda bin_: (bin_.mean, bin_.mean_error)

    *get_coordinate* defines what the coordinate
    of a graph point created from a histogram bin will be.
    It can be "left" (default), "right" and "middle".

    *field_names* set field names of the graph. Their number
    must be the same as the dimension of the result.
    For a *make_value* above they would be
    *("x", "y_mean", "y_mean_error")*.

    *scale* becomes the graph's scale (unknown by default).
    If it is ``True``, it uses the histogram scale.

    *hist* must contain only numeric bins (without context)
    or *make_value* must remove context when creating a numeric graph.

    Return the resulting graph.
    """
    # Validate basic input
    if not hasattr(hist, "__iter__"):
        raise TypeError("hist must be an iterable histogram")
    if not isinstance(field_names, (tuple, list)):
        raise TypeError("field_names must be a tuple or list")
    if not isinstance(get_coordinate, str):
        raise TypeError("get_coordinate must be a string")
    # Default make_value
    if make_value is None:
        def make_value(x):
            return x
    # Determine graph scale
    graph_scale = None
    if scale is True:
        # Try to use histogram's scale
        try:
            graph_scale = getattr(hist, "scale", None)
        except Exception:
            graph_scale = None
    elif scale is not None:
        graph_scale = scale
    # Create an empty graph with specified fields
    try:
        graph = Graph(field_names=field_names, scale=graph_scale)
    except NameError:
        # Fallback: create a simple container if Graph is undefined
        class SimpleGraph:
            def __init__(self, field_names, scale=None):
                self.field_names = tuple(field_names)
                self.scale = scale
                self.data = []

            def add_point(self, point):
                if len(point) != len(self.field_names):
                    raise ValueError(f"Point dimension {len(point)} != expected {len(self.field_names)}")
                self.data.append(point)

            def __iter__(self):
                return iter(self.data)

        graph = SimpleGraph(field_names, scale=graph_scale)
    # Iterate over histogram bins
    for bin_ in hist:
        try:
            # Get coordinate from the bin
            if hasattr(bin_, get_coordinate):
                coord = getattr(bin_, get_coordinate)
            else:
                # Fallback: try known attributes
                if hasattr(bin_, 'left') and hasattr(bin_, 'right'):
                    if get_coordinate == "left":
                        coord = bin_.left
                    elif get_coordinate == "right":
                        coord = bin_.right
                    else:  # middle
                        coord = (bin_.left + bin_.right) / 2.0
                elif hasattr(bin_, 'center'):
                    coord = bin_.center
                else:
                    raise AttributeError(f"Cannot determine coordinate '{get_coordinate}' from bin")
        except Exception as e:
            raise ValueError(f"Error getting coordinate from bin: {e}") from e
        # Get bin content
        content = getattr(bin_, "content", bin_)
        # Compute the value(s) for the graph point
        try:
            value_tuple = make_value(content)
        except Exception as e:
            raise ValueError(f"make_value function raised an error: {e}") from e
        # Ensure value_tuple is iterable if more than one field expected
        if isinstance(value_tuple, (tuple, list)):
            v = list(value_tuple)
        else:
            v = [value_tuple]
        # Build point: coordinate + values
        point = [coord] + v
        # Add point to graph
        try:
            graph.add_point(point)
        except AttributeError:
            # If graph has append or similar
            try:
                graph.append(point)
            except Exception as e:
                raise RuntimeError(f"Unable to add point to graph: {e}") from e
    return graph

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    """Convert a :class:`.histogram` to a :class:`.graph`.

    *make_value* is a function to set the value of a graph's point.
    By default it is bin content.
    *make_value* accepts a single value (bin content) without context.

    This option could be used to create graph's error bars.
    For example, to create a graph with errors
    from a histogram where bins contain
    a named tuple with fields *mean*, *mean_error* and a context
    one could use

    >>> make_value = lambda bin_: (bin_.mean, bin_.mean_error)

    *get_coordinate* defines what the coordinate
    of a graph point created from a histogram bin will be.
    It can be "left" (default), "right" and "middle".

    *field_names* set field names of the graph. Their number
    must be the same as the dimension of the result.
    For a *make_value* above they would be
    *("x", "y_mean", "y_mean_error")*.

    *scale* becomes the graph's scale (unknown by default).
    If it is ``True``, it uses the histogram scale.

    *hist* must contain only numeric bins (without context)
    or *make_value* must remove context when creating a numeric graph.

    Return the resulting graph.
    """
    # Validate parameters
    if make_value is not None and not callable(make_value):
        raise TypeError("make_value must be callable or None")
    if get_coordinate not in {"left", "right", "middle"}:
        raise ValueError("get_coordinate must be one of 'left', 'right', 'middle'")
    if not isinstance(field_names, (list, tuple)):
        raise TypeError("field_names must be a list or tuple")
    # Determine scale for the graph
    if scale is True:
        try:
            graph_scale = getattr(hist, "scale", None)
        except Exception:
            graph_scale = None
    else:
        graph_scale = scale
    # Attempt to locate the Graph class from the histogram's module
    Graph_cls = None
    try:
        Graph_cls = getattr(type(hist), "Graph", None)
    except Exception:
        pass
    if Graph_cls is None:
        # Fallback: create a simple graph container
        class SimpleGraph:
            def __init__(self, field_names, scale):
                self.field_names = tuple(field_names)
                self.scale = scale
                self.points = []

            def add_point(self, *values):
                if len(values) != len(self.field_names):
                    raise ValueError(
                        f"Expected {len(self.field_names)} values, got {len(values)}")
                self.points.append(tuple(values))

