        return getattr(bin_obj, "content", bin_obj)
    # Prepare coordinate extraction
    def _coord(edges, i):
        if get_coordinate == "left":
            return edges[i]
        if get_coordinate == "right":
            return edges[i + 1]
        return (edges[i] + edges[i + 1]) / 2
    # Extract bins and edges from histogram
    bins = None
    edges = None
    values = None
    # Attempt common histogram attributes
    if hasattr(hist, "bins") and hasattr(hist, "bin_edges"):
        edges = getattr(hist, "bin_edges")
        bins = getattr(hist, "bins")
        if not isinstance(bins, (list, tuple)):
            bins = list(bins)
    elif hasattr(hist, "values") and hasattr(hist, "bin_edges"):
        edges = getattr(hist, "bin_edges")
        values = getattr(hist, "values")
        if not isinstance(values, (list, tuple)):
            values = list(values)
    elif hasattr(hist, "__len__") and not hasattr(hist, "values") and not hasattr(hist, "bins"):
        values = list(hist)
        # No explicit edges; use index as coordinate
        edges = None
    else:
        raise ValueError("Unrecognized histogram format; required attributes missing.")
    # Iterate over bins and construct graph points
    if edges is not None and bins is not None:
        nbins = len(bins)
        if len(edges) != nbins + 1:
            raise ValueError("bin_edges length must be one more than number of bins")
        for i in range(nbins):
            content = _bin_value(bins[i])
            coord = _coord(edges, i)
            if make_value is None:
                point_vals = (coord, content)
            else:
                mv = make_value(content)
                if not isinstance(mv, tuple):
                    mv = (mv,)
                point_vals = (coord,) + mv
            if len(field_names) != len(point_vals):
                raise ValueError(f"field_names length {len(field_names)} does not match "
                                 f"point dimension {len(point_vals)}")
            Graph_obj.add_point(*point_vals)
    elif edges is not None and values is not None:
        nbins = len(values)
        if len(edges) != nbins + 1:
            raise ValueError("bin_edges length must be one more than number of values")
        for i in range(nbins):
            content = values[i]
            coord = _coord(edges, i)
            if make_value is None:
                point_vals = (coord, content)
            else:
                mv = make_value(content)
                if not isinstance(mv, tuple):
                    mv = (mv,)
                point_vals = (coord,) + mv
            if len(field_names) != len(point_vals):
                raise ValueError(f"field_names length {len(field_names)} does not match "
                                 f"point dimension {len(point_vals)}")
            Graph_obj.add_point(*point_vals)
    elif values is not None and edges is None:
        nbins = len(values)
        for i in range(nbins):
            content = values[i]
            coord = i  # use index as x-coordinate
            if make_value is None:
                point_vals = (coord, content)
            else:
                mv = make_value(content)
                if not isinstance(mv, tuple):
                    mv = (mv,)
                point_vals = (coord,) + mv
            if len(field_names) != len(point_vals):
                raise ValueError(f"field_names length {len(field_names)} does not match "
                                 f"point dimension {len(point_vals)}")
            Graph_obj.add_point(*point_vals)
    else:
        raise ValueError("No valid bin data found in the histogram.")
    # Set scale if attribute exists and not already set
    if hasattr(Graph_obj, "scale") and Graph_obj.scale is None:
        Graph_obj.scale = graph_scale
    return Graph_obj

def _verify(iface, candidate, tentative=False, vtype=None):
    """Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
      interface using ``iface.providedBy`` (unless *tentative* is `True`,
      in which case this step is skipped). This means that the candidate's class
      declares that it `implements <zope.interface.implementer>` the interface,
      or the candidate itself declares that it `provides <zope.interface.provider>`
      the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
      extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
       checked passed.
    :raises zope.interface.Invalid: If any of the previous
       conditions does not hold.
    """
    import inspect as _inspect
    errors = []

    # Check that candidate declares provision of the interface
    if not tentative:
        try:
            if not iface.providedBy(candidate):
                errors.append(zope.interface.Invalid("Candidate does not provide interface %s" % (iface,)))
        except Exception as exc:
            errors.append(zope.interface.Invalid("Error checking providedBy: %s" % exc))

    # Gather interface attribute/ method definitions
    for name in iface.names():
        # ``iface[name]`` gives the declared attribute object
        iface_item = iface[name]
        has_attr = hasattr(candidate, name)
        # Attributes
        if hasattr(iface_item, 'type'):  # zope.interface._InterfaceDeclaration
            dtype = iface_item.type
        else:
            dtype = None

        if dtype == 'attribute':
            if not has_attr:
                errors.append(AttributeError("Missing required attribute '%s'" % name))
        elif dtype == 'method':
            if not has_attr:
                errors.append(AttributeError("Missing required method '%s'" % name))
            else:
                # Compare signature if possible
                iface_sig = None
                try:
                    iface_sig = _inspect.signature(iface_item)
                except Exception:
                    pass
                try:
                    cand_sig = _inspect.signature(getattr(candidate, name))
                except Exception:
                    cand_sig = None
                if iface_sig and cand_sig:
                    if iface_sig.parameters != cand_sig.parameters:
                        errors.append(ValueError(
                            "Signature mismatch for method '%s': expected %s got %s" %
                            (name, iface_sig, cand_sig)))
                # else: could not introspect; skip signature check
        else:
            # Unknown type; ignore
            pass

    if errors:
        if len(errors) == 1:
            raise errors[0]
        else:
            # Aggregate all errors
            raise zope.interface.Invalid("Multiple interface verification errors", errors=errors)

    return True

def _verify(iface, candidate, tentative=False, vtype=None):
    """Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
      interface using ``iface.providedBy`` (unless *tentative* is `True`,
      in which case this step is skipped). This means that the candidate's class
      declares that it `implements <zope.interface.implementer>` the interface,
      or the candidate itself declares that it `provides <zope.interface.provider>`
      the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
      extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
       checked passed.
    :raises zope.interface.Invalid: If any of the previous
       conditions does not hold.
    """
    import inspect
    errors = []

    # Skip interface provision check if tentative
    if not tentative:
        try:
            from zope.interface import providedBy
        except Exception:
            # Cannot perform the check if zope.interface is not available
            pass
        else:
            if not iface.providedBy(candidate):
                errors.append(f"Candidate does not provide interface {iface.__name__}")

    # Gather all names defined by the interface
    try:
        iface_names = list(iface.names())
    except Exception:
        iface_names = []

    for name in iface_names:
        # The interface may define attributes or methods
        try:
            iface_member = getattr(iface, name)
        except Exception:
            continue

        # Determine if it is a method (callable) or an attribute
        if callable(iface_member):
            # Method: verify existence and signature
            if not hasattr(candidate, name):
                errors.append(f"Missing required method '{name}'")
                continue
            cand_method = getattr(candidate, name)
            if not callable(cand_method):
                errors.append(f"Attribute '{name}' is not callable")
                continue

            # Compare signatures if they can be inspected
            try:
                iface_sig = inspect.signature(iface_member)
                cand_sig = inspect.signature(cand_method)
                if iface_sig != cand_sig:
                    errors.append(
                        f"Signature mismatch for method '{name}': "
                        f"interface expects {iface_sig}, candidate has {cand_sig}"
                    )
            except Exception:
                # If introspection fails for any reason, skip the comparison
                pass
        else:
            # Attribute: verify presence
            if not hasattr(candidate, name):
                errors.append(f"Missing required attribute '{name}'")

    # Exception handling: collect all errors, replicate old behaviour
    if errors:
        try:
            from zope.interface import Invalid
        except Exception:
            # If zope.interface is not available, raise a generic Exception
            raise Exception("\n".join(errors))
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid("\n".join(errors))

    return True

def _verify(iface, candidate, tentative=False, vtype=None):
    from inspect import signature, Parameter
    from zope.interface import Invalid

    errors = []

    # 1. Check interface provision
    if not tentative:
        if not iface.providedBy(candidate):
            errors.append(
                f"Candidate {candidate!r} does not provide interface {iface.__name__}."
            )

    # Helper: obtain signature string
    def sig_str(sig):
        # format as typical signature string
        params = []
        for name, param in sig.parameters.items():
            params.append(str(param))
        return f"({', '.join(params)})"

    # 2. Check required methods
    for name, iface_sig in getattr(iface, "_methods", {}).items():
        # Retrieve implementation
        impl = getattr(candidate, name, None)
        if impl is None:
            errors.append(f"Method {name!r} required by {iface.__name__} not found on {candidate!r}.")
            continue
        # Check signature compatibility
        try:
            impl_sig = signature(impl)
        except Exception as exc:  # pragma: no cover
            errors.append(f"Could not introspect signature of method {name!r}: {exc!r}")
            continue
        # Compare number of parameters and kinds
        iface_params = list(iface_sig.parameters.values())
        impl_params = list(impl_sig.parameters.values())
        if len(iface_params) != len(impl_params):
            errors.append(
                f"Signature mismatch for {name!r}: expected {len(iface_params)} params, "
                f"got {len(impl_params)} params on {candidate!r}."
            )
            continue
        # Compare parameter kinds (POSITIONAL_OR_KEYWORD, VAR_POSITIONAL, etc.)
        for iparam, imp in zip(iface_params, impl_params):
            if iparam.kind != imp.kind:
                errors.append(
                    f"Signature mismatch for {name!r}: parameter {iparam.name!r} "
                    f"has kind {iparam.kind} in interface but {imp.kind} in candidate."
                )
                break
        # Optional: compare return annotation presence (zope uses annotations)
        iface_ret = iface_sig.return_annotation
        impl_ret = impl_sig.return_annotation
        if iface_ret is not Parameter.empty and impl_ret is Parameter.empty:
            errors.append(
                f"Signature mismatch for {name!r}: interface expects a return annotation "
                f"{iface_ret!r} but candidate has none."
            )

    # 3. Check required attributes
    required_attrs = getattr(iface, "_required_attributes", set())
    for attr in required_attrs:
        if not hasattr(candidate, attr):
            errors.append(
                f"Attribute {attr!r} required by {iface.__name__} not found on {candidate!r}."
            )

    # 4. Raise errors if any
    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        raise Invalid("Multiple interface verification errors:\n" + "\n".join(errors))

    return True

def verifyObject(iface, candidate, tentative=False):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
      interface using ``iface.providedBy`` (unless *tentative* is `True`,
      in which case this step is skipped). This means that the candidate's class
      declares that it `implements <zope.interface.implementer>` the interface,
      or the candidate itself declares that it `provides <zope.interface.provider>`
      the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
      extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
    checked passed.
    :raises zope.interface.Invalid: If any of the previous
    conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    import inspect
    from zope.interface import Invalid

    errors = []

    # Step 1: check providedBy unless tentative
    if not tentative:
        try:
            if not iface.providedBy(candidate):
                raise Invalid("Candidate does not provide %s" % iface)
        except Exception as exc:
            raise Invalid("Failed to check providedBy: %s" % exc) from exc

    # Helper to compare two signatures
    def _sigs_match(sig1, sig2):
        params1 = list(sig1.parameters.values())
        params2 = list(sig2.parameters.values())
        if len(params1) != len(params2):
            return False
        for p1, p2 in zip(params1, params2):
            if p1.kind != p2.kind:
                return False
            if p1.default != p2.default:
                return False
            if p1.annotation != p2.annotation:
                return False
        return True

    # Step 2: gather required methods and attributes from iface
    # Methods: functions defined on the interface
    required_methods = {
        name: obj
        for name, obj in inspect.getmembers(iface)
        if inspect.isfunction(obj) and not name.startswith("_")
    }

    # Attributes: non-callable members that are not special
    required_attrs = {
        name
        for name, obj in inspect.getmembers(iface)
        if not inspect.isroutine(obj) and not name.startswith("_")
    }

    # Check methods
    for name, iface_method in required_methods.items():
        candidate_method = getattr(candidate, name, None)
        if candidate_method is None:
            errors.append(
                Invalid("Missing required method: %s" % name)
            )
            continue
        try:
            iface_sig = inspect.signature(iface_method)
            cand_sig = inspect.signature(candidate_method)
        except Exception as exc:
            errors.append(
                Invalid(
                    "Could not inspect signatures for method %s: %s"
                    % (name, exc)
                )
            )
            continue
        if not _sigs_match(cand_sig, iface_sig):
            errors.append(
                Invalid(
                    "Signature mismatch for method %s: expected %s, got %s"
                    % (name, iface_sig, cand_sig)
                )
            )

    # Check attributes
    for name in required_attrs:
        if not hasattr(candidate, name):
            errors.append(
                Invalid("Missing required attribute: %s" % name)
            )

    if errors:
        if len(errors) == 1:
            raise errors[0]
        else:
            raise Invalid(errors)

    return True

def verifyObject(iface, candidate, tentative=False):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
      interface using ``iface.providedBy`` (unless *tentative* is `True`,
      in which case this step is skipped). This means that the candidate's class
      declares that it `implements <zope.interface.implementer>` the interface,
      or the candidate itself declares that it `provides <zope.interface.provider>`
      the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
      extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
    checked passed.
    :raises zope.interface.Invalid: If any of the previous
    conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    inspect = __import__('inspect')
    from zope.interface import Invalid

    errors = []

    # 1. Verify interface is claimed
    try:
        if not tentative and not iface.providedBy(candidate):
            errors.append(
                f'{candidate!r} does not claim to provide interface {iface!r}'
            )
    except Exception as e:
        errors.append(f'Error checking interface claim: {e}')

    # 2. Gather required methods and attributes from the interface definition
    #    We inspect the interface's __dict__ for callables and non-callables.
    method_names = []
    attr_names = []
    for name, value in iface.__dict__.items():
        if name.startswith('__'):
            continue
        if callable(value):
            method_names.append(name)
        else:
            attr_names.append(name)

    # 3. Check methods existence and signature
    for name in method_names:
        if not hasattr(candidate, name):
            errors.append(f"method '{name}' missing in {candidate!r}")
            continue
        iface_method = getattr(iface, name, None)
        cand_method = getattr(candidate, name, None)
        try:
            iface_sig = inspect.signature(iface_method) if iface_method else None
            cand_sig = inspect.signature(cand_method) if cand_method else None
            if iface_sig and cand_sig:
                # Compare parameters (order, names, kind)
                iface_params = list(iface_sig.parameters.values())
                cand_params = list(cand_sig.parameters.values())
                if len(iface_params) != len(cand_params):
                    errors.append(
                        f"method '{name}' signature length mismatch in {candidate!r}"
                    )
                else:
                    for p_i, p_c in zip(iface_params, cand_params):
                        if p_i.kind != p_c.kind:
                            errors.append(
                                f"method '{name}' parameter kind mismatch in {candidate!r}"
                            )
                            break
                        if p_i.name != p_c.name:
                            errors.append(
                                f"method '{name}' parameter name mismatch in {candidate!r}"
                            )
                            break
        except (ValueError, TypeError):
            # If the signatures cannot be inspected (e.g. builtins), skip signature check
            pass

    # 4. Check required attributes
    for name in attr_names:
        try:
            getattr(candidate, name)
        except AttributeError:
            errors.append(f"attribute '{name}' missing in {candidate!r}")

    # 5. Raise exceptions if any errors collected
    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid("; ".join(errors))

    return True

def verifyClass(iface, candidate, tentative=False):
    """Verify that the *candidate* might correctly provide *iface*."""
    if not isinstance(iface, type):
        raise TypeError("iface must be a class or type")

    # Determine candidate's class
    if isinstance(candidate, type):
        cand_cls = candidate
    else:
        try:
            cand_cls = candidate.__class__
        except AttributeError:
            if tentative:
                return False
            raise TypeError("candidate is not an object with a __class__ attribute")

    try:
        if not issubclass(cand_cls, iface):
            if tentative:
                return False
            raise ValueError(f"{cand_cls.__name__} does not provide interface {iface.__name__}")
    except TypeError as exc:
        # Happens if cand_cls or iface isn't a class
        if tentative:
            return False
        raise TypeError(f"Error checking subclass: {exc}") from exc

    return True

def verifyClass(iface, candidate, tentative=False):
    """Verify that the *candidate* might correctly provide *iface*."""
    # Guard against missing interface or candidate
    if iface is None:
        raise ValueError("iface must be specified")
    if candidate is None:
        return False

    try:
        # If iface is a tuple of interfaces, succeed if any of them match
        if isinstance(iface, tuple):
            return any(verifyClass(i, candidate, tentative) for i in iface)

        # Direct subclass/instance validation
        if isinstance(candidate, type):
            if issubclass(candidate, iface):
                return True
        else:
            if isinstance(candidate, iface):
                return True

        # Handle Abstract Base Classes (ABCs) with __abstractmethods__
        abstract_methods = getattr(iface, "__abstractmethods__", None)
        if abstract_methods:
            # If tentative, require at least one method to be implemented
            if tentative:
                return any(hasattr(candidate, m) for m in abstract_methods)
            # Otherwise all abstract methods must be present
            return all(hasattr(candidate, m) for m in abstract_methods)

        # If none of the above checks passed, candidate does not provide the interface
        return False
    except Exception:
        # Any unexpected error means the candidate cannot be verified as providing the iface
        return False

def verifyClass(iface, candidate, tentative=False):
    """Verify that the *candidate* might correctly provide *iface*.

    Parameters
    ----------
    iface : type
        The interface or abstract class that ``candidate`` is expected to implement.
    candidate : object or type
        The object or class to be tested for compatibility with ``iface``.
    tentative : bool, optional
        If ``True``, the function will return ``False`` on failure instead of
        raising an exception. Default is ``False``.

    Returns
    -------
    bool
        ``True`` if ``candidate`` appears to satisfy the interface, otherwise
        ``False`` (or ``False``/raise when tentative is ``False``).

    Raises
    ------
    TypeError
        If ``iface`` is not a type or ``candidate`` is not a class or an
        instance capable of providing the interface.
    """
    # Validate the interface
    if not isinstance(iface, type):
        raise TypeError("iface must be a class or interface type")

    # A ``None`` candidate can never implement an interface
    if candidate is None:
        return False

    # Helper to inspect attributes of the interface
    def iface_attrs():
        return {
            name: attr
            for name, attr in vars(iface).items()
            if not name.startswith("_")
        }

    # If candidate is a class, perform a subclass check
    if isinstance(candidate, type):
        try:
            return issubclass(candidate, iface)
        except Exception:
            # In case candidate is not a proper class construct
            if tentative:
                return False
            raise

    # Otherwise assume candidate is an instance; check that it has the
    # required attributes and methods
    try:
        for name, ref in iface_attrs().items():
            if not hasattr(candidate, name):
                if tentative:
                    return False
                raise AttributeError(
                    f"Candidate object is missing required attribute '{name}'."
                )
            # If the interface attribute is callable, ensure the candidate's
            # corresponding attribute is also callable
            if callable(ref):
                attr = getattr(candidate, name)
                if not callable(attr):
                    if tentative:
                        return False
                    raise TypeError(
                        f"Attribute '{name}' of candidate is not callable as "
                        f"required by the interface."
                    )
        return True
    except Exception as exc:
        if tentative:
            return False
        raise

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.

    Returns True if the candidate satisfies the interface; otherwise,
    returns False if *tentative* is True, or raises TypeError if
    *tentative* is False.

    This check is intentionally lightweight: it ensures that the candidate
    (either a class or an instance) has all public callable attributes
    defined on the interface. It does not perform a deep inheritance
    analysis or type checks beyond existence.
    """
    try:
        # Validate arguments
        if not isinstance(iface, type):
            raise TypeError("iface must be a class or interface type")
        if candidate is None:
            raise TypeError("candidate must not be None")

        # Determine the set of public method names that the interface requires.
        required = set()
        for name in dir(iface):
            if name.startswith('_'):
                continue  # ignore private/special attributes
            attr = getattr(iface, name, None)
            if callable(attr):
                required.add(name)

        # If no methods are found, we consider the candidate valid by default.
        if not required:
            return True

        # Helper to check attribute existence on a candidate object/class.
        def has_attributes(obj, names):
            for n in names:
                if not hasattr(obj, n):
                    return False
            return True

        # Check the candidate.
        if isinstance(candidate, type):
            # candidate is a class; check that it defines the required methods.
            if not has_attributes(candidate, required):
                if tentative:
                    return False
                missing = [name for name in required if not hasattr(candidate, name)]
                raise TypeError(
                    f"Candidate class '{candidate.__name__}' is missing required "
                    f"methods for interface '{iface.__name__}': {', '.join(missing)}"
                )
        else:
            # candidate is an instance; check that its class (or the instance) provides the methods.
            if not has_attributes(candidate, required):
                if tentative:
                    return False
                missing = [name for name in required if not hasattr(candidate, name)]
                raise TypeError(
                    f"Candidate instance of type '{type(candidate).__name__}' is missing "
                    f"required methods for interface '{iface.__name__}': {', '.join(missing)}"
                )

        return True
    except Exception as exc:
        if tentative:
            return False
        raise

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    # Validate inputs
    if not isinstance(bases, (list, tuple)):
        raise TypeError("bases must be a list or tuple of classes")
    if explicit_mc is not None and not isinstance(explicit_mc, type):
        raise TypeError("explicit __metaclass__ must be a metaclass (type)")

    # Collect candidate metaclasses from bases
    metaclasses = []
    for base in bases:
        if not isinstance(base, type):
            raise TypeError(f"base {base!r} is not a class")
        metaclasses.append(type(base))

    # Add explicit metaclass if provided
    if explicit_mc is not None:
        # If the explicit metaclass is already in the list, remove the duplicate
        if explicit_mc in metaclasses:
            metaclasses.remove(explicit_mc)
        metaclasses.insert(0, explicit_mc)

    # If no metaclasses, default to `type`
    if not metaclasses:
        return type

