def format_dt(dt):
    """Format a datetime in the way that D* nodes expect.

    The D* nodes expect an ISO 8601 date-time string with seconds precision
    followed by a UTC timezone designator ``Z``.  If ``dt`` is a naive
    ``datetime.datetime`` object it is treated as UTC.  If ``dt`` is a
    ``datetime.date`` instance it is combined with midnight.
    """
    try:
        import datetime
    except ImportError as exc:
        raise RuntimeError("datetime module is required") from exc

    if isinstance(dt, datetime.datetime):
        dt_val = dt
    elif isinstance(dt, datetime.date):
        dt_val = datetime.datetime.combine(dt, datetime.time.min)
    else:
        raise TypeError("format_dt expects a datetime or date instance")

    # Ensure UTC tzinfo
    if dt_val.tzinfo is None:
        dt_val = dt_val.replace(tzinfo=datetime.timezone.utc)
    else:
        dt_val = dt_val.astimezone(datetime.timezone.utc)

    iso_str = dt_val.isoformat(timespec='seconds')
    # Append 'Z' for UTC
    if iso_str.endswith('+00:00'):
        iso_str = iso_str[:-6] + 'Z'
    return iso_str

