    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    # Find the ranges of code blocks (triple-quoted or single backticks)
    code_ranges = []
    for m in re.finditer(r'(```.*?```|`[^`]*`)', text, flags=re.S):
        code_ranges.append((m.start(), m.end()))

    def _inside_code(pos: int) -> bool:
        for s, e in code_ranges:
            if s <= pos < e:
                return True
        return False

    tags: Set[str] = set()

    if replacer is not None:
        parts = []
        last_end = 0
        for m in re.finditer(r'(?<!\w)#(\w+)\b', text):
            start, end = m.span()
            if _inside_code(start):
                continue
            tag_word = m.group(1)
            tags.add('#' + tag_word)
            parts.append(text[last_end:start])
            try:
                replacement = replacer(tag_word)
            except Exception as exc:
                raise RuntimeError(f"Replacer function raised an exception: {exc}") from exc
            parts.append(str(replacement))
            last_end = end
        parts.append(text[last_end:])
        new_text = ''.join(parts)
        return tags, new_text
    else:
        for m in re.finditer(r'(?<!\w)#(\w+)\b', text):
            start, _ = m.span()
            if _inside_code(start):
                continue
            tags.add('#' + m.group(1))
        return tags, text

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    import re
    if not isinstance(text, str):
        raise TypeError("Expected a string, got %r" % (type(text).__name__,))
    # Regex patterns for URLs (http, https, ftp) and www. prefixes
    url_pattern = re.compile(
        r'(?P<prefix>https?://|ftp://)'
        r'(?P<domain>[^\s/]+(?:/[^\s]*)?)',
        re.IGNORECASE)
    www_pattern = re.compile(
        r'(?P<prefix>www\.)'
        r'(?P<domain>[^\s/]+(?:/[^\s]*)?)',
        re.IGNORECASE)
    # Regex pattern for email addresses (simple version)
    email_pattern = re.compile(
        r'(?P<email>[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,})',
        re.IGNORECASE)

    def replace_url(match):
        try:
            href = match.group('prefix') + match.group('domain')
            text = href
            return f'<a href="{href}" target="_blank" rel="nofollow">{text}</a>'
        except Exception:
            return match.group(0)

    def replace_www(match):
        try:
            href = 'http://' + match.group('domain')
            text = match.group(0)
            return f'<a href="{href}" target="_blank" rel="nofollow">{text}</a>'
        except Exception:
            return match.group(0)

    def replace_email(match):
        try:
            email = match.group('email')
            return f'<a href="mailto:{email}">{email}</a>'
        except Exception:
            return match.group(0)

    # First replace full URLs
    text = url_pattern.sub(replace_url, text)
    # Then replace www prefixes
    text = www_pattern.sub(replace_www, text)
    # Finally replace email addresses
    text = email_pattern.sub(replace_email, text)

    return text

