def xml_children_as_dict(node):
    """
    Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversion - child nodes are not recursively processed.
    If multiple child elements share the same tag, the value in the dict will be a
    list of those elements.  Non-element children (e.g., text nodes) are ignored.
    """
    import collections

    # If node isn't an Element, try to get its children via iter()
    try:
        children = list(node)
    except Exception:
        children = []

    # Use a default dict to collect elements by tag
    temp = collections.defaultdict(list)

    for child in children:
        # Only consider Element nodes that have a tag attribute
        if hasattr(child, "tag"):
            temp[child.tag].append(child)

    # Convert lists of length 1 to single elements for convenience
    result = {}
    for tag, elems in temp.items():
        if len(elems) == 1:
            result[tag] = elems[0]
        else:
            result[tag] = elems

    return result

def check_sender_and_entity_handle_match(sender_handle, entity_handle):
    """Ensure that sender and entity handles match.

    Basically we've already verified the sender is who they say when receiving the payload.
    However, the sender might be trying to set another author in the payload itself, since Diaspora
    has the sender in both the payload headers AND the object. We must ensure they're the same.
    """
    # Validate that the two handles are identical. If not, raise an informative error.
    try:
        if sender_handle != entity_handle:
            raise ValueError(
                f"Sender handle '{sender_handle}' does not match the entity handle '{entity_handle}'. "
                "The payload may be attempting to spoof the author."
            )
    except Exception as exc:
        # Catch any unexpected comparison errors and re-raise with context
        raise ValueError(
            f"Failed to validate sender and entity handles: {exc}"
        ) from exc
    # Successful match
    return True

