def parse_diaspora_webfinger(document: str) -> Dict:
    """Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ET

    # Strip leading/trailing whitespace
    document = document.strip()
    if not document:
        raise ValueError("Empty webfinger document")

    # Try JSON first
    try:
        obj = json.loads(document)
        if isinstance(obj, dict):
            return obj
    except Exception:
        pass

    # Fallback to XRD (XML)
    try:
        root = ET.fromstring(document)
    except ET.ParseError as e:
        raise ValueError("Document is neither valid JSON nor XRD XML") from e

    def strip_ns(tag):
        """Remove namespace from an XML tag."""
        return tag.split('}', 1)[-1] if '}' in tag else tag

    result: Dict[str, object] = {}
    for child in root:
        tag = strip_ns(child.tag)
        if tag == 'Subject':
            result['subject'] = child.text
        elif tag == 'Alias':
            result.setdefault('aliases', []).append(child.text or '')
        elif tag == 'Property':
            name = child.attrib.get('name')
            if name:
                result[name] = child.text or ''
        elif tag == 'Link':
            rel = child.attrib.get('rel')
            template = child.attrib.get('template')
            href = child.attrib.get('href')
            value = template or href or child.text
            if rel and value:
                result.setdefault('links', []).append({'rel': rel, 'value': value})
        else:
            # capture any other elements as a simple key/value
            if child.text:
                result[tag] = child.text

    if not result:
        raise ValueError("Unable to parse webfinger document")

    return result

def parse_diaspora_webfinger(document: str) -> Dict:
    """Parse Diaspora webfinger which is either in JSON format (new) or XRD (old)."""
    if not document:
        raise ValueError("Empty document")

    # First try JSON parsing
    try:
        data = json.loads(document)
        if isinstance(data, dict):
            return data
    except Exception:
        pass  # fall back to XRD parsing

    # XRD parsing
    try:
        root = ET.fromstring(document)
        # Helper to handle namespaces
        def find_tag(elem, tag, namespace=None):
            if namespace:
                return elem.find(f"{{{namespace}}}{tag}")
            return elem.find(tag)

        # Namespace may vary; try common XRD namespace
        ns = "http://xri.net/xrd"
        subject_el = find_tag(root, "Subject", ns)
        subject = subject_el.text if subject_el is not None else None

        aliases = []
        for alias_el in root.findall(f"{{{ns}}}Alias"):
            if alias_el.text:
                aliases.append(alias_el.text)

        links = []
        for link_el in root.findall(f"{{{ns}}}Link"):
            rel = link_el.attrib.get("rel")
            href = link_el.attrib.get("href")
            type_ = link_el.attrib.get("type")
            if href:
                links.append({"rel": rel, "href": href, "type": type_})

        result: Dict[str, object] = {}
        if subject:
            result["subject"] = subject
        if aliases:
            result["aliases"] = aliases
        if links:
            result["links"] = links

        return result
    except Exception as e:
        raise ValueError(f"Unable to parse Diaspora webfinger document: {e}")

def parse_diaspora_webfinger(document: str) -> Dict:
    """Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    # Try parsing as JSON first
    try:
        import json
        return json.loads(document)
    except Exception:
        # Fallback to XRD (XML) parsing
        import xml.etree.ElementTree as ET

        try:
            root = ET.fromstring(document)
        except ET.ParseError:
            # If the document cannot be parsed at all, return empty dict
            return {}

        result: Dict = {}
        result['subject'] = None
        result['aliases'] = []
        result['links'] = []

        # Iterate over all elements ignoring namespaces
        for elem in root.iter():
            tag = elem.tag
            if tag.endswith('Subject'):
                result['subject'] = elem.text or ''
            elif tag.endswith('Alias'):
                # Ignore bad alias entries
                if elem.text:
                    result['aliases'].append(elem.text)
            elif tag.endswith('Link'):
                rel = elem.attrib.get('rel')
                href = elem.attrib.get('href')
                template = elem.attrib.get('template')
                link_data = {'rel': rel}
                if href is not None:
                    link_data['href'] = href
                if template is not None:
                    link_data['template'] = template
                result['links'].append(link_data)

        # The result may be empty if nothing matched
        return result

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    try:
        import urllib.request
        import urllib.parse

        # Normalise the resource format
        if handle.startswith("acct:"):
            resource = handle
        else:
            if "@" not in handle:
                return None
            resource = f"acct:{handle}"

        # Extract domain from the resource
        try:
            domain = resource.split(":", 1)[1].split("@", 1)[1]
        except Exception:
            return None

        # Build the webfinger URL
        url = f"https://{domain}/.well-known/webfinger?resource={urllib.parse.quote(resource, safe='')}"
        # Some services may support HTTP fallback
        http_url = f"http://{domain}/.well-known/webfinger?resource={urllib.parse.quote(resource, safe='')}"

        headers = {"Accept": "application/jrd+json, application/json"}
        request = urllib.request.Request(url, headers=headers)

        # Try HTTPS first, then fallback to HTTP
        try:
            with urllib.request.urlopen(request, timeout=5) as resp:
                if 200 <= resp.status < 300:
                    return resp.read().decode("utf-8")
        except Exception:
            # Fallback to HTTP
            request = urllib.request.Request(http_url, headers=headers)
            try:
                with urllib.request.urlopen(request, timeout=5) as resp:
                    if 200 <= resp.status < 300:
                        return resp.read().decode("utf-8")
            except Exception:
                pass

        return None
    except Exception:
        return None

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """Try to retrieve an RFC7033 webfinger document. Does not raise if it fails."""
    try:
        from urllib.request import Request, urlopen
        from urllib.error import URLError, HTTPError

        if not isinstance(handle, str) or not handle:
            return None
        if '@' not in handle:
            return None

        domain = handle.split('@', 1)[1]
        resource = f"acct:{handle}"
        url = f"https://{domain}/.well-known/webfinger?resource={resource}"

        req = Request(url, headers={'Accept': 'application/json'})
        with urlopen(req, timeout=5) as resp:
            if resp.status != 200:
                return None
            data = resp.read()
            if not data:
                return None
            return data.decode('utf-8')
    except Exception:
        # Any error (network, timeout, parsing, etc.) results in None
        return None

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    import json
    try:
        from urllib.request import urlopen, Request
        from urllib.error import URLError, HTTPError
        from urllib.parse import quote
    except Exception:
        raise ImportError("Required modules for webfinger request are missing")

    if not isinstance(handle, str) or '@' not in handle:
        raise ValueError("handle must be a string containing '@' (e.g., 'alice@example.com')")

    domain = handle.split('@', 1)[1]
    # Percent‑encode the entire resource to be safe
    resource = f"acct:{handle}"
    encoded_resource = quote(resource, safe='')
    url = f"https://{domain}/.well-known/webfinger?resource={encoded_resource}"

    # Prepare a user agent that browsers tend to accept
    req = Request(url, headers={"User-Agent": "Python Webfinger-client/1.0"})

    try:
        with urlopen(req, timeout=10) as resp:
            content_type = resp.headers.get("Content-Type", "")
            body = resp.read().decode(resp.headers.get_content_charset() or "utf-8")
            if "application/json" in content_type.lower():
                return json.loads(body)
            else:
                # Fallback: try JSON parsing even if content-type is not set correctly
                return json.loads(body)
    except (URLError, HTTPError) as err:
        # Return an empty dict on any network or HTTP error
        return {}
    except json.JSONDecodeError:
        # If parsing fails, return empty dict
        return {}
    except Exception:
        # Catch all other exceptions for safety
        return {}

def retrieve_and_parse_diaspora_webfinger(handle):
    """
