def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    # Ensure handle is in the form acct:username@domain
    if not handle.startswith('acct:'):
        if '@' in handle:
            acct_handle = 'acct:' + handle
        else:
            raise ValueError('handle must contain an "@" or be prefixed with "acct:"')
    else:
        acct_handle = handle

    # Extract host component from the handle
    try:
        _, host = acct_handle.split('@', 1)
    except ValueError:
        raise ValueError('invalid handle format: expected acct:user@host')

    # Build the WebFinger URL: https://{host}/.well-known/webfinger?resource={acct_handle}
    import urllib.parse
    encoded_resource = urllib.parse.quote(acct_handle, safe='')
    url = f'https://{host}/.well-known/webfinger?resource={encoded_resource}'

    # Retrieve the JSON document
    try:
        import urllib.request
        import ssl
        import json

        req = urllib.request.Request(url, headers={'Accept': 'application/json'})
        context = ssl._create_unverified_context()
        with urllib.request.urlopen(req, context=context) as response:
            if response.status != 200:
                raise ValueError(f'HTTP error {response.status} retrieving WebFinger for {handle}')
            raw = response.read()
            try:
                return json.loads(raw.decode('utf-8'))
            except json.JSONDecodeError as e:
                raise ValueError(f'Failed to parse WebFinger JSON: {e}')
    except Exception as exc:
        raise ValueError(f'Could not retrieve WebFinger for {handle}: {exc}')

