def retrieve_diaspora_host_meta(host):
    """
    Retrieve a remote Diaspora host-meta document.

    :arg host: Host to retrieve from
    :returns: ``XRD`` instance
    """
    try:
        import urllib.request
        import urllib.error
        import urllib.parse
        from xml.etree import ElementTree

        # Construct the well‑known host-meta URL
        if not host.startswith(("http://", "https://")):
            url = f"https://{host}/.well-known/host-meta"
        else:
            url = urllib.parse.urljoin(host.rstrip("/") + "/", ".well-known/host-meta")

        # Fetch the host‑meta XML
        with urllib.request.urlopen(url, timeout=10) as resp:
            if resp.status != 200:
                raise RuntimeError(f"HTTP {resp.status} received while retrieving {url}")
            xml_data = resp.read()

        # Try to use an XRD parser if available
        try:
            from XRD import XRD  # type: ignore
            return XRD.from_raw(xml_data)
        except Exception:
            # Fallback: return parsed ElementTree Element representing the XRD
            return ElementTree.fromstring(xml_data)

    except Exception as exc:
        raise RuntimeError(f"Failed to retrieve host‑meta from {host!r}: {exc}") from exc

def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    """Helper method to send a document via POST.

    Additional ``*args`` and ``**kwargs`` will be passed on to ``requests.post``.

    :arg url: Full url to send to, including protocol
    :arg data: Dictionary (will be form-encoded), bytes, or file-like object to send in the body
    :arg timeout: Seconds to wait for response (defaults to 10)
    :arg method: Method to use, defaults to post
    :returns: Tuple of status code (int or None) and error (exception class instance or None)
    """
    # Ensure we have a valid HTTP method
    method = method.lower()
    allowed_methods = {"get", "post", "put", "delete", "head", "options", "patch"}
    if method not in allowed_methods:
        raise ValueError(f"Unsupported HTTP method: {method!r}")

    try:
        import requests  # local import to avoid global dependency
        resp = requests.request(method, url, data=data, timeout=timeout, *args, **kwargs)
        return (resp.status_code, None)
    except Exception as e:
        return (None, e)

def dict_insert(dic, val, key, *keys):
    """insert a value of a nested key into a dictionary

    to insert value for a nested key, all ancestor keys should be given as
    method's arguments

    example:
      dict_insert({}, 'val', 'key1.key2'.split('.'))

    :param dic: a dictionary object to insert the nested key value into
    :param val: a value to insert to the given dictionary
    :param key: first key in a chain of key that will store the value
    :param keys: sub keys in the keys chain
    """
    if not isinstance(dic, dict):
        raise TypeError("dic must be a dictionary instance")
    chain = [key] + list(keys)
    current = dic
    for i, k in enumerate(chain):
        if i == len(chain) - 1:
            current[k] = val
        else:
            if k not in current or not isinstance(current[k], dict):
                current[k] = {}
            current = current[k]
    return dic

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type

    This function scans the directories in ``settings_dirs`` and returns
    a list of file names that match the ``spec_option`` pattern.  If
    ``spec_option`` is ``None`` or an empty string all files are
    returned.  The function is tolerant to missing directories and
    inaccessible files.
    """
    import os
    import fnmatch

    if settings_dirs is None:
        raise ValueError("settings_dirs must be an iterable of directory paths")
    if not hasattr(settings_dirs, '__iter__'):
        raise TypeError("settings_dirs must be an iterable (list, tuple, etc.)")

    result = []
    for dir_path in settings_dirs:
        if not isinstance(dir_path, (str, bytes)):
            raise TypeError("Each entry in settings_dirs must be a string path")
        if not os.path.isdir(dir_path):
            # Skip directories that do not exist or are not directories
            continue

        try:
            for entry in os.listdir(dir_path):
                full_path = os.path.join(dir_path, entry)
                if os.path.isfile(full_path):
                    if spec_option is None or spec_option == '':
                        result.append(entry)
                    else:
                        if fnmatch.fnmatchcase(entry, spec_option):
                            result.append(entry)
        except OSError:
            # Ignore errors such as permission issues and continue with next dir
            continue
    return result

def list_of_file_names(settings_dirs, spec_option):
    """Generate a list of file names from the given settings directories optionally filtered by file extension.

    Arguments:
        settings_dirs (Iterable[str]): A sequence of directory paths.
        spec_option (str or None): A file extension (e.g., '.ini') to filter the returned file names. If None or empty, return all file names.

    Returns:
        list[str]: A list of file names (with full path).

    Raises:
        TypeError: If ``settings_dirs`` is not an iterable of strings or ``spec_option`` is not a string or ``None``.
        FileNotFoundError: If any directory in ``settings_dirs`` does not exist or is not accessible.
    """
    import os

    # Validate inputs
    if not hasattr(settings_dirs, "__iter__") or isinstance(settings_dirs, (str, bytes)):
        raise TypeError(f"settings_dirs must be an iterable of strings, got {type(settings_dirs)!r}")

    if spec_option is not None and not isinstance(spec_option, (str, bytes)):
        raise TypeError(f"spec_option must be a string or None, got {type(spec_option)!r}")

    file_list = []

    for dir_path in settings_dirs:
        if not isinstance(dir_path, (str, bytes)):
            raise TypeError(f"Each directory path must be a string, got {type(dir_path)!r}")

        if not os.path.isdir(dir_path):
            raise FileNotFoundError(f"Directory not found: {dir_path!r}")

        try:
            for entry in os.listdir(dir_path):
                full_path = os.path.join(dir_path, entry)
                if os.path.isfile(full_path):
                    if spec_option:
                        if entry.endswith(spec_option):
                            file_list.append(full_path)
                    else:
                        file_list.append(full_path)
        except OSError as exc:
            raise FileNotFoundError(f"Unable to access directory {dir_path!r}: {exc}") from exc

    return file_list

