def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    if not isinstance(parser_dict, dict):
        raise ValueError("parser_dict must be a dict")
    # If the parser_dict contains an 'include' key with a dict value,
    # merge it into the current dict, with override on duplicates.
    includes = parser_dict.pop('include', None)
    if includes and isinstance(includes, dict):
        for key, value in includes.items():
            parser_dict[key] = value
    return parser_dict

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    try:
        includes = parser_dict.get("include")
        # nothing to do if no include directive
        if not includes:
            return parser_dict

        if not isinstance(includes, dict):
            raise ValueError("include directive must be a dict")

        # Ensure the object that owns group definitions is available
        if not hasattr(self, "_groups"):
            raise AttributeError("Spec object missing '_groups' attribute for include resolution")

        for grp_name, _ in includes.items():
            if not isinstance(grp_name, str):
                raise TypeError("Group name in include directive must be a string")

            if grp_name not in self._groups:
                raise KeyError(f"Included group '{grp_name}' is not defined in the specification")

            # Perform a shallow merge of the group's dict into the current parser_dict
            group_def = self._groups[grp_name]
            if not isinstance(group_def, dict):
                raise TypeError(f"Definition of group '{grp_name}' must be a dict")

            for key, val in group_def.items():
                # Do not overwrite an existing 'include' key; it will be removed later
                if key == "include":
                    continue
                if key in parser_dict and key != "include":
                    # Existing key; we choose to override with the included group's value
                    # If this behavior is undesirable, raise an exception instead
                    pass
                parser_dict[key] = val

        # Remove the include directive from the dictionary after processing
        parser_dict.pop("include", None)
        return parser_dict

    except Exception as exc:
        raise RuntimeError(f"Failed to resolve include groups: {exc}") from exc

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    # Grab and remove the directive so it does not remain in the output
    include_directive = parser_dict.pop('include', None)
    if include_directive is None:
        # Nothing to do
        return

    # Normalise the include directive to a dictionary.
    # Accept a dict or a list of string paths (future‑proof, but not processed here).
    if isinstance(include_directive, list):
        # Currently we only support explicit dictionaries.
        raise ValueError("`include` directive provided as a list; expected a dict defining group names to merge.")
    if not isinstance(include_directive, dict):
        raise ValueError("`include` directive must be a dict of group names to group definitions.")

    # Merge the included groups into the main parser dictionary.
    groups = parser_dict.setdefault('groups', {})
    for name, definition in include_directive.items():
        if not isinstance(name, str):
            raise ValueError(f"Group name must be a string, got {type(name).__name__}")
        if not isinstance(definition, dict):
            raise ValueError(f"Definition for group {name!r} must be a dict")
        if name in groups:
            # Duplicate group name, prefer raising an explicit error
            raise ValueError(f"Duplicate group name {name!r} while including into spec.")
        groups[name] = definition

    # The include directive is now fully resolved and has been removed from the spec.

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    # Walk through the dictionary, resolving any include directives
    for key, value in list(parser_dict.items()):
        if isinstance(value, dict):
            # Detect an include directive
            if "include" in value:
                include_name = value.pop("include")
                # The included group should be defined elsewhere in the same dictionary
                include_group = parser_dict.get(include_name)
                if isinstance(include_group, dict):
                    # Merge the included group's content into the current entry
                    for sub_key, sub_val in include_group.items():
                        if sub_key not in value:
                            value[sub_key] = sub_val
                else:
                    raise KeyError(
                        f"Include target '{include_name}' not found "
                        f"or is not a dictionary in the parser specification"
                    )
            # Recurse into nested dictionaries
            self._include_groups(value)
    return parser_dict

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    try:
        defaults = {}

        # Try to get spec directly from the element
        spec = getattr(self, "spec", None)

        # Fall back to the document-level spec if available
        if spec is None and hasattr(self, "doc"):
            spec = getattr(self.doc, "spec", None)

        # Finally, try a module-level or class-level spec if defined
        if spec is None and hasattr(self, "config"):
            spec = getattr(self.config, "spec", None)

        # Merge spec dict into defaults if it is a mapping
        if isinstance(spec, dict):
            defaults.update(spec)

        # Merge element-specific defaults (they override spec defaults)
        elem_defaults = getattr(self, "defaults", {})
        if isinstance(elem_defaults, dict):
            defaults.update(elem_defaults)

        return defaults

    except Exception as exc:  # pragma: no cover
        # Log the exception and return an empty dict to avoid breaking callers
        import logging
        logging.getLogger(__name__).warning(
            "Failed to resolve spec defaults: %s", exc
        )
        return {}

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    # Gather defaults from a spec dictionary if present
    try:
        spec_attr = getattr(self, 'spec', None)
    except Exception:
        spec_attr = None
    if isinstance(spec_attr, dict):
        spec_defaults = spec_attr.get('defaults')
        if isinstance(spec_defaults, dict):
            defaults.update(spec_defaults)

    # Fallback: inspect the class signature for default argument values
    try:
        import inspect
        sig = inspect.signature(type(self))
    except Exception:
        # If signature inspection fails, just return what we have so far
        return defaults

    for name, param in sig.parameters.items():
        if param.default is not inspect.Parameter.empty:
            # Do not override spec-driven defaults
            defaults.setdefault(name, param.default)

    return defaults

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    defaults = {}
    spec = getattr(self, 'spec', {})
    # The specification might provide a mapping of default values
    spec_defaults = {}
    if isinstance(spec, dict):
        spec_defaults = spec.get('defaults', {})
        if not isinstance(spec_defaults, dict):
            spec_defaults = {}
    # Prefer values from the spec when the current attribute is None
    for name, value in spec_defaults.items():
        if hasattr(self, name):
            current = getattr(self, name)
            if current is None:
                defaults[name] = value
    # If the element has an explicit method for retrieving defaults, use it
    if hasattr(self, 'get_default'):
        for name in getattr(self, 'args', []):
            if name not in defaults:
                try:
                    val = self.get_default(name)
                    if val is not None:
                        defaults[name] = val
                except Exception:  # pragma: no cover
                    pass
    # Fallback to environment variables, using upper‑cased keys
    import os
    for name in getattr(self, 'args', []):
        if name not in defaults:
            env_val = os.getenv(name.upper())
            if env_val is not None:
                defaults[name] = env_val
    return defaults

