def get_deprecated_args(self):
    """Return a dictionary mapping deprecated arguments to their replacements.

    The method attempts to gather deprecated argument mappings from both the
    instance and the class. It returns an empty dictionary if no mappings
    are found or an error occurs during retrieval.
    """
    deprecated = {}
    # Grab instance level mapping if defined
    if hasattr(self, "_deprecated_args"):
        try:
            deprecated.update(self._deprecated_args)
        except Exception:
            pass
    # Grab class level mapping if defined
    cls = self.__class__
    if hasattr(cls, "DEPRECATED_ARGS"):
        try:
            deprecated.update(cls.DEPRECATED_ARGS)
