        """Validates and prints the deprecated arguments.

        :param cli_args: the dict of arguments from cli
        :param answer_file_args:  the dict of arguments from files
        """
        # Basic type checking
        if not isinstance(cli_args, dict):
            raise TypeError("cli_args must be a dict")
        if answer_file_args is None:
            answer_file_args = {}
        elif not isinstance(answer_file_args, dict):
            raise TypeError("answer_file_args must be a dict")

        # Retrieve deprecated arguments and mapping if defined
        deprecated = getattr(self, "deprecated_args", set())
        mapping = getattr(self, "deprecation_map", {})

        # Helper to collect warnings
        warnings = []

        # Check CLI arguments
        for key in cli_args:
            if key in deprecated:
                new = mapping.get(key, "no alternative provided")
                warnings.append(f"Deprecated argument '{key}' used in CLI. Consider using '{new}'.")
        # Check answer file arguments
        for key in answer_file_args:
            if key in deprecated:
                new = mapping.get(key, "no alternative provided")
                # Avoid duplicate warnings if already reported from CLI
                if key in cli_args:
                    continue
                warnings.append(f"Deprecated argument '{key}' used in answer file. Consider using '{new}'.")
        # Print out warnings
        for w in warnings:
            print(w)

def validate_arg_deprecation(self, cli_args, answer_file_args):
        """Validates and prints the deprecated arguments.

        :param cli_args: the dict of arguments from cli
        :param answer_file_args:  the dict of arguments from files
        """
        try:
            if not isinstance(cli_args, dict):
                raise TypeError("cli_args must be a dictionary")
            if not isinstance(answer_file_args, dict):
                raise TypeError("answer_file_args must be a dictionary")

            # Merge dictionaries (cli_args take precedence over answer_file_args)
            merged_args = {**answer_file_args, **cli_args}

            # Retrieve a mapping of deprecated arguments to their replacements.
            # It is expected that `self` has an attribute called `deprecated_args`
            # mapping argument names to either a replacement name or None.
            deprecated_map = getattr(self, "deprecated_args", {})
            if not isinstance(deprecated_map, dict):
                deprecated_map = {}

            found_deprecated = []

            for arg_name, arg_val in merged_args.items():
                if arg_name in deprecated_map:
                    replacement = deprecated_map[arg_name]
                    msg = f"Argument '{arg_name}' is deprecated."
                    if replacement:
                        msg += f" Use '{replacement}' instead."
                    print(msg)
                    found_deprecated.append(arg_name)

            return found_deprecated

        except Exception as exc:
            # Print a helpful error message and re-raise for upstream handling
            print(f"Error validating deprecated arguments: {exc}")
            raise

def validate_arg_deprecation(self, cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    # Basic type checks
    if not isinstance(cli_args, dict):
        raise TypeError(f"cli_args must be a dict, got {type(cli_args).__name__}")
    if not isinstance(answer_file_args, dict):
        raise TypeError(f"answer_file_args must be a dict, got {type(answer_file_args).__name__}")

    # Merge the two argument sets, giving precedence to answer_file_args
    merged_args = {**cli_args, **answer_file_args}

    # Retrieve the class attribute containing deprecated arguments.
    # Subclasses are free to define DEPRECATED_ARGS as a dict mapping
    # argument names to a deprecation message or simply as a set/list of names.
    deprecated_attrs = getattr(self, "DEPRECATED_ARGS", {})
    if isinstance(deprecated_attrs, dict):
        deprecated_keys = set(deprecated_attrs.keys())
    else:
        # Treat any non-dict as an iterable of keys
        try:
            deprecated_keys = set(deprecated_attrs)
        except Exception:
            # Fallback: no deprecations available
            deprecated_keys = set()

    # If nothing to check, return early
    if not deprecated_keys:
        return

    # Prepare a simple logger; fall back to print if logging fails
    try:
        import logging
        logger = logging.getLogger(self.__class__.__name__)
        for key in merged_args:
            if key in deprecated_keys:
                # Build a helpful warning message
                msg = f"Argument '{key}' is deprecated."
                # Add specific message if available
                if isinstance(deprecated_attrs, dict):
                    detail = deprecated_attrs.get(key)
                    if detail:
                        msg += f" {detail}"
                logger.warning(msg)
    except Exception:
        # Any issue with logging – use a plain print fallback
        for key in merged_args:
            if key in deprecated_keys:
                print(f"WARNING: Argument '{key}' is deprecated.")

def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    if not isinstance(command_name, str):
        raise TypeError("command_name must be a string")

    # Try to locate a mapping of command names to option specs.
    # Common attribute names are 'parser_options', 'command_options', or 'options'.
    option_map = getattr(self, 'parser_options', None)
    if option_map is None:
        option_map = getattr(self, 'command_options', None)
    if option_map is None:
        option_map = getattr(self, 'options', None)

    if option_map is None:
        raise AttributeError(
            "Cannot find a command-to-options mapping on this object."
        )

    try:
        spec = option_map[command_name]
    except (KeyError, IndexError, TypeError):
        raise ValueError(
            f"Unknown command name '{command_name}'. Available commands: "
            f"{', '.join(map(str, option_map.keys()))}"
        )

    # Ensure the returned value is a list (or convertible to one).
    if isinstance(spec, list):
        return spec
    try:
        return list(spec)
    except TypeError:
        raise TypeError(
            f"Option specification for command '{command_name}' is not iterable."
        )

