    """
    if not isinstance(command_name, str):
        raise TypeError("command_name must be a string")
    # Try to fetch the command object from the registry / commands mapping
    # This logic may vary depending on the actual implementation of the CLI framework.
    try:
        command = self.commands[command_name]
    except AttributeError:
        # ``self.commands`` does not exist – try a generic lookup
        command = getattr(self, command_name, None)
    except KeyError:
        command = None

    if command is None:
        raise ValueError(f"Unknown command: {command_name!r}")

