        """Check if value of choice arguments is one of the available choices.

        :param args: The received arguments.

        Raises:
            ValueError: If an argument value does not match its allowed choices.
        """
        # Ensure args is a mapping; if not, nothing to validate
        if not isinstance(args, dict):
            return

        # Skip validation if self has no defined choice constraints
        choices = getattr(self, "choices", None)
        if not isinstance(choices, dict):
            return

        for key, value in args.items():
            if key not in choices:
                # No constraints defined for this key; skip
                continue

            # If the allowed choices are a list/tuple/set
            allowed = choices[key]
            if isinstance(allowed, (list, tuple, set)):
                if value not in allowed:
                    raise ValueError(
                        f"Invalid value '{value}' for argument '{key}'. "
                        f"Allowed values: {sorted(allowed)}."
                    )
            else:
                # Allow a single value or iterable pattern
                if value != allowed:
                    raise ValueError(
                        f"Invalid value '{value}' for argument '{key}'. "
                        f"Expected: {allowed}."
                    )

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.

    Raises:
        ValueError: If any argument value is outside its min/max constraints.

    Returns:
        bool: True if all arguments are within their limits.
    """
    # Attempt to get per-argument limits; fall back to general limits if defined.
    min_limits = getattr(self, 'min_per_arg', {}) or {}
    max_limits = getattr(self, 'max_per_arg', {}) or {}
    general_min = getattr(self, 'min', None)
    general_max = getattr(self, 'max', None)

    for name, value in args.items():
        # Skip validation for non-numeric values unless limits are explicitly set
        if value is None:
            continue

        # Resolve limits for this argument
        min_val = min_limits.get(name, general_min)
        max_val = max_limits.get(name, general_max)

        try:
            if min_val is not None and value < min_val:
                raise ValueError(f"Argument '{name}' value {value} below minimum {min_val}")
            if max_val is not None and value > max_val:
                raise ValueError(f"Argument '{name}' value {value} above maximum {max_val}")
        except TypeError:
            # Value is not comparable; ignore or log if needed
            pass

    return True

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    Parameters
    ----------
    args : any
        The received arguments.  If ``args`` is a container (e.g. list,
        tuple, set or dictionary) the length of the container is checked
        against the ``min_args`` and ``max_args`` attributes of the
        instance.  If the instance defines ``min_value`` and ``max_value``
        attributes, each scalar argument that is numeric will be checked
        to be within that range.
    """
    # Validate container size against min_args/max_args if defined
    if hasattr(self, "min_args") and hasattr(self, "max_args"):
        try:
            length = len(args)
        except Exception:
            raise TypeError("Provided 'args' must be a container type with measurable length.")
        if not (self.min_args <= length <= self.max_args):
            raise ValueError(
                f"Expected between {self.min_args} and {self.max_args} arguments, "
                f"got {length}."
            )

    # Validate individual numeric values against min_value/max_value if defined
    if hasattr(self, "min_value") and hasattr(self, "max_value"):
        for key, value in (args.items() if isinstance(args, dict) else enumerate(args)):
            if isinstance(value, (int, float)):
                if not (self.min_value <= value <= self.max_value):
                    raise ValueError(
                        f"Argument value {value} for key {key} is out of range "
                        f"({self.min_value} - {self.max_value})."
                    )
            else:
                continue  # ignore non-numeric values
    return True

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Helper to perform check against min/max constraints
    def _check_value(name, value, min_val, max_val):
        if min_val is not None and value < min_val:
            raise ValueError(
                f"Argument '{name}' has value {value}, "
                f"which is less than the minimum allowed {min_val}"
            )
        if max_val is not None and value > max_val:
            raise ValueError(
                f"Argument '{name}' has value {value}, "
                f"which is greater than the maximum allowed {max_val}"
            )

    # If args is None, nothing to validate
    if args is None:
        return True

    # Determine the container type of args. Allow int/float (scalar),
    # iterables (list, tuple, set, dict). Use dict items as name/value pairs.
    min_val = getattr(self, "min_value", None)
    max_val = getattr(self, "max_value", None)

    try:
        if isinstance(args, (int, float)):
            # Scalar value
            _check_value("value", args, min_val, max_val)

        elif isinstance(args, dict):
            # Mapping argument names to values
            for key, val in args.items():
                # Allow per-argument overrides of min/max
                spec = getattr(self, "arg_specs", {}).get(key, {})
                spec_min = spec.get("min", min_val)
                spec_max = spec.get("max", max_val)
                _check_value(key, val, spec_min, spec_max)

        else:
            # Assume any other iterable of values
            for idx, val in enumerate(args):
                name = f"arg_{idx}"
                _check_value(name, val, min_val, max_val)

    except Exception as exc:
        # Re‑raise with a clearer message
        raise ValueError(f"Minimum/Maximum value validation failed: {exc}") from exc

    return True

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Assume that the class defines optional attributes `min_args` and `max_args`
    # which specify the minimum and maximum allowed number of arguments.
    min_args = getattr(self, "min_args", None)
    max_args = getattr(self, "max_args", None)

    # args is expected to be a sequence, mapping, or any object with a length
    try:
        n = len(args)
    except (TypeError, AttributeError):
        raise TypeError("Expected args to be a sequence or a mapping with length")

    if min_args is not None and n < min_args:
        raise ValueError(
            f"Expected at least {min_args} arguments, got {n}"
        )
    if max_args is not None and n > max_args:
        raise ValueError(
            f"Expected at most {max_args} arguments, got {n}"
        )

def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                 spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    # Basic validation
    if not isinstance(subcommand, str):
        raise ValueError("subcommand must be a string")
    if not isinstance(type_name, str):
        raise ValueError("type_name must be a string")
    if not isinstance(option_name, str):
        raise ValueError("option_name must be a string")
    if spec_option is None:
        spec_option = {}
    if not isinstance(spec_option, dict):
        raise ValueError("spec_option must be a dict")

    # Merge the basic attributes with the specification options
    complex_type = {
        'subcommand': subcommand,
        'type_name': type_name,
        'option_name': option_name,
        **spec_option
    }

    return complex_type

def create_complex_argumet_type(self, subcommand, type_name, option_name, spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    # validate the required string parameters
    for param_name, param_val in [('subcommand', subcommand),
                                  ('type_name', type_name),
                                  ('option_name', option_name)]:
        if not isinstance(param_val, str) or not param_val:
            raise ValueError(f"{param_name!r} must be a non‑empty string")

    # ensure spec_option is a dict (it may be None)
    if spec_option is None:
        spec_option = {}
    elif not isinstance(spec_option, dict):
        raise TypeError("spec_option must be a dict or None")

    # internal simple representation of the complex argument type
    class ComplexType:
        __slots__ = ('subcommand', 'type_name', 'option_name', 'spec')

        def __init__(self, subcommand, type_name, option_name, spec):
            self.subcommand = subcommand
            self.type_name = type_name
            self.option_name = option_name
            self.spec = spec

        def __repr__(self):
            return (f"<ComplexType subcommand={self.subcommand!r} "
                    f"type_name={self.type_name!r} "
                    f"option_name={self.option_name!r} "
                    f"spec={self.spec!r}>")

    try:
        return ComplexType(subcommand, type_name, option_name, spec_option)
    except Exception as exc:
        raise RuntimeError(f"Error creating complex argument type: {exc}") from exc

def get_nested_custom_and_control_args(self, args):
        """Split input arguments to control nested and custom.

        Controls arguments: control the IR behavior. These arguments
            will not be put into the spec yml file
        Nested arguments: are used by the Ansible playbooks and will be put
            into the spec yml file.
        Custom arguments: Custom ansible variables to be used instead of the
            normal nested usage.

        :param args: the collected list of args.
        :return: (dict, dict): flat dicts (control_args, nested_args)
        """
        # Ensure we have a mapping to iterate over
        if isinstance(args, dict):
            items = args.items()
        else:
            try:
                items = dict(args).items()
            except Exception as exc:
                raise ValueError("args must be a dict or iterable of (key, value) pairs") from exc

        control_args = {}
        nested_args = {}

        for key, value in items:
            # If the key is a string and starts with 'control_' or contains
            # the word 'control' in any form, treat it as a control argument.
            # Otherwise, treat it as a nested (or custom) argument.
            if isinstance(key, str) and key.startswith("control_"):
                control_args[key] = value
            else:
                nested_args[key] = value

        return control_args, nested_args

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    # Defensive handling: args may be None, dict, list of tuples, or other iterable
    control_args = {}
    nested_args = {}

    if args is None:
        return control_args, nested_args

    # Determine if args is a mapping
    if isinstance(args, dict):
        items = list(args.items())
    else:
        # Try to iterate
        try:
            items = list(args)
        except Exception:
            raise TypeError(f"Expected a dict or iterable of (key, value) pairs, got {type(args).__name__}")

    # Define heuristics for control keys
    # Use a default set if the exception defines one; otherwise fall back to underscore prefix
    default_control_keys = getattr(self, 'CONTROL_KEYS', set())

    for item in items:
        # Validate item as a key-value pair
        if not (isinstance(item, (list, tuple)) and len(item) == 2):
            raise ValueError(f"Argument {item!r} is not a (key, value) pair.")
        key, value = item

        if not isinstance(key, str):
            raise TypeError(f"Argument key {key!r} must be a string, got {type(key).__name__}")

        # Decide whether this is a control argument
        is_control = False
        if default_control_keys:
            # If a specific set of control keys is defined, use that
            if key in default_control_keys:
                is_control = True
        else:
            # Use underscore prefix as fallback
            if key.startswith('_'):
                is_control = True

        if is_control:
            control_args[key] = value
        else:
            nested_args[key] = value

    return control_args, nested_args

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    if not isinstance(args, dict):
        raise TypeError(f"Expected dict for args, got {type(args).__name__}")

    control_args = {}
    nested_args = {}

    for key, value in args.items():
        if isinstance(key, str):
            # Custom logic: keys starting with '_' are treated as control.
            # Keys starting with 'custom_' are treated as nested to allow
            # custom ansible variables while still being part of nested args.
            if key.startswith('_'):
                control_args[key] = value
            elif key.startswith('custom_'):
                nested_args[key] = value
            else:
                nested_args[key] = value
        else:
            # If the key is not a string, place it in nested_args by default
            nested_args[key] = value

    return control_args, nested_args

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
           will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
           into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
           normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}

    # Handle empty or None input
    if not args:
        return control_args, nested_args

    # Normalise to iterable of (key, value) pairs
    if isinstance(args, dict):
        items = args.items()
    else:
        try:
            # Expect iterable of pairs – try unpacking
            items = list(args)
            if any(not isinstance(item, (list, tuple)) or len(item) != 2 for item in items):
                raise ValueError
        except Exception:
            raise TypeError("args must be a dict or an iterable of 2-tuples")

    for key, value in items:
        if not isinstance(key, str):
            # Skip non-string keys – they cannot be classified
            continue

        # Classify control args: keys that start with '_' or 'control_'
        if key.startswith('_') or key.lower().startswith('control_'):
            control_args[key] = value
        # Custom arguments: defined by 'custom_' prefix
        elif key.lower().startswith('custom_'):
            nested_args[key] = value
        else:
            # Default: nested args
            nested_args[key] = value

    return control_args, nested_args

@staticmethod
    def merge_extra_vars(vars_dict, extra_vars=None):
        """Extend ``vars_dict`` with ``extra-vars``

        :param vars_dict: Dictionary to merge extra-vars into
        :param extra_vars: List of extra-vars
        """
        if not isinstance(vars_dict, dict):
            raise TypeError("vars_dict must be a dictionary")
        if extra_vars is None:
            return vars_dict

        # if a single dict is provided, merge it directly
        if isinstance(extra_vars, dict):
            vars_dict.update(extra_vars)
            return vars_dict

        # otherwise expect an iterable of dicts or key=value strings
        if not hasattr(extra_vars, "__iter__"):
            raise TypeError("extra_vars must be a dict or an iterable of dicts/strings")

        import ast
        for item in extra_vars:
            if isinstance(item, dict):
                vars_dict.update(item)
            elif isinstance(item, str):
                # consider items like "key=value"
                if "=" not in item:
                    continue
                key, value = item.split("=", 1)
                # try to interpret the value as a literal
                try:
                    value = ast.literal_eval(value)
                except Exception:
                    # keep as string if evaluation fails
                    pass
                vars_dict[key] = value
            else:
                raise ValueError(f"Unsupported element type in extra_vars: {type(item)!r}")

        return vars_dict

def merge_extra_vars(cls, vars_dict, extra_vars=None):
        """Extend ``vars_dict`` with ``extra-vars``

