        # Nothing to merge
        if extra_vars is None:
            return vars_dict

        # Handle dict-like extra_vars
        if isinstance(extra_vars, dict):
            vars_dict.update(extra_vars)
            return vars_dict

        # Handle iterable of key/value pairs
        try:
            iterator = iter(extra_vars)
        except TypeError:
            raise TypeError(f"extra_vars must be None, a dict, or an iterable of key/value pairs, got {type(extra_vars).__name__}")

        for item in iterator:
            if not isinstance(item, (list, tuple)):
                raise TypeError(f"Each item in extra_vars must be a pair (key, value), got {type(item).__name__}")
            if len(item) != 2:
