                    cmd.append(flag)
            else:
                cmd.extend([flag, str(value)])

    # Add extra-vars if provided
    if extra_vars:
        try:
            json_str = json.dumps(extra_vars)
        except Exception as exc:
            raise ValueError("extra_vars could not be serialized to JSON") from exc
        cmd.extend(["--extra-vars", json_str])

    try:
        # Execute the command and capture output
        result = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            check=False  # handle errors manually
        )
    except FileNotFoundError as exc:
        raise RuntimeError("ansible-playbook command not found") from exc
    except Exception as exc:
        raise RuntimeError(f"Error while running ansible-playbook: {exc}") from exc

    # Raise a more informative exception if the command failed
    if result.returncode != 0:
