def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     workspace
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    cmd = ['ansible-playbook', playbook_path]

    # Add verbosity
    if verbose:
        if isinstance(verbose, int) and verbose > 0:
            cmd.append('-' + 'v' * verbose)
        else:
            cmd.append('-' + str(verbose))

    # Extra vars
    if extra_vars:
        # Convert dictionary into a space‑separated key=value string
        ev_str = ' '.join(f'{k}={v}' for k, v in extra_vars.items())
        cmd.extend(['--extra-vars', ev_str])

    # Additional ansible‑playbook arguments
    if ansible_args:
        for key, value in ansible_args.items():
            if isinstance(value, bool):
                if value:
                    cmd.append(key)          # flag style
            else:
                cmd.extend([key, str(value)])

    try:
        result = subprocess.run(
            cmd,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            check=True
        )
        return {
            'returncode': result.returncode,
            'stdout': result.stdout,
            'stderr': result.stderr
        }
    except subprocess.CalledProcessError as exc:
        raise RuntimeError(
            f"ansible-playbook failed with return code {exc.returncode}: "
            f"{exc.stderr}"
        ) from exc

def _run_playbook(cli_args, vars_dict, ir_workspace, ir_plugin):
    """Runs ansible cli with vars dict

    :param vars_dict: dict, Will be passed as Ansible extra-vars
    :param cli_args: the list  of command line arguments
    :param ir_workspace: An Infrared Workspace object represents the active
     workspace
    :param ir_plugin: An InfraredPlugin object of the current plugin
    :return: ansible results
    """
    import json, subprocess

    # Validate input types
    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dictionary")
    if not isinstance(cli_args, (list, tuple)):
        raise TypeError("cli_args must be a list or tuple of arguments")

    # Build the ansible-playbook command
    cmd = ["ansible-playbook"] + list(cli_args)

    # Add extra-vars if provided
    if vars_dict:
        try:
            extra_vars = json.dumps(vars_dict)
        except (TypeError, ValueError) as exc:
            raise ValueError(f"Unable to serialize vars_dict to JSON: {exc}") from exc
        cmd.extend(["--extra-vars", extra_vars])

    # Optionally add the inventory from the workspace, if available
    if ir_workspace and hasattr(ir_workspace, "inventory"):
        # Assume inventory is a string path or a list of paths
        inventory = ir_workspace.inventory
        if isinstance(inventory, (list, tuple)):
            for inv in inventory:
                cmd.extend(["-i", str(inv)])
        else:
            cmd.extend(["-i", str(inventory)])

    # Execute the command
    try:
        result = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            check=True,
        )
    except subprocess.CalledProcessError as e:
        # Log failure via the plugin, if possible
        if ir_plugin and hasattr(ir_plugin, "log_error"):
            ir_plugin.log_error(
                f"Ansible playbook failed (returncode {e.returncode}): {e.stderr}"
            )
        raise RuntimeError(
            f"Ansible playbook execution failed: {e.stderr}"
        ) from e

    # Log success via the plugin, if possible
    if ir_plugin and hasattr(ir_plugin, "log_info"):
        ir_plugin.log_info(
            f"Ansible playbook executed successfully (returncode {result.returncode})"
        )

    # Return a dictionary containing the key result information
    return {
        "stdout": result.stdout,
        "stderr": result.stderr,
        "returncode": result.returncode,
    }

