def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    # Basic validation of input types
    if not isinstance(path, str):
        raise TypeError(f"path must be a string, got {type(path).__name__}")
    if not isinstance(root, str):
        raise TypeError(f"root must be a string, got {type(root).__name__}")

    # Normalize root so it ends with the OS path separator
    import os
    sep = os.sep
    norm_root = root if root.endswith(sep) else root + sep

    # Ensure the path starts with the normalized root
    if not path.startswith(norm_root):
        # Try without the trailing separator
        if path.startswith(root):
            norm_root = root
        else:
            raise ValueError(f"Root '{root}' is not a prefix of path '{path}'")

    # Strip the root from the beginning of the path
    stripped = path[len(norm_root):]
    if not stripped or stripped == sep:
        raise ValueError(f"Removing root results in an empty or irrelevant path (original: '{path}', root: '{root}')")

    return stripped
